/// assert_eq!(sums.get("a"), Some(&6));
/// assert_eq!(sums.get("b"), Some(&9));
/// assert_eq!(sums.get("c"), Some(&10));
/// ```
pub fn sum_sequences<T, V>(mapping: &HashMap<T, V>) -> HashMap<T, i32>
where
    T: std::hash::Hash + Eq + std::fmt::Debug,
    V: IntoIterator<Item = i32>,
