use std::collections::HashMap;
use std::hash::Hash;

/// Sum each sequence in the input map and return a new map of sums.
///
/// K: identifier type (must be hashable + clonable)
/// V: numeric type (must support + and have a Default zero value)
fn sum_sequences<K, V>(input: &HashMap<K, Vec<V>>) -> HashMap<K, V>
where
    K: Eq + Hash + Clone,
    V: std::ops::Add<Output = V> + Default + Copy,
{
