```rust
use std::sync::Arc;
use chrono::NaiveDate;
use datafusion::prelude::*;
use datafusion::dataframe::DataFrame;
use datafusion::common::ScalarValue;
use datafusion::error::DataFusionError;

/// Filter `df` to retain only rows where column `var0` is between `date0` and `date1` (inclusive).
/// `date0` and `date1` must be "YYYY-MM-DD" strings. `df` is expected to have `var0` as Date32 type.
/// Returns a new DataFrame (Arc<dyn DataFrame>) on success.
pub fn filter_between_dates(
    df: Arc<dyn DataFrame>,
    var0: &str,
    date0: &str,
    date1: &str,
) -> datafusion::error::Result<Arc<dyn DataFrame>> {
    // Parse input dates (YYYY-MM-DD)
    let d0 = NaiveDate::parse_from_str(date0, "%Y-%m-%d")
        .map_err(|e| DataFusionError::Execution(format!("invalid date0 '{}': {}", date0, e)))?;
    let d1 = NaiveDate::parse_from_str(date1, "%Y-%m-%d")
        .map_err(|e| DataFusionError::Execution(format!("invalid date1 '{}': {}", date1, e)))?;

    // Convert to days since UNIX epoch (Date32)
    let epoch = NaiveDate::from_ymd_opt(1970, 1, 1)
        .expect("1970-01-01 should be a valid date");
    let days0 = (d0 - epoch).num_days() as i32;
    let days1 = (d1 - epoch).num_days() as i32;

    // Ensure low <= high (swap if necessary)
    let (low, high) = if days0 <= days1 { (days0, days1) } else { (days1, days0) };

    // Build expression: var0 >= low AND var0 <= high
    let expr = col(var0)
        .gt_eq(lit(ScalarValue::Date32(Some(low))))
        .and(col(var0).lt_eq(lit(ScalarValue::Date32(Some(high)))));

    // Apply filter
    df.filter(expr)
}
```

Notes:
- The function is inclusive: it keeps rows where var0 >= date0 and var0 <= date1.
- If your DataFrame stores dates as a timestamp type (e.g., Timestamp(Nanosecond, _)), convert the input date strings to the appropriate timestamp scalar (e.g., seconds or nanoseconds since epoch) and use ScalarValue::TimestampNanosecond(Some(ns), None) (or the matching precision) instead of ScalarValue::Date32.

