/// # Arguments
/// * `batch` - The RecordBatch containing the data
/// * `row_indices` - A slice of row indices to include in the average
/// * `col_names` - A slice of column names to include in the average
///
/// # Returns
/// * `Ok(f64)` - The computed average value
/// * `Err(String)` - Error message if something goes wrong
pub fn compute_average(
    batch: &RecordBatch,
    row_indices: &[usize],
    col_names: &[&str],
) -> Result<f64, String> {
    // Validate inputs
    if row_indices.is_empty() || col_names.is_empty() {
        return Err("Row indices and column names must not be empty".to_string());
    }

    // Get the schema to validate column names
    let schema = batch.schema();

    // Collect all values from specified columns and rows
    let mut values: Vec<f64> = Vec::new();

    for col_name in col_names {
        // Find column index
        let col_index = schema.index_of(col_name)
            .map_err(|_| format!("Column '{}' not found in dataset", col_name))?;

        // Get the column array
        let column = batch.column(col_index);

        // Try to cast to Float64Array
        let float_array = column
            .as_any()
            .downcast_ref::<Float64Array>()
            .ok_or_else(|| format!("Column '{}' is not a Float64 type", col_name))?;

        // Extract values for specified rows
        for &row_idx in row_indices {
            if row_idx >= column.len() {
                return Err(format!(
                    "Row index {} is out of bounds (max: {})",
                    row_idx,
                    column.len() - 1
                ));
            }

            if float_array.is_valid(row_idx) {
                values.push(float_array.value(row_idx));
            }
        }
    }

    // Check if we have any valid values
    if values.is_empty() {
        return Err("No valid values found for the specified rows and columns".to_string());
    }

    // Compute average
    let sum: f64 = values.iter().sum();
    let count = values.len() as f64;
    let average = sum / count;

    Ok(average)
}

