    loop {
        match parse_until_and_after_slash(remaining) {
            Ok((rest, Some(ch))) => {
                result.push(ch);
                remaining = rest;
            }
            Ok((rest, None)) => {
                remaining = rest;
            }
            Err(_) => break,
        }

        if remaining.is_empty() {
            break;
        }
    }

    result
