/// - `axis` is a 0-based axis index.
/// - Removal rule: an element with index `i` along the given axis is removed if `(i + 1) % step == 0`.
///
/// Returns an owned ArrayD with the elements removed, or an Err(String) on invalid inputs.
pub fn delete_every<T: Clone>(
    arr: &ArrayD<T>,
    step: usize,
    axis: usize,
) -> Result<ArrayD<T>, String> {
    if step == 0 {
        return Err("step must be >= 1".to_string());
    }
    if axis >= arr.ndim() {
        return Err("axis out of bounds".to_string());
    }

    let axis_len = arr.shape()[axis];
    let mut kept_slices: Vec<ArrayViewD<T>> = Vec::new();

    for i in 0..axis_len {
        // remove elements where (i+1) is divisible by step
        if (i + 1) % step == 0 {
            continue;
        }
        // index_axis removes the axis; insert_axis restores a length-1 axis so shapes match for concatenation
        let slice = arr.index_axis(Axis(axis), i).insert_axis(Axis(axis));
        kept_slices.push(slice.into_dyn());
    }

    if kept_slices.is_empty() {
        // construct an array with the same shape but axis length 0 (no elements required)
        let mut new_shape = arr.shape().to_vec();
        new_shape[axis] = 0;
        return ArrayD::from_shape_vec(IxDyn(&new_shape), Vec::<T>::new())
            .map_err(|e| e.to_string());
    }

    // concatenate the kept slices along the axis
    concatenate(Axis(axis), &kept_slices).map_err(|e| e.to_string())
}

