pub fn delete_every_nth<T: Clone + Default>(
    arr0: &ArrayD<T>,
    var0: usize,
    var1: usize,
) -> ArrayD<T> {
    assert!(var0 >= 1, "var0 must be >= 1");
    assert!(
        var1 < arr0.ndim(),
        "var1 must be less than the number of dimensions"
    );

    let shape = arr0.shape();
    let dim_size = shape[var1];

    // Calculate new dimension size after removing every var0-th element
    let new_dim_size = dim_size - (dim_size / var0);

    // Create new shape
    let mut new_shape: Vec<usize> = shape.to_vec();
    new_shape[var1] = new_dim_size;

    // Create output array
    let mut result = ArrayD::<T>::default(new_shape.clone());

    // Calculate strides for iteration
    let strides = compute_strides(shape);
    let new_strides = compute_strides(&new_shape);

    // Iterate over all elements of the output array
    for flat_idx in 0..result.len() {
        // Convert flat index to multi-dimensional indices
        let mut indices = vec![0usize; shape.len()];
        let mut remaining = flat_idx;

        for d in (0..shape.len()).rev() {
            indices[d] = remaining / new_strides[d];
            remaining %= new_strides[d];
