        indices[var1] = original_idx;

        // Get value from input array
        let src_flat_idx = indices_to_flat(&indices, strides);
        let value = arr0.as_slice().unwrap()[src_flat_idx].clone();

        // Set value in result array
        result.as_slice_mut().unwrap()[flat_idx] = value;
    }

    result
}

/// Compute strides for a given shape
fn compute_strides(shape: &[usize]) -> Vec<usize> {
    let mut strides = vec![1usize; shape.len()];
    for i in (0..shape.len() - 1).rev() {
        strides[i] = strides[i + 1] * shape[i + 1];
    }
    strides
}

/// Convert multi-dimensional indices to flat index
fn indices_to_flat(indices: &[usize], strides: &[usize]) -> usize {
    indices.iter().zip(strides.iter()).map(|(i, s)| i * s).sum()
}

/// Adjust an index along the dimension to account for removed elements
fn adjust_index(index: usize, var0: usize) -> usize {
    // For each group of var0 elements, we remove the last one
    // So we need to find the original index that maps to this new index
    let groups = index / (var0 - 1);
    let remainder = index % (var0 - 1);
    groups * var0 + remainder
}

