        return Err("Cannot produce duplicates in a sequence of length 1");
    }

    let mut rng = thread_rng();
    // Generate var0-1 random values first.
    let mut v: Vec<i32> = Vec::with_capacity(var0);
    for _ in 0..(var0 - 1) {
        // pick random values in some range, e.g. 0..1000
        v.push(rng.gen_range(0..1000));
    }

    // Pick one existing element and duplicate it to guarantee at least one duplicate.
    let dup_idx = rng.gen_range(0..v.len());
    let dup_val = v[dup_idx];
    v.push(dup_val);

    // Shuffle so the duplicate isn't necessarily at the end.
    v.shuffle(&mut rng);

    Ok(v)
