use toml::Value;

/// Count the total number of key-value pairs in a TOML value,
/// including those at any nested level.
fn count_key_value_pairs(value: &Value) -> usize {
    match value {
        Value::Table(table) => {
            // Count all key-value pairs in this table
            let mut count = table.len();

            // Recursively count nested key-value pairs
            for v in table.values() {
                count += count_key_value_pairs(v);
            }

            count
        }
        Value::Array(array) => {
            // For arrays, recursively count key-value pairs in each element
            let mut count = 0;
            for item in array {
                count += count_key_value_pairs(item);
            }
            count
        }
        // Scalar values (string, integer, float, boolean, datetime) don't contain nested pairs
        _ => 0,
    }
}

