use oolars::{Chunks, Workbook, WorkbookError};

/// Reorders the rows of a worksheet by the values in the "name" column
/// according to the specified sequence.
///
/// # Arguments
/// * `wb` - A mutable reference to the Workbook containing the worksheet
/// * `sheet_name` - The name of the worksheet to reorder
/// * `name_column` - The column index (1-based) containing the names to sort by
/// * `order_sequence` - A vector of values that defines the desired order
///
/// # Returns
/// Result<(), WorkbookError> - Returns Ok if successful, Err otherwise
pub fn reorder_rows_by_name_sequence(
    wb: &mut Workbook,
    sheet_name: &str,
    name_column: usize,
    order_sequence: Vec<String>,
) -> Result<(), WorkbookError> {
    // Get the worksheet
    let sheet = wb.sheet_by_name(sheet_name)
        .ok_or(WorkbookError::SheetNotFound(sheet_name.to_string()))?;

    // Get all rows from the name column
    let name_values: Vec<String> = sheet
        .column(name_column)
        .map(|cell| cell.value().to_string())
        .collect();

    // Create a map from value to its index in the order sequence
    let mut order_map = std::collections::HashMap::new();
    for (index, value) in order_sequence.iter().enumerate() {
        order_map.insert(value, index);
    }

    // Create a vector of tuples containing (original index, order value)
    let mut rows_with_order: Vec<(usize, Option<usize>)> = (0..name_values.len())
        .map(|i| {
            let value = &name_values[i];
            let order = order_map.get(value).copied();
            (i, order)
        })
        .collect();

    // Sort the rows based on the order sequence
    rows_with_order.sort_by(|a, b| {
        match (a.1, b.1) {
            (Some(a_order), Some(b_order)) => a_order.cmp(&b_order),
            (Some(_), None) => std::cmp::Ordering::Less,
            (None, Some(_)) => std::cmp::Ordering::Greater,
            (None, None) => a.0.cmp(&b.0),
        }
    });

    // Extract the new order of row indices
    let new_order: Vec<usize> = rows_with_order.iter().map(|(i, _)| *i).collect();

    // Reorder the rows in the worksheet
    let mut new_sheet = Workbook::new();
    let new_sheet_name = format!("{}_{}", sheet_name, "temp");

    // Copy all columns to the new sheet
    for col in 1..=sheet.column_count() {
        for row in 1..=sheet.row_count() {
            let cell = sheet.cell(row, col);
            new_sheet.sheet_by_name(&new_sheet_name)
                .unwrap()
                .set_cell(row, col, cell.value().clone());
        }
    }

    // Move rows according to the new order
    for (new_row, &old_row) in new_order.iter().enumerate() {
        for col in 1..=sheet.column_count() {
            let cell = sheet.cell(old_row + 1, col);
            new_sheet.sheet_by_name(&new_sheet_name)
                .unwrap()
                .set_cell(new_row + 1, col, cell.value().clone());
        }
    }

    // Replace the original sheet with the reordered one
    wb.remove_sheet(sheet_name)?;
    wb.add_sheet(new_sheet.sheet_by_name(&new_sheet_name).unwrap())?;

    Ok(())
}

// Example usage:
fn main() -> Result<(), WorkbookError> {
