use polars::prelude::*;
use std::collections::HashMap;

/// Reorder rows of `df` according to the order given in `name_order`.
/// - `df` must contain a UTF8 column named "name".
/// - Rows with names not present in `name_order` are placed after the listed names,
///   preserving their original relative order.
///
/// Returns a new DataFrame sorted as requested.
pub fn reorder_rows_by_name_order(df: &DataFrame, name_order: &[&str]) -> PolarsResult<DataFrame> {
    // Build lookup map: name -> rank index (0-based)
    let order_map: HashMap<&str, i64> = name_order
        .iter()
        .enumerate()
        .map(|(i, &s)| (s, i as i64))
        .collect();

    // Ensure "name" column exists and is Utf8
    let name_col = df.column("name")?;
    let utf8 = name_col.utf8()?;

    let n = df.height() as i64;

    // Map names to order indices; names not found -> large value to push them to the end.
    // Also build an original index to preserve relative order among ties.
    let mut order_vals: Vec<i64> = Vec::with_capacity(n as usize);
    let mut orig_idx_vals: Vec<i64> = Vec::with_capacity(n as usize);

    for (i, opt_name) in utf8.into_iter().enumerate() {
        let idx = match opt_name {
            Some(s) => order_map.get(s).copied().unwrap_or(i64::MAX / 2),
            None => i64::MAX / 2, // treat nulls as "not found"
        };
        order_vals.push(idx);
        orig_idx_vals.push(i as i64);
    }

    let order_series = Series::new("__order_idx", order_vals);
    let orig_idx_series = Series::new("__orig_idx", orig_idx_vals);

    // Clone df, attach helper columns, sort by them, then drop helpers.
    let mut df2 = df.clone();
    df2.with_column(order_series)?;
    df2.with_column(orig_idx_series)?;

    // Sort first by order index, then by original index to preserve relative order for ties.
    let df_sorted = df2.sort(&["__order_idx", "__orig_idx"], &[false, false])?;

    // Drop helper columns and return
    let df_final = df_sorted.drop("__order_idx")?.drop("__orig_idx")?;
    Ok(df_final)
}

