        .into_iter()
        .enumerate()
        .map(|(i, idx)| (i, idx))
        .collect();

    indexed.sort_by_key(|(original_idx, _)| {
        name_series
            .get(*original_idx)
            .and_then(|name| order_map.get(name).copied())
            .unwrap_or(usize::MAX)
    });

    let final_indices: Vec<u32> = indexed.iter().map(|(_, idx)| *idx).collect();
    df.take(&final_indices)
}
