use regex_automata::{Automaton, RegexBuilder};
use regex_automata::regex::Regex;

/// Finds all overlapping matches of pattern in text using regex-automata
///
/// # Arguments
/// * `pattern` - The regex pattern to search for
/// * `text` - The text to search within
///
/// # Returns
/// A vector of (start, end) index pairs representing all matches (including overlapping ones)
pub fn find_overlapping_matches(pattern: &str, text: &str) -> Vec<(usize, usize)> {
    // Build the regex automaton
    let automaton = RegexBuilder::new(pattern)
        .build()
        .expect("Failed to build regex automaton");

    // Convert to NFA (deterministic or non-deterministic)
    let nfa = automaton.to_nfa();

    // Find all matches
    let mut matches = Vec::new();

    // Iterate through the text to find all matches
    let mut state = nfa.initial_state();
    let mut pos = 0;
    let text_bytes = text.as_bytes();

    while pos < text_bytes.len() {
        // Process current character
        let current_char = text_bytes[pos];
        let mut new_states = Vec::new();

        // Transition from current state
        for state in state {
            let transitions = nfa.transitions(state);
            for (c, next_state) in transitions {
                if c == current_char {
                    new_states.push(*next_state);
                }
            }
        }

        // If we have accepting states, record the match
        if new_states.iter().any(|s| nfa.is_accepting(*s)) {
            // Find the earliest accepting state to get the earliest match
            let earliest_accepting = new_states.iter()
                .min_by_key(|s| nfa.accepting_positions(*s).min())
                .unwrap();

            let start_pos = nfa.accepting_positions(*earliest_accepting).min().unwrap();
            let end_pos = pos + 1;

            matches.push((start_pos, end_pos));
        }

        // Move to next state
        state = new_states;
        pos += 1;
    }

    matches
}

