use duckdb::{Connection, Result};

/// Counts records for each distinct combination of values in specified columns.
///
/// # Arguments
///
/// * `conn` - A DuckDB connection
/// * `table_name` - The name of the table to query (e.g., "df")
/// * `key_columns` - A slice of column names to group by
///
/// # Returns
///
/// A vector of tuples where each tuple contains:
/// - A vector of column values representing the distinct combination
/// - The count of records for that combination
///
/// # Example
///
/// ```ignore
/// let counts = count_by_key_combination(
///     &conn,
///     "df",
///     &["category", "region"]
/// )?;
///
/// for (keys, count) in counts {
///     println!("{:?}: {}", keys, count);
/// }
/// ```
pub fn count_by_key_combination(
    conn: &Connection,
    table_name: &str,
    key_columns: &[&str],
) -> Result<Vec<(Vec<String>, i64)>> {
    if key_columns.is_empty() {
        return Err(duckdb::Error::InvalidParameterValue(
            "key_columns cannot be empty".to_string(),
        ));
    }

    // Build the SELECT and GROUP BY clause
    let columns_str = key_columns.join(", ");
    let query = format!(
        "SELECT {}, COUNT(*) as count FROM {} GROUP BY {} ORDER BY count DESC",
        columns_str, table_name, columns_str
    );

    let mut stmt = conn.prepare(&query)?;
    let mut rows = stmt.query([])?;

    let mut results = Vec::new();

    while let Some(row) = rows.next()? {
        let mut key_values = Vec::new();

        // Extract the values for each key column
        for (idx, _col) in key_columns.iter().enumerate() {
            let value: String = row.get(idx)?;
            key_values.push(value);
        }

        // Extract the count (last column)
        let count: i64 = row.get(key_columns.len())?;

        results.push((key_values, count));
    }

    Ok(results)
}

