/// Determines if a list of text entries contains at least one element 
/// that matches any of the provided regular expression patterns.
///
/// # Arguments
/// * `entries` - A slice of text entries to search through
/// * `patterns` - A slice of regular expression pattern strings
///
/// # Returns
/// * `Ok(true)` if at least one entry matches any pattern
/// * `Ok(false)` if no entries match any pattern
/// * `Err` if any regex pattern is invalid
///
/// # Example
/// ```
/// let entries = vec!["hello123", "world", "test456"];
/// let patterns = vec![r"\d+", r"world"];
/// assert!(contains_regex_match(&entries, &patterns).unwrap());
/// ```
fn contains_regex_match(
    entries: &[&str],
    patterns: &[&str],
) -> Result<bool, fancy_regex::Error> {
    // Compile all patterns first to validate them
    let compiled_patterns: Result<Vec<Regex>, _> = 
        patterns.iter().map(|p| Regex::new(p)).collect();

    let compiled_patterns = compiled_patterns?;

    // Check if any entry matches any pattern
    for entry in entries {
        for pattern in &compiled_patterns {
            if pattern.is_match(entry)? {
                return Ok(true);
            }
        }
    }

    Ok(false)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Example 1: Match found
    let entries1 = vec!["apple", "banana123", "cherry"];
    let patterns1 = vec![r"\d+", r"^cherry$"];
    match contains_regex_match(&entries1, &patterns1) {
        Ok(result) => println!("Example 1 - Match found: {}", result),
        Err(e) => println!("Example 1 - Error: {}", e),
    }

    // Example 2: No match found
    let entries2 = vec!["apple", "banana", "cherry"];
    let patterns2 = vec![r"\d+", r"xyz"];
    match contains_regex_match(&entries2, &patterns2) {
        Ok(result) => println!("Example 2 - Match found: {}", result),
        Err(e) => println!("Example 2 - Error: {}", e),
    }

    // Example 3: Using fancy_regex features (lookahead)
    let entries3 = vec!["test123", "hello"];
    let patterns3 = vec![r"(?=.*\d)test"];
    match contains_regex_match(&entries3, &patterns3) {
        Ok(result) => println!("Example 3 - Match found with lookahead: {}", result),
        Err(e) => println!("Example 3 - Error: {}", e),
    }

    Ok(())
}
```

