use arrow::array::Array;
use arrow::record_batch::RecordBatch;

fn extract_columns_as_lists(batch: &RecordBatch) -> Vec<Vec<String>> {
    let mut result = Vec::new();

    for i in 0..batch.num_columns() {
        let column = batch.column(i);
        let field = &batch.schema().field(i);
        let column_name = field.name().clone();

        let mut column_list = vec![column_name];

        // Convert array values to strings
        for j in 0..column.len() {
            if column.is_null(j) {
                column_list.push("null".to_string());
            } else {
                // Convert the value to string representation
                let value_string = format_array_value(column, j);
                column_list.push(value_string);
            }
        }

        result.push(column_list);
    }

    result
}

