    // Extend with placeholder values (cloning the last element)
    let placeholder = lst0[original_len - 1].clone();
    lst0.resize(new_len, placeholder);

    // Shift elements from the insertion point to the right
    for i in (var0..original_len).rev() {
        lst0[i + lst1.len()] = lst0[i].clone();
