/// # Arguments
/// * `ctx` - DataFusion session context
/// * `table_name` - Name of the table to filter
///
/// # Returns
/// * `Result<RecordBatch>` - Filtered records as a RecordBatch
pub async fn filter_highest_c_per_ab(
    ctx: &SessionContext,
    table_name: &str,
) -> Result<RecordBatch> {
    // Create a SQL query that:
    // 1. Ranks records within each (A, B) group by C in descending order
    // 2. Keeps only records with rank = 1 (highest C value)
    let query = format!(
        r#"
        SELECT A, B, C
        FROM (
            SELECT 
                A, 
                B, 
                C,
                ROW_NUMBER() OVER (PARTITION BY A, B ORDER BY C DESC) as rn
            FROM {}
        )
        WHERE rn = 1
        ORDER BY A, B
