        table_name
    );

    // Execute the query
    let df = ctx.sql(&query).await?;
    let batches = df.collect().await?;

    // Combine all record batches into a single batch
    if batches.is_empty() {
        // Return empty batch with correct schema
        return Ok(batches[0].clone());
    }

    Ok(batches.into_iter().next().unwrap_or(batches[0].clone()))
