```rust
use ndarray::{Array2, Axis};

/// Normalize each row of `input_data` so that each row sums to 1.0.
/// Returns an error if any row has a sum of zero.
pub fn normalize_rows(input_data: &Array2<f64>) -> Result<Array2<f64>, String> {
    // Compute row sums: yields a 1-D array with length = number of rows
    let row_sums = input_data.sum_axis(Axis(1));

    // Fail if any row sum is zero (can't normalize)
    if row_sums.iter().any(|&s| s == 0.0) {
        return Err("One or more rows have zero sum and cannot be normalized.".to_string());
    }

    // Broadcast the row_sums (shape [nrows] -> [nrows, 1]) and divide
    let normalized = input_data / &row_sums.insert_axis(Axis(1));
    Ok(normalized)
}

#[cfg(test)]
mod tests {
