    use ndarray::array;

    #[test]
    fn test_normalize_rows() {
        let a = array![
            [1.0, 1.0, 2.0],
            [0.5, 0.5, 0.0]
        ];
        let normalized = normalize_rows(&a).unwrap();
        // First row sums to 4.0 -> [0.25, 0.25, 0.5]
        // Second row sums to 1.0 -> [0.5, 0.5, 0.0]
        let expected = array![
            [0.25, 0.25, 0.5],
            [0.5,  0.5,  0.0]
        ];
        assert!((&normalized - &expected).mapv(f64::abs).iter().all(|&d| d < 1e-12));
    }
}
