    let row_sums = input_data.sum_axis(ndarray::Axis(1));

    // Check for zero sums to avoid division by zero
    if row_sums.iter().any(|&sum| sum == 0.0) {
        panic!("Cannot normalize: one or more rows have a sum of zero");
    }

    // Normalize each row by dividing by its sum
    // We need to reshape row_sums to be a column vector for broadcasting
    let row_sums_col = row_sums.insert_axis(ndarray::Axis(1));

    // Divide each element by its row sum
    input_data / &row_sums_col
}

// Example usage
fn main() {
    // Create a sample 2D array
    let data = Array2::from_shape_vec((3, 4), vec![
        1.0, 2.0, 3.0, 4.0,
