use ndarray::{Array2, ArrayView1, s};

/// Normalizes a 2D array by dividing each row by its sum,
/// so that each row's entries sum to exactly 1.
///
/// # Arguments
/// * `input_data` - A 2D ndarray where each row will be normalized
///
/// # Returns
