```rust
use multiset::MultiSet;

fn unique_elements<T: Eq + std::hash::Hash>(elements: &[T]) -> Vec<T> 
where 
    T: Clone,  // Requires Clone to output the same type
{
    // Count the occurrences of each element
    let mut counts = MultiSet::new();
    for element in elements {
        counts.insert(element.clone());
    }

    // Collect only the elements that appear exactly once
    elements
        .iter()
        .filter(|&element| counts.count(element) == 1)
        .cloned()
        .collect()
}

fn main() {
    let input = vec![1, 2, 2, 3, 4, 3, 5];
    let result = unique_elements(&input);
    println!("{:?}", result); // Output should be [1, 4, 5]
}
```

