```rust
use ndarray::{Array1, ArrayView1};

/// Assigns ranks to elements in a list based on their values.
///
/// The function sorts the list once, then iterates over the original list to assign ranks.
/// If there are duplicate values, the rank will be the same for these values, and the next rank will be skipped.
///
/// # Arguments
///
/// * `lst0` - The input list of values.
///
/// # Returns
///
/// A list of ranks corresponding to the input list.
fn assign_ranks(lst0: ArrayView1<f64>) -> Array1<f64> {
    // Clone the input list to sort it without modifying the original.
    let mut sorted_lst = lst0.to_owned();
    sorted_lst.sort_unstable();

    // Initialize an empty array to store the ranks.
    let mut ranks = Array1::zeros(lst0.len());

    // Initialize the current rank.
    let mut current_rank = 1.0;

    // Initialize the index of the last seen value in the sorted list.
    let mut last_idx = 0;

    // Iterate over the original list.
    for (idx, &val) in lst0.iter().enumerate() {
        // Find the position of the current value in the sorted list.
        let mut pos = last_idx;
        while pos < sorted_lst.len() && sorted_lst[pos] < val {
            pos += 1;
        }

        // If the current value is not the same as the previous one, update the rank.
        if pos > last_idx {
            current_rank = (pos as f64) + 1.0;
        }

        // Assign the rank to the current element.
        ranks[idx] = current_rank;

        // Update the index of the last seen value.
        last_idx = pos;
    }

    ranks
}

fn main() {
    // Example usage.
    let lst0 = Array1::from(vec![5.0, 2.0, 8.0, 2.0, 1.0]);
    let ranks = assign_ranks(lst0.view());
    println!("{:?}", ranks);
}
