    }

    // Create index-value pairs and sort by value
    let mut indexed_values: Vec<(usize, f64)> = lst0.iter().enumerate().map(|(i, &v)| (i, v)).collect();
    indexed_values.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal));

    // Assign ranks and handle ties
    let mut ranks = vec![0.0_f64; n];
    let mut i = 0;

    while i < n {
        let mut j = i;
        // Find all elements with the same value
        while j < n && indexed_values[j].1 == indexed_values[i].1 {
            j += 1;
        }

        // Calculate average rank for tied elements
        let avg_rank = (i + j - 1) as f64 / 2.0 + 1.0; // 1-based ranking

        // Assign the same rank to all tied elements
        for k in i..j {
            ranks[indexed_values[k].0] = avg_rank;
        }

        i = j;
    }

    Array1::from(ranks)
}

