        a.1.partial_cmp(&b.1)
            .unwrap_or(Ordering::Equal)
    });

    // Create result array
    let mut ranks = Array1::zeros(n);

    // Assign ranks based on sorted order
    for (rank, (original_idx, _)) in indexed.iter().enumerate() {
        ranks[*original_idx] = rank + 1; // 1-indexed ranks
    }

    ranks
}

fn main() {
    use ndarray::arr1;

    // Example usage
    let lst0 = arr1(&[3.5, 1.2, 4.8, 1.2, 2.3]);
    let ranks = assign_ranks(&lst0);

    println!("Original list: {:?}", lst0);
    println!("Ranks:        {:?}", ranks);
    // Output: Original list: [3.5, 1.2, 4.8, 1.2, 2.3]
    //         Ranks:        [4, 1, 5, 1, 3]  (handles ties by assigning same rank)
