```rust
use linked_hash_map::LinkedHashMap;
use std::hash::Hash;

/// Reorder a collection of items so they appear in the sequence defined by `order`.
/// - `items`: any iterable of items (consumed).
/// - `order`: iterable of keys specifying the desired ordering.
/// - `id_of`: function to extract the item's identifier (key).
///
/// Items whose id appears in `order` are emitted in the order of `order`.
/// Any remaining items (ids not listed in `order`) are appended in their
/// original input order. Supports multiple items with the same id.
pub fn reorder_by_ids<T, K, I, J, F>(items: I, order: J, id_of: F) -> Vec<T>
where
    I: IntoIterator<Item = T>,
    J: IntoIterator<Item = K>,
    K: Eq + Hash + Clone,
    F: Fn(&T) -> K,
{
    // Group items by id while preserving the insertion order of ids encountered.
    let mut map: LinkedHashMap<K, Vec<T>> = LinkedHashMap::new();
    for item in items {
        let key = id_of(&item);
        map.entry(key).or_insert_with(Vec::new).push(item);
    }

    // Emit items in the requested order, removing them from the map as we go.
    let mut result = Vec::new();
    for key in order {
        if let Some(group) = map.remove(&key) {
            result.extend(group);
        }
    }

    // Append any remaining items in their original insertion order.
    for (_k, group) in map.into_iter() {
        result.extend(group);
    }

    result
}

fn main() {
    #[derive(Debug)]
    struct Item { id: u32, name: &'static str }

    let items = vec![
        Item { id: 3, name: "c" },
        Item { id: 1, name: "a" },
        Item { id: 2, name: "b" },
        Item { id: 4, name: "d" },
    ];

    let order = vec![1, 2, 3];

    let reordered = reorder_by_ids(items, order, |it: &Item| it.id);
    for it in reordered {
        println!("{:?}", it);
    }
    // Output order: id 1, 2, 3, then remaining id 4
}
