pub fn reorder_by_id<T, Id: Clone + Eq + Hash>(
    items: Vec<T>,
    id_order: &[Id],
    get_id: impl Fn(&T) -> Id,
) -> Vec<T> {
    // Build a map from identifier to item for O(1) lookup
    let mut item_map: LinkedHashMap<Id, T> = LinkedHashMap::new();

    for item in items {
        let id = get_id(&item);
        item_map.insert(id, item);
    }

    // Reorder items according to id_order
    let mut result = Vec::with_capacity(id_order.len());

    for id in id_order {
        // Remove and take ownership of the item from the map
        let item = item_map
            .remove(id)
            .unwrap_or_else(|| panic!("Identifier {:?} not found in items", id));
        result.push(item);
    }

    result
