# Rust Function to Reorder Items by Identifier Sequence

```rust
use linked_hash_map::LinkedHashMap;

/// Reorders a collection of items based on a sequence of identifiers.
/// 
/// # Arguments
/// * `items` - A vector of items, each with an identifier
/// * `id_sequence` - A vector defining the desired order by identifiers
/// * `id_fn` - A function that extracts the identifier from an item
/// 
/// # Returns
/// A vector of items reordered according to `id_sequence`. Items whose
/// identifiers are not in `id_sequence` are appended at the end.
/// 
/// # Example
/// ```
/// #[derive(Clone, Debug, PartialEq)]
/// struct Item {
///     id: u32,
///     name: String,
/// }
/// 
/// let items = vec![
///     Item { id: 3, name: "C".to_string() },
///     Item { id: 1, name: "A".to_string() },
///     Item { id: 2, name: "B".to_string() },
/// ];
/// 
/// let sequence = vec![1, 2, 3];
/// let reordered = reorder_by_identifier_sequence(items, sequence, |item| item.id);
/// 
/// assert_eq!(reordered[0].id, 1);
/// assert_eq!(reordered[1].id, 2);
/// assert_eq!(reordered[2].id, 3);
/// ```
pub fn reorder_by_identifier_sequence<T, ID>(
    items: Vec<T>,
    id_sequence: Vec<ID>,
    id_fn: fn(&T) -> ID,
) -> Vec<T>
where
    ID: Clone + Eq + std::hash::Hash,
{
    // Create a map from identifiers to items for O(1) lookup
    let mut item_map: LinkedHashMap<ID, T> = LinkedHashMap::new();
    for item in items {
        item_map.insert(id_fn(&item).clone(), item);
    }

    let mut result = Vec::new();

    // First, add items in the order specified by id_sequence
    for id in id_sequence {
        if let Some(item) = item_map.remove(&id) {
            result.push(item);
        }
    }

    // Then, append any remaining items that weren't in id_sequence
    for (_, item) in item_map.into_iter() {
        result.push(item);
    }

    result
}

#[cfg(test)]
