/// * `categorical_cols` - Names of columns to one-hot encode (None to encode all discrete columns)
///
/// # Returns
/// A new DataFrame with one-hot encoded columns
pub fn one_hot_encode(df: DataFrame, categorical_cols: Option<Vec<String>>) -> DataFrame {
    // Determine which columns to encode
    let cols_to_encode = match categorical_cols {
        Some(cols) => cols,
        None => {
            // Find all discrete columns (assuming they're of type Categorical)
            df.column_types()
                .iter()
                .enumerate()
                .filter(|(_, t)| matches!(t, ColumnType::Categorical(_)))
                .map(|(i, _)| df.column_name(i).to_string())
                .collect()
        }
    };

    // Create a mapping from original column names to new binary column names
    let mut new_col_names = HashMap::new();
    let mut new_col_types = Vec::new();

    for col_name in &cols_to_encode {
        // Get the categorical values for this column
        let col = df.column(col_name).unwrap();
        let categorical = match col.column_type() {
            ColumnType::Categorical(cat) => cat,
            _ => panic!("Column {} is not categorical", col_name),
        };

        // Create new binary column names
        let base_name = format!("{}_", col_name);
        let labels: Vec<String> = categorical.labels().iter().map(|s| s.to_string()).collect();

        // Add new columns to the mapping
        for (i, label) in labels.iter().enumerate() {
            let new_col_name = format!("{}{}", base_name, label);
            new_col_names.insert(new_col_name.clone());
            new_col_types.push(ColumnType::Integer);
        }
    }

    // Create a new empty DataFrame with the new columns
    let mut new_df = DataFrame::new();
    for (name, ty) in new_col_names.iter().zip(new_col_types.iter()) {
        new_df = new_df.with_column(name.clone(), ty.clone());
    }

    // Copy all non-categorical columns from the original DataFrame
    for (i, col_name) in df.column_names().iter().enumerate() {
        if !cols_to_encode.contains(&col_name.to_string()) {
            let col = df.column(col_name).unwrap();
            new_df = new_df.with_column(col_name.clone(), col.column_type().clone());
        }
    }

    // Perform the one-hot encoding
    for col_name in cols_to_encode {
        let col = df.column(&col_name).unwrap();
        let categorical = match col.column_type() {
            ColumnType::Categorical(cat) => cat,
            _ => panic!("Column {} is not categorical", col_name),
        };

        let labels: Vec<String> = categorical.labels().iter().map(|s| s.to_string()).collect();
        let base_name = format!("{}_", col_name);

        // Get the values from the original column
        let values = match col.column_type() {
            ColumnType::Categorical(cat) => {
                let arr = cat.array();
                arr.map(|s| s.to_string()).to_owned()
            }
            _ => panic!("Column {} is not categorical", col_name),
        };

        // Create binary vectors for each label
        for (i, label) in labels.iter().enumerate() {
            let new_col_name = format!("{}{}", base_name, label);
            let mut binary_vec = Vec::new();

            for val in values {
                binary_vec.push(if val == *label { 1 } else { 0 });
            }

            // Convert to Array2 for linfa
            let arr = Array2::from_shape_vec((binary_vec.len(), 1), binary_vec).unwrap();
            let col = Column::new(new_col_name.clone(), ColumnType::Integer, arr);

            // Replace the column in the new DataFrame
            new_df = new_df.replace_column(new_col_name, col);
        }
    }

    new_df
}

