/// Convert categorical columns in a DataFrame to binary integer columns (one-hot encoding)
/// 
/// # Arguments
/// * `df0` - Input DataFrame containing mixed numeric and categorical columns
/// * `categorical_columns` - Vector of column names that should be treated as categorical
/// 
/// # Returns
/// * Result containing the transformed DataFrame with categorical columns replaced by binary columns
pub fn one_hot_encode_categorical(
    df0: &DataFrame,
    categorical_columns: &[&str],
) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Validate that all specified columns exist
    for col_name in categorical_columns {
        if !df0.column_names().contains(col_name) {
            return Err(format!("Column '{}' not found in DataFrame", col_name).into());
        }
    }

    // Separate categorical and non-categorical columns
    let non_categorical_cols: Vec<&str> = df0.column_names()
        .iter()
        .filter(|name| !categorical_columns.contains(name))
        .copied()
        .collect();

    // Start with non-categorical columns
    let mut result_df = df0.select(&non_categorical_cols)?;

    // Process each categorical column
    for col_name in categorical_columns {
        // Extract the categorical column as strings
        let categorical_data: Vec<String> = df0[col_name]
            .as_slice::<String>()
            .map_err(|e| format!("Column '{}' is not string type: {}", col_name, e))?
            .to_vec();

        // Get unique categories
        let unique_categories: Vec<&str> = {
            let mut cats: Vec<&str> = categorical_data.iter()
                .map(|s| s.as_str())
                .collect();
            cats.sort();
            cats.dedup();
            cats
        };

        // Create binary columns for each category
        for category in &unique_categories {
            let binary_values: Vec<f64> = categorical_data.iter()
                .map(|val| if val == *category { 1.0 } else { 0.0 })
                .collect();

