                .column(col_idx)
                .to_owned()
                .into_shape((n_rows, 1))
                .unwrap();
            encoded_cols.push(col_2d);
        }
    }

    // Concatenate all columns horizontally
    if encoded_cols.is_empty() {
        return Array2::zeros((n_rows, 0));
    }

    let result = ndarray::concatenate(
        Axis(1),
        &encoded_cols.iter().map(|a| a.view()).collect::<Vec<_>>(),
    )
    .expect("Failed to concatenate columns");

    result
}

/// One-hot encodes a single categorical column
fn one_hot_encode_column(col: &Array1<f64>) -> Array2<f64> {
    // Get unique values and create a mapping
    let mut unique_vals: Vec<f64> = col.to_vec();
    unique_vals.sort_by(|a, b| a.partial_cmp(b).unwrap());
    unique_vals.dedup();

    let category_map: HashMap<f64, usize> = unique_vals
        .iter()
        .enumerate()
        .map(|(idx, &val)| (val, idx))
        .collect();

    let n_rows = col.len();
    let n_categories = unique_vals.len();

    // Create one-hot encoded matrix
    let mut result = Array2::zeros((n_rows, n_categories));

    for (row_idx, &value) in col.iter().enumerate() {
        if let Some(&category_idx) = category_map.get(&value) {
            result[[row_idx, category_idx]] = 1.0;
        }
    }

    result
}

