use jmespath;
use serde_json::Value;
use std::error::Error;

/// Return true if any element in `lst0` (a JSON array) contains the key `var0`
/// whose value equals `var1`.
///
/// Example:
/// let lst = serde_json::json!([{"name":"alice"}, {"name":"bob"}]);
/// let found = any_element_contains_key_value(&lst, "name", &serde_json::json!("alice"))?;
/// assert!(found);
pub fn any_element_contains_key_value(
    lst0: &Value,
    var0: &str,
    var1: &Value,
) -> Result<bool, Box<dyn Error>> {
    // Ensure input is an array
    if !lst0.is_array() {
        return Err("lst0 must be a JSON array".into());
    }

    // Build a root object containing the array and the target value so we can refer
    // to the target value by name inside the JMESPath expression.
    let mut map = serde_json::Map::new();
    map.insert("lst0".to_string(), lst0.clone());
    map.insert("match_value".to_string(), var1.clone());
    let data = Value::Object(map);

    // Escape single quotes in the key so we can safely embed it inside ['...']
    let key_escaped = var0.replace('\'', "\\'");

    // Expression:
    // lst0[?@['<key>'] == match_value] | length(@) > `0`
    // This filters lst0 for elements whose field `<key>` equals match_value,
    // then checks if the filtered list length is > 0.
    let expr_str = format!("lst0[?@['{}'] == match_value] | length(@) > `0`", key_escaped);

    let expr = jmespath::compile(&expr_str).map_err(|e| Box::new(e) as Box<dyn Error>)?;
    let result = expr.search(&data).map_err(|e| Box::new(e) as Box<dyn Error>)?;

    Ok(result.as_boolean().unwrap_or(false))
}
```

