use tch::{Tensor, Kind, Device};

/// Clone `input` `repeats` times along axis `axis`.
///
/// - `input`: input tensor (any shape).
/// - `repeats`: number of copies along the new axis (must be >= 1).
/// - `axis`: axis at which to insert the new dimension (supports negative indices).
///
/// Returns a new Tensor with one more dimension than `input`, where the new dimension
/// at `axis` has size `repeats` and contains repeated copies of the input.
///
/// Panics on invalid arguments.
pub fn clone_along_axis(input: &Tensor, repeats: i64, axis: i64) -> Tensor {
    if repeats < 1 {
        panic!("repeats must be >= 1, got {}", repeats);
    }

    let rank = input.dim(); // rank of input tensor (i64)
    // allowed axis values:  - (rank+1) ..= rank  (we will insert new axis)
    let axis_norm = if axis < 0 {
        axis + (rank + 1)
    } else {
        axis
    };
    if axis_norm < 0 || axis_norm > rank {
        panic!(
            "axis out of range for inserting new dimension: {}, allowed -{}..{}",
            axis,
            rank + 1,
            rank
        );
    }

    // Insert new singleton dimension at position axis_norm
    let unsq = input.unsqueeze(axis_norm);

    // Build repeat sizes: 1 for all dims except repeats for the new axis
    let mut repeats_vec = vec![1i64; (rank + 1) as usize];
    repeats_vec[axis_norm as usize] = repeats;

    unsq.repeat(&repeats_vec)
}

fn main() {
