/// Multiplies a vector by a matrix using a mapping-based approach
///
/// # Arguments
/// * `vector` - The input vector (1D slice)
/// * `matrix` - The input matrix (2D slice)
///
/// # Returns
/// A new vector containing the result of the matrix-vector multiplication
///
/// # Panics
/// Panics if the number of columns in the matrix doesn't match the vector length
fn matrix_vector_multiply(vector: &[f64], matrix: &[f64]) -> Vec<f64> {
    // Validate input dimensions
    let rows = matrix.len();
    let cols = vector.len();

    // Check if the matrix is rectangular (all rows have the same number of columns)
    let mut current_col = 0;
    for i in 1..rows {
        // Calculate the number of columns for the current row
        let row_start = i * cols;
        let row_end = (i + 1) * cols;
        let row_cols = row_end - row_start;

        if row_cols != cols {
            panic!("Matrix must be rectangular (all rows must have the same number of columns)");
        }

        // Check if all elements in the row are properly aligned
        if row_cols != (matrix[row_start..row_end].len()) {
            panic!("Invalid matrix dimensions");
        }
    }

    // Check if the number of columns in the matrix matches the vector length
    if cols != vector.len() {
        panic!("Number of columns in matrix must match vector length");
    }

    // Calculate the number of rows in the matrix
    let num_rows = rows / cols;

    // Initialize the result vector
    let mut result = vec![0.0; num_rows];

    // Perform the multiplication using a mapping-based approach
    for i in 0..num_rows {
        let mut sum = 0.0;
        for j in 0..cols {
            // Calculate the index in the matrix for element (i,j)
            let matrix_index = i * cols + j;
            sum += matrix[matrix_index] * vector[j];
        }
        result[i] = sum;
    }

    result
}

