use serde_json::Value;
use assert_json_diff::assert_json_eq;
use std::collections::BTreeMap;

/// Compares two JSON objects for equality, ignoring property order.
/// Returns true if the objects have the same entries and values.
///
/// # Arguments
/// * `obj1` - First JSON value to compare
/// * `obj2` - Second JSON value to compare
///
/// # Returns
/// * `bool` - true if objects are equal (ignoring property order), false otherwise
///
/// # Examples
/// ```
/// use serde_json::json;
///
/// let obj1 = json!({"b": 2, "a": 1});
/// let obj2 = json!({"a": 1, "b": 2});
/// assert!(json_objects_equal(&obj1, &obj2));
///
/// let obj3 = json!({"a": 1, "b": 3});
/// assert!(!json_objects_equal(&obj1, &obj3));
/// ```
pub fn json_objects_equal(obj1: &Value, obj2: &Value) -> bool {
    // Normalize both objects by sorting their keys
    let normalized1 = normalize_json(obj1);
    let normalized2 = normalize_json(obj2);

    // Use assert_json_diff to compare the normalized versions
    // We use a try-catch approach since assert_json_eq panics on mismatch
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        assert_json_eq(&normalized1, &normalized2);
    })).is_ok()
}

/// Recursively normalizes a JSON value by sorting object keys
fn normalize_json(value: &Value) -> Value {
    match value {
        Value::Object(map) => {
            let mut sorted_map = BTreeMap::new();
            for (key, val) in map.iter() {
                sorted_map.insert(key.clone(), normalize_json(val));
            }
            Value::Object(sorted_map.into_iter().collect())
        }
        Value::Array(arr) => {
            Value::Array(arr.iter().map(normalize_json).collect())
        }
        other => other.clone()
    }
}

