use assertjson_diff::assert_json_eq;
use serde_json::{json, Value};

/// Compares two JSON objects for equality, ignoring key order.
/// 
/// Returns true if both objects have the same key-value pairs, regardless of order.
/// Returns false if they differ in any way.
///
/// # Arguments
/// * `obj1` - First JSON value to compare
/// * `obj2` - Second JSON value to compare
///
