Example code:

```rust
use std::cmp::Ordering;

/// Return indices of the `n` elements with the largest `var0` values from `lst0`.
/// - `lst0`: slice of items
/// - `n`: how many top indices to return (if n >= lst0.len(), returns all indices sorted by descending var0)
/// - `var0`: accessor closure mapping &T -> f64
///
/// The returned indices are ordered by decreasing var0 (largest first).
pub fn top_n_indices_by_var0<T, F>(lst0: &[T], n: usize, mut var0: F) -> Vec<usize>
where
    F: FnMut(&T) -> f64,
{
    let len = lst0.len();
    if n == 0 || len == 0 {
        return Vec::new();
    }
    if n >= len {
        // return all indices sorted by decreasing var0
        let mut all: Vec<(f64, usize)> = lst0.iter().enumerate().map(|(i, x)| (var0(x), i)).collect();
        all.sort_unstable_by(|a, b| b.0.total_cmp(&a.0));
        return all.into_iter().map(|(_, i)| i).collect();
    }

    // Build (value, index) pairs
    let mut pairs: Vec<(f64, usize)> = lst0.iter().enumerate().map(|(i, x)| (var0(x), i)).collect();

    // Partition so that the highest `n` values are in the last `n` positions (not sorted)
    let k = len - n;
    pairs.select_nth_unstable_by(k, |a, b| a.0.total_cmp(&b.0));

    // Copy the top-n slice, sort it descending by value, and return indices
    let mut top: Vec<(f64, usize)> = pairs[k..].to_vec();
    top.sort_unstable_by(|a, b| b.0.total_cmp(&a.0));
    top.into_iter().map(|(_, i)| i).collect()
}

