use orderstat::OrderStat;

/// Returns the indices of the N elements with the highest values from a collection.
///
/// # Arguments
/// * `lst0` - A slice of comparable values
/// * `n` - The number of top elements to find
///
/// # Returns
/// A vector of indices corresponding to the N largest elements, sorted in descending order
/// (highest value first).
///
/// # Panics
/// Panics if `n` is greater than the length of `lst0`.
pub fn top_n_indices<T: Ord + Clone>(lst0: &[T], n: usize) -> Vec<usize> {
    assert!(
        n <= lst0.len(),
        "n ({}) cannot be greater than the length of lst0 ({})",
        n,
        lst0.len()
    );

    if n == 0 {
        return Vec::new();
    }

    // Create a vector of (value, index) pairs
    let mut indexed: Vec<(T, usize)> = lst0
        .iter()
        .enumerate()
        .map(|(i, v)| (v.clone(), i))
        .collect();

    // Use orderstat to find the nth largest element (nth order statistic from the top)
    // We need the (len - n)th smallest element to partition
    let k = lst0.len() - n;

    // Find the kth smallest element (which is the nth largest)
    let (_, &mut (ref pivot_value, _)) = indexed.kth_smallest(k);

    // Collect indices of elements >= pivot_value
    let mut result_indices: Vec<usize> = indexed
        .iter()
        .filter(|(val, _)| val >= pivot_value)
        .map(|(_, idx)| *idx)
        .collect();

    // Sort indices by their corresponding values in descending order
    result_indices.sort_by(|&a, &b| lst0[b].cmp(&lst0[a]));

    // If we have more than n elements (due to duplicates), truncate
    result_indices.truncate(n);

    result_indices
}

