    // Use orderstat to partition around the (n-1)th largest element
    if actual_n < indexed_items.len() {
        let partition_idx = indexed_items.len() - actual_n;
        indexed_items.select_nth_unstable_by(
            partition_idx,
            |a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal),
        );
    }

    // Collect the top N indices and sort them by their values in descending order
    indexed_items
        .iter()
        .rev()
        .take(actual_n)
        .map(|(idx, _)| *idx)
        .collect()
}

// Alternative version for direct value access
fn get_top_n_indices_direct(lst0: &[f64], n: usize) -> Vec<usize> {
    if n == 0 || lst0.is_empty() {
        return Vec::new();
    }

    let actual_n = n.min(lst0.len());

    // Create indexed pairs
    let mut indexed_items: Vec<(usize, f64)> = lst0
        .iter()
        .enumerate()
        .map(|(idx, &val)| (idx, val))
        .collect();

    // Partition to find top N
    if actual_n < indexed_items.len() {
        let partition_idx = indexed_items.len() - actual_n;
        indexed_items.select_nth_unstable_by(
            partition_idx,
            |a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal),
        );
    }

    // Sort top N by value (descending) and return indices
    let mut top_n: Vec<_> = indexed_items.iter().rev().take(actual_n).copied().collect();
    top_n.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
    top_n.into_iter().map(|(idx, _)| idx).collect()
}

#[cfg(test)]
