    fn test_top_n_indices() {
        let values = vec![10.5, 20.3, 15.7, 25.1, 5.2, 18.9];
        let indices = get_top_n_indices_direct(&values, 3);

        // Top 3 should be: 25.1 (idx 3), 20.3 (idx 1), 18.9 (idx 5)
        assert_eq!(indices.len(), 3);
        assert!(indices.contains(&3));
        assert!(indices.contains(&1));
        assert!(indices.contains(&5));
    }

    #[test]
    fn test_n_larger_than_list() {
