use itertools::Itertools;

fn cartesian_grid(var0: f64, var1: f64, var2: f64, var3: f64, steps: usize) -> Vec<(f64, f64)> {
    // Create ranges for both intervals
    let x_range = linspace(var0, var1, steps);
