    // Helper to escape a reference token per RFC 6901 for JSON Pointer:
    // replace "~" with "~0" and "/" with "~1".
    fn escape_json_pointer_token(s: &str) -> String {
        s.replace('~', "~0").replace('/', "~1")
    }

    // Ensure lst0 is an array
    let arr = match lst0.as_array() {
        Some(a) => a,
        None => return Err("lst0 must be a JSON array".into()),
    };

    // Build patch operations: only emit "remove" ops for objects that actually contain var0
    let mut ops = Vec::new();
    for (i, item) in arr.iter().enumerate() {
        if item.get(var0).is_some() {
            let token = escape_json_pointer_token(var0);
            let path = format!("/{}/{}", i, token);
            ops.push(json!({
                "op": "remove",
                "path": path
            }));
        }
    }

    // If nothing to remove, return early
    if ops.is_empty() {
        return Ok(());
    }

    let patch = Value::Array(ops);
    // Apply the patch to lst0 (in-place)
    jsonpatch::patch(lst0, &patch)?;
    Ok(())
}
```

