    let col_key = df0.column("var0").expect("column 'var0' not found");
    let col_val = df0.column("var1").expect("column 'var1' not found");

    // We'll collect sums into a HashMap<key_string, f64>
    let mut sums: HashMap<String, f64> = HashMap::new();
    let n_rows = df0.height();

    for i in 0..n_rows {
        // Convert key value to String (supports string-like / scalar values)
        let key_any = col_key.get(i).expect("failed to get var0 value");
        let key = key_any.to_string();

        // Convert var1 to f64. Accept integer or float types; treat missing as 0.0.
        let val_any = col_val.get(i).expect("failed to get var1 value");
        let v = if let Some(f) = val_any.as_f64() {
            f
        } else if let Some(i64v) = val_any.as_i64() {
            i64v as f64
        } else if let Some(u64v) = val_any.as_u64() {
            u64v as f64
        } else {
            0.0
        };

        *sums.entry(key).or_insert(0.0) += v;
