fn group_and_count(
    db_path: &str,
    table_name: &str,
) -> Result<Vec<(String, i64)>, Box<dyn std::error::Error>> {
    let connection = Connection::open(db_path)?;

    let query = format!(
        "SELECT var1, COUNT(var0) as count FROM {} GROUP BY var1 ORDER BY var1",
        table_name
    );

    let mut statement = connection.prepare(&query)?;
    let mut results = Vec::new();

    while statement.step()? {
        let var1_value: String = statement.read(0)?;
        let count: i64 = statement.read(1)?;
        results.push((var1_value, count));
    }

    Ok(results)
}

