use rdermap::RderMap;
use std::cmp::Reverse;

/// Return the keys of `dict0` sorted in descending order by the length of their associated values.
///
/// - K must be Clone because keys are returned by value.
/// - V must implement `AsRef<[T]>` so we can measure the length of the value as a slice.
///
/// T is unconstrained because we only need the slice for its `len()`.
pub fn sorted_keys_by_value_len_desc<K, V, T>(dict0: &RderMap<K, V>) -> Vec<K>
where
    K: Clone,
    V: AsRef<[T]>,
{
    // Collect (key, value_len) pairs, cloning keys
    let mut pairs: Vec<(K, usize)> = dict0
        .iter()
        .map(|(k, v)| (k.clone(), v.as_ref().len()))
        .collect();

    // Sort by length descending. sort_by_key is stable, so ties preserve original order.
    pairs.sort_by_key(|&(_, len)| Reverse(len));

    // Extract and return keys in the new order
    pairs.into_iter().map(|(k, _)| k).collect()
}

