    dict0.insert("a".to_string(), vec![1, 2]);
    dict0.insert("b".to_string(), vec![1, 2, 3, 4]);
    dict0.insert("c".to_string(), vec![1]);

    let keys = sorted_keys_by_value_len_desc(&dict0);
