    /// Compare two same-length slices of f32 and return a Vec<bool> with elementwise `a[i] < b[i]`.
    ///
    /// Panics if the slices have different lengths.
    fn less_than_simd(a: &[f32], b: &[f32]) -> Vec<bool> {
