        while i + stride <= n {
            // load vectors
            let va = S::loadu_ps(&a[i]);
            let vb = S::loadu_ps(&b[i]);

            // compare: produces a mask-vector
            let cmp_mask = S::cmp_lt_ps(va, vb);

