use regex::Regex;

fn cleanse_column(df: &mut DataFrame, col_name: &str) -> Result<(), PolarsError> {
    // Create a regex pattern that matches non-alphanumeric characters
    let re = Regex::new(r"[^a-zA-Z0-9]")?;

