fn cleanse_csv_column(input_path: &str, output_path: &str, col_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let re = Regex::new(r"[^a-zA-Z0-9]")?;

    let mut reader = Reader::from_path(input_path)?;
    let mut writer = Writer::from_path(output_path)?;

    // Write headers
    let headers = reader.headers()?.clone();
    writer.write_record(&headers)?;

    let col_index = headers.iter().position(|h| h == col_name)
        .ok_or("Column not found")?;

    for result in reader.records() {
        let mut record = result?;
        record[col_index] = re.replace_all(&record[col_index], "").to_string();
        writer.write_record(&record)?;
    }

    writer.flush()?;
    Ok(())
}
