    physical_plan::execution::send_to_executor,
    logical_plan::expr::Column,
};
use std::sync::Arc;

/// Groups rows by `var0` and computes the sum of each column for each group
///
/// # Arguments
/// * `df` - The input DataFrame
/// * `group_by_col` - The name of the column to group by (default: "var0")
/// * `sum_cols` - The names of columns to sum (default: all columns except the group-by column)
///
/// # Returns
/// A new DataFrame with grouped and summed rows
pub async fn group_and_sum(
    df: Arc<dyn Executor>,
    group_by_col: &str,
    sum_cols: Option<Vec<String>>,
) -> Result<Arc<dyn Executor>, Box<dyn std::error::Error>> {
    // Get the schema to determine all column names
    let schema = df.schema();
    let all_columns: Vec<String> = schema
        .columns()
        .iter()
        .map(|c| c.name().to_string())
        .collect();

    // Determine which columns to sum (all except group_by_col if not specified)
    let columns_to_sum = match sum_cols {
        Some(cols) => cols,
        None => {
            let mut cols = all_columns.clone();
            cols.retain(|c| c != group_by_col);
            cols
        }
    };

    // Create the group-by expression
    let group_expr = Column::new(group_by_col.to_string(), schema);

    // Create sum expressions for each column
    let sum_exprs: Vec<_> = columns_to_sum
        .iter()
        .map(|col| {
            let col_expr = Column::new(col.clone(), schema);
            datafusion::logical_plan::expr::Sum::new(Arc::new(col_expr), false)
        })
        .collect();

    // Create the logical plan
    let mut plan = df.create_logical_plan()?;
    plan = plan.group_by(vec![group_expr])?
        .aggregate(vec![group_expr], sum_exprs)?;

    // Execute the plan
    let physical_plan = plan.create_physical_plan()?;
    let output = send_to_executor(df, physical_plan).await?;

    Ok(output)
}

