use std::sync::Arc;

use datafusion::arrow::datatypes::DataType;
use datafusion::dataframe::DataFrame;
use datafusion::error::{DataFusionError, Result};
use datafusion::prelude::{col, sum, Expr};

/// Group the rows in `df` (a DataFusion DataFrame) by the values in column `group_col`,
/// and for each group return a single row whose columns (except the group key) are the
/// sums of the corresponding original columns.
///
/// - Only numeric Arrow column types are summed (integer and floating-point types).
/// - Non-numeric columns (other than the group key) are skipped.
///
/// Returns a new DataFrame representing the grouped-and-summed result.
pub fn group_and_sum_by_key(
    df: Arc<dyn DataFrame>,
    group_col: &str,
) -> Result<Arc<dyn DataFrame>> {
    // Validate the group column exists
    let schema = df.schema();
    if !schema.fields().iter().any(|f| f.name() == group_col) {
        return Err(DataFusionError::Plan(format!(
            "group column '{}' not found in schema",
            group_col
        )));
    }

    // Build aggregate expressions: sum(...) for each numeric column except the group key
    let mut aggr_exprs: Vec<Expr> = Vec::new();
    for field in schema.fields() {
        let name = field.name().as_str();
        if name == group_col {
            continue;
        }

        match field.data_type() {
            DataType::Int8
            | DataType::Int16
            | DataType::Int32
            | DataType::Int64
            | DataType::UInt8
            | DataType::UInt16
            | DataType::UInt32
            | DataType::UInt64
            | DataType::Float32
            | DataType::Float64 => {
                // sum(col(name)) and alias it to the original column name
                aggr_exprs.push(sum(col(name)).alias(name));
            }
            _ => {
                // skip non-numeric columns
            }
        }
    }

    if aggr_exprs.is_empty() {
        return Err(DataFusionError::Plan(
            "no numeric columns found to aggregate".to_string(),
        ));
    }

    // Group by the key column and apply the aggregates
    df.aggregate(vec![col(group_col)], aggr_exprs)
}

