/// let result = longest_in_each_column(data);
/// assert_eq!(result, vec!["abc".to_string(), "hello".to_string(), "yz".to_string()]);
/// ```
fn longest_in_each_column(rows: Vec<Vec<String>>) -> Vec<String> {
    if rows.is_empty() {
        return Vec::new();
    }

    let num_cols = rows[0].len();
    let mut longest: Vec<String> = vec![String::new(); num_cols];

    // Iterate through each row
    for row in rows {
        // Iterate through each column in the row
        for (col_idx, cell) in row.iter().enumerate() {
            if col_idx < num_cols {
                // Update if current cell is longer than stored longest
                if cell.len() > longest[col_idx].len() {
                    longest[col_idx] = cell.clone();
                }
            }
        }
    }

    longest
}

