    // Find column indices
    let col1_idx = header.iter().position(|h| h == col_name1)
        .ok_or_else(|| format!("Column '{}' not found", col_name1))?;
    let col2_idx = header.iter().position(|h| h == col_name2)
        .ok_or_else(|| format!("Column '{}' not found", col_name2))?;

