///   and col_name2 values as values, or an error message
pub fn create_column_map(
    df0: Vec<Vec<String>>,
    col_name1: &str,
    col_name2: &str,
    headers: Vec<String>,
) -> Result<IndexMap<String, String>, String> {
    // Find column indices
    let col_idx1 = headers
        .iter()
        .position(|h| h == col_name1)
        .ok_or(format!("Column '{}' not found", col_name1))?;

    let col_idx2 = headers
