use ordered_float::OrderedFloat;
use std::cmp::Ordering;

fn sort_floats_in_place(lst0: &mut [f64]) {
    // Convert the slice of f64 into a slice of OrderedFloat<f64>
    let mut ordered_floats: Vec<OrderedFloat<f64>> = lst0.iter().map(|&x| OrderedFloat(x)).collect();

    // Sort the vector of OrderedFloat<f64>
    ordered_floats.sort_unstable_by(|a, b| a.cmp(b));

    // Copy the sorted values back into the original slice
