use csv::ReaderBuilder;
use std::error::Error;

fn filter_table_rows(
    df0: &str,
    var0: &str,
    var1: &str,
) -> Result<Vec<Vec<String>>, Box<dyn Error>> {
    let mut reader = ReaderBuilder::new()
        .from_reader(df0.as_bytes());

    // Get headers to find the column index
    let headers = reader.headers()?.clone();
    let column_index = headers
        .iter()
        .position(|h| h == var0)
        .ok_or(format!("Column '{}' not found", var0))?;

    let mut result = Vec::new();

    // Add header row
    result.push(headers.iter().map(|s| s.to_string()).collect());

    // Filter and collect matching rows
    for record in reader.records() {
        let record = record?;
        if record.get(column_index).map_or(false, |val| val == var1) {
            result.push(record.iter().map(|s| s.to_string()).collect());
        }
    }

    Ok(result)
}

