use std::collections::HashMap;
use maplit::hashmap;

/// Sum values for each key across all maps in `lst0` and return a Vec of (key, sum)
/// sorted by sum descending (ties by key ascending).
///
/// Example:
/// let m1 = hashmap! { "a".to_string() => 2, "b".to_string() => 3 };
/// let m2 = hashmap! { "a".to_string() => 4, "c".to_string() => 1 };
/// let result = sum_and_sort_by_value(&[m1, m2]);
/// // result == [("a",6), ("b",3), ("c",1)]
pub fn sum_and_sort_by_value(lst0: &[HashMap<String, i64>]) -> Vec<(String, i64)> {
    let mut acc: HashMap<String, i64> = HashMap::new();

    for map in lst0 {
        for (k, v) in map {
            *acc.entry(k.clone()).or_insert(0) += *v;
        }
    }

    let mut vec: Vec<(String, i64)> = acc.into_iter().collect();

    // Sort by value descending, then by key ascending for deterministic order on ties.
    vec.sort_by(|a, b| {
        b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0))
