use itertools::Itertools;

/// Generate all possible sequences formed by picking exactly one element 
/// from each sublist in the given list of lists.
///
/// # Arguments
/// * `lst0` - A slice of slices, where each inner slice contains elements to choose from
///
/// # Returns
