/// let result = cartesian_product(&input);
/// assert_eq!(result, vec![
///     vec![1, 3],
///     vec![1, 4],
///     vec![2, 3],
///     vec![2, 4],
/// ]);
/// ```
pub fn cartesian_product<T: Clone>(lst0: &[Vec<T>]) -> Vec<Vec<T>> {
    if lst0.is_empty() {
        return vec![vec![]];
    }

    // Start with the first sublist
    let mut result: Vec<Vec<T>> = lst0[0]
        .iter()
        .map(|x| vec![x.clone()])
        .collect();

    // For each subsequent sublist, combine with existing results
    for sublist in &lst0[1..] {
        result = result
            .into_iter()
            .cartesian_product(sublist.iter())
            .map(|(mut seq, item)| {
                seq.push(item.clone());
                seq
            })
            .collect();
    }

    result
}

