    if lst0.is_empty() {
        return vec![vec![]];
    }

    lst0.iter()
        .fold(vec![vec![]], |acc, sublist| {
            acc.into_iter()
                .cartesian_product(sublist.iter())
                .map(|(mut seq, item)| {
                    seq.push(item.clone());
                    seq
                })
                .collect()
        })
}

