use ndarray::{array, Array2, Zip};

/// Update cells in `df0` in-place by copying values from `df1`
/// wherever the predicate `cond(&df0_value, &df1_value)` returns true.
///
/// Returns Err if the two arrays have different shapes.
pub fn update_cells_inplace<T, F>(
    df0: &mut Array2<T>,
    df1: &Array2<T>,
    cond: F,
) -> Result<(), &'static str>
where
    T: Clone,
    F: Fn(&T, &T) -> bool,
{
    if df0.shape() != df1.shape() {
        return Err("shape mismatch between df0 and df1");
    }

    Zip::from(df0)
        .and(df1)
        .for_each(|a_cell, b_cell| {
            if cond(a_cell, b_cell) {
                *a_cell = b_cell.clone();
            }
        });

    Ok(())
}

/// Convenience helper: for f64 arrays, copy from df1 to df0 wherever df1 is not NaN.
pub fn copy_non_nan_f64(df0: &mut Array2<f64>, df1: &Array2<f64>) -> Result<(), &'static str> {
    update_cells_inplace(df0, df1, |_, b| !b.is_nan())
}

fn main() {
    // Example 1: generic predicate - replace df0 cell when df1 is greater
    let mut df0: Array2<i32> = array![[1, 2, 3], [4, 5, 6]];
    let df1: Array2<i32> = array![[0, 20, 0], [40, 0, 60]];
    update_cells_inplace(&mut df0, &df1, |_, b| *b > 0).expect("shapes match");
    // df0 is now [[1, 20, 3], [40, 5, 60]]
    println!("df0 after >0 replacement:\n{:#?}", df0);

    // Example 2: f64 NaN-aware replacement
    let mut a: Array2<f64> = array![[1.0, 2.0], [3.0, 4.0]];
    let b: Array2<f64> = array![[f64::NAN, 20.0], [30.0, f64::NAN]];
    copy_non_nan_f64(&mut a, &b).unwrap();
    // a is now [[1.0, 20.0], [30.0, 4.0]]
    println!("a after copy_non_nan_f64:\n{:#?}", a);
}
```

Notes:
- The function checks shapes and returns an error for mismatched shapes.
- The predicate gets references to the df0 and df1 cell values, allowing arbitrary logic to decide whether to overwrite df0's cell with df1's.
- For performance, Zip iterates in cache-friendly order and performs updates in-place.

