```rust
use ndarray::{Array2, s};

/// Updates specific cells in df0 based on corresponding cells in df1.
/// 
/// This function iterates through both datasets and updates cells in df0
/// where the corresponding cell in df1 meets a condition (non-zero/non-empty).
/// 
/// # Arguments
/// * `df0` - The primary dataset to be modified (mutable)
/// * `df1` - The source dataset containing values to copy from
/// * `update_condition` - A closure that determines if a cell should be updated
/// 
/// # Example
/// ```
/// use ndarray::Array2;
/// 
/// let mut df0 = Array2::from_shape_vec((2, 2), vec![1, 2, 3, 4]).unwrap();
/// let df1 = Array2::from_shape_vec((2, 2), vec![10, 0, 20, 0]).unwrap();
/// 
/// update_cells_from_dataset(&mut df0, &df1, |val| val != &0);
/// 
/// assert_eq!(df0[[0, 0]], 10);
/// assert_eq!(df0[[0, 1]], 2);  // unchanged
/// assert_eq!(df0[[1, 0]], 20);
/// assert_eq!(df0[[1, 1]], 4);  // unchanged
/// ```
fn update_cells_from_dataset<T: Clone + PartialEq>(
    df0: &mut Array2<T>,
    df1: &Array2<T>,
    update_condition: impl Fn(&T) -> bool,
) -> Result<(), String> {
    // Verify datasets have the same shape
    if df0.shape() != df1.shape() {
        return Err(format!(
            "Shape mismatch: df0 {:?} vs df1 {:?}",
            df0.shape(),
            df1.shape()
        ));
    }

    let (rows, cols) = df0.dim();

    // Iterate through all cells and update based on condition
    for i in 0..rows {
        for j in 0..cols {
            let df1_value = &df1[[i, j]];

            // Update df0 cell if condition is met
            if update_condition(df1_value) {
                df0[[i, j]] = df1_value.clone();
            }
        }
    }

    Ok(())
}

