            10, 0, 20,
            0, 30, 0,
        ]).unwrap();

        update_cells_from_dataset(&mut df0, &df1, |val| val != &0).unwrap();

        assert_eq!(df0.to_vec(), vec![10, 2, 20, 4, 30, 6]);
