use std::collections::HashMap;

/// Updates rows in a DataFrame where column `var0` equals `var1`, setting `var2` to `var1`
///
/// # Arguments
/// * `df0` - The input DataFrame
/// * `var0` - Name of the column to compare against `var1`
/// * `var1` - Name of the column containing the values to match against `var0`
/// * `var2` - Name of the column to update with values from `var1`
///
/// # Returns
/// A new DataFrame with the specified updates applied
pub fn update_matching_rows(df0: DataFrame, var0: &str, var1: &str, var2: &str) -> DataFrame {
    // Get the columns we need to work with
    let var0_series = df0.column(var0).unwrap();
    let var1_series = df0.column(var1).unwrap();
    let var2_series = df0.column(var2).unwrap();

    // Create a mask of rows where var0 equals var1
    let mask: Vec<bool> = var0_series
        .iter()
        .zip(var1_series.iter())
        .map(|(a, b)| a == b)
        .collect();

    // Create a new Series with var1 values where mask is true, otherwise keep original var2
    let new_var2: Vec<Option<_>> = var2_series
        .iter()
        .zip(mask.iter())
        .map(|(val, &should_update)| if should_update { var1_series[mask.iter().position(|x| x).unwrap()] } else { val })
        .collect();

    // Create a new DataFrame with the updated column
    let mut new_df = df0.clone();
    new_df.set_column(var2, Series::new(var2, new_var2)).unwrap();

    new_df
}

