///
/// # Returns
/// A vector of tuples containing:
/// - The numerical value (as a string)
/// - The comparison operator (if any)
/// - The comparison value (if any)
pub fn extract_numerical_comparisons(input: &str) -> Vec<(String, Option<String>, Option<String>)> {
    // Parse the input string into an AST
    let mut parser = Parser::new();
    let ast = match parser.parse(TokenStream::from_str(input)) {
        Ok(ast) => ast,
        Err(e) => {
            eprintln!("Error parsing input: {}", e);
            return Vec::new();
        }
    };

    let mut results = Vec::new();

    // Helper function to process numeric literals and their comparisons
    fn process_node(node: &ast::Node, results: &mut Vec<(String, Option<String>, Option<String>)>) {
        match node {
            ast::Node::Literal(lit) => {
                if let ast::Literal::Number(num) = lit {
                    // Check if this number is part of a comparison
                    let mut comparison = None;
                    let mut comparison_value = None;

                    // Look for adjacent comparison operators
                    if let Some(prev_node) = node.prev_node() {
                        if let ast::Node::Operator(op) = prev_node {
                            if let ast::Operator::Comparison(op_str) = op {
                                comparison = Some(op_str.clone());
                                // Try to find the next number if this is a range
                                if let Some(next_node) = node.next_node() {
                                    if let ast::Node::Literal(next_lit) = next_node {
                                        if let ast::Literal::Number(next_num) = next_lit {
                                            comparison_value = Some(next_num.to_string());
                                            // Skip the next number to avoid double processing
                                            if let Some(grand_next) = next_node.next_node() {
                                                process_node(grand_next, results);
                                            }
                                            return;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    results.push((num.to_string(), comparison, comparison_value));
                }
            }
            ast::Node::Operator(_) => {
                // Skip operators as they're handled in the literal processing
            }
            _ => {
                // Recursively process other nodes (like parentheses, etc.)
                for child in node.children() {
                    process_node(child, results);
                }
            }
        }
    }

    // Start processing from the root
    for child in ast.children() {
        process_node(child, &mut results);
    }

    results
}

