        // Worded comparisons before the number: less than 5, greater than or equal to 3
        r"(?i)\b(?:less\s+than|more\s+than|greater\s+than(?:\s+or\s+equal\s+to)?|less\s+than\s+or\s+equal\s+to|at\s+least|at\s+most|under|over)\s*[+-]?\d+(?:\.\d+)?",
