    for pat in &patterns {
        let re = Regex::new(pat).expect("Invalid regex");
        for mat in re.find_iter(text) {
            // Store match start to preserve original order later
            found.push((mat.start(), mat.as_str().to_string()));
        }
    }

    // Sort by first occurrence index and deduplicate while preserving order
    found.sort_by_key(|(idx, _)| *idx);
    let mut seen = HashSet::new();
    let mut results = Vec::new();
    for (_, s) in found {
        if seen.insert(s.clone()) {
            results.push(s);
        }
    }

