/// Extracts numerical values with their associated comparison terms from text.
/// Returns a vector of tuples containing (comparison_term, numerical_value).
/// 
/// Examples:
/// - "less than 10" -> ("less than", 10.0)
/// - "greater than 5" -> ("greater than", 5.0)
/// - "between 20 and 30" -> ("between", 20.0), ("and", 30.0)
/// - "more than 100" -> ("more than", 100.0)
/// - "at least 50" -> ("at least", 50.0)
/// - "at most 25" -> ("at most", 25.0)
/// - "exactly 42" -> ("exactly", 42.0)
/// - "equal to 7" -> ("equal to", 7.0)
/// - "no more than 15" -> ("no more than", 15.0)
/// - "no less than 8" -> ("no less than", 8.0)
pub fn extract_numerical_comparisons(var0: &str) -> Vec<(String, f64)> {
    // Define comparison patterns with their associated terms
    let comparison_patterns = vec![
        // Multi-word patterns (check these first to avoid partial matches)
        ("no more than", "no more than"),
        ("no less than", "no less than"),
        ("greater than or equal to", "greater than or equal to"),
        ("less than or equal to", "less than or equal to"),
        ("more than", "more than"),
        ("less than", "less than"),
        ("greater than", "greater than"),
        ("at least", "at least"),
        ("at most", "at most"),
        ("equal to", "equal to"),
        // Single word patterns
        ("between", "between"),
        ("exactly", "exactly"),
        ("above", "above"),
        ("below", "below"),
        ("over", "over"),
        ("under", "under"),
        ("minimum", "minimum"),
        ("maximum", "maximum"),
        ("min", "min"),
        ("max", "max"),
    ];

    let mut results: Vec<(String, f64)> = Vec::new();
    let lower_text = var0.to_lowercase();

    // Try to find "between X and Y" pattern first
    if let Some(between_match) = extract_between_pattern(&lower_text) {
        results.push(("between".to_string(), between_match.0));
        results.push(("and".to_string(), between_match.1));
    }

    // Extract other comparison patterns
    for (pattern, label) in &comparison_patterns {
        if pattern == &"between" {
            continue; // Already handled above
        }

        // Find all occurrences of this pattern followed by a number
        let pattern_lower = pattern.to_lowercase();
        let mut search_start = 0;

        while let Some(pos) = lower_text[search_start..].find(&pattern_lower) {
            let actual_pos = search_start + pos;
            let after_pattern = &lower_text[actual_pos + pattern_lower.len()..];

            // Try to extract the number after the pattern
            if let Some((value, _)) = extract_number(after_pattern) {
                results.push((label.to_string(), value));
                search_start = actual_pos + pattern_lower.len() + 1;
            } else {
                search_start = actual_pos + 1;
            }
        }
    }

    // Also extract standalone numbers that might have implicit comparisons
    // (e.g., "values > 10" or "items < 5")
    extract_symbolic_comparisons(&lower_text, &mut results);

    results
}

/// Extracts numbers from "between X and Y" patterns
fn extract_between_pattern(text: &str) -> Option<(f64, f64)> {
    let between_re = regex::Regex::new(r"between\s+(\d+(?:\.\d+)?)\s+and\s+(\d+(?:\.\d+)?)").ok()?;

    if let Some(caps) = between_re.captures(text) {
        let first: f64 = caps.get(1)?.as_str().parse().ok()?;
        let second: f64 = caps.get(2)?.as_str().parse().ok()?;
        Some((first, second))
    } else {
        None
    }
}

/// Extracts a number from the beginning of a string (ignoring whitespace)
fn extract_number(text: &str) -> Option<(f64, usize)> {
    let trimmed = text.trim_start();
    let num_re = regex::Regex::new(r"^(\d+(?:\.\d+)?)").ok()?;

    if let Some(caps) = num_re.captures(trimmed) {
        let value: f64 = caps.get(1)?.as_str().parse().ok()?;
        let end_pos = text.len() - trimmed.len() + caps.get(1)?.as_str().len();
        Some((value, end_pos))
    } else {
        None
    }
}

/// Extracts symbolic comparisons like >, <, >=, <=, =, !=
fn extract_symbolic_comparisons(text: &str, results: &mut Vec<(String, f64)>) {
    let symbolic_patterns = vec![
        (">=", "greater than or equal to"),
        ("<=", "less than or equal to"),
        (">", "greater than"),
        ("<", "less than"),
        ("!=", "not equal to"),
        ("=", "equal to"),
    ];

    for (symbol, label) in &symbolic_patterns {
        let mut search_start = 0;

        while let Some(pos) = text[search_start..].find(symbol) {
            let actual_pos = search_start + pos;

            // Check for number before or after the symbol
            let before = &text[..actual_pos].trim();
            let after = &text[actual_pos + symbol.len()..].trim();

            // Try number after symbol first
            if let Some((value, _)) = extract_number(after) {
                results.push((label.to_string(), value));
            }
            // Then try number before symbol
            else if let Some((value, _)) = extract_number(before) {
                results.push((label.to_string(), value));
            }

            search_start = actual_pos + 1;
        }
    }
}

