# Rust Function to Extract Numerical Values with Comparison Terms

```rust
use regex::Regex;
use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub struct NumericExpression {
    pub comparison: String,
    pub value: f64,
    pub original_text: String,
}

/// Extracts numerical values with associated comparison terms or range expressions
/// from the input string.
/// 
/// # Arguments
/// * `var0` - The input string to parse
/// 
/// # Returns
/// A vector of NumericExpression structs containing the extracted values and comparisons
/// 
/// # Example
/// ```
/// let results = extract_numerical_values("less than 5, between 10 and 20, greater than 100");
/// // Returns expressions like: "< 5", "between 10-20", "> 100"
/// ```
pub fn extract_numerical_values(var0: &str) -> Vec<NumericExpression> {
    let mut results = Vec::new();

    // Regex patterns for various comparison expressions
    let patterns = vec![
        // Range expressions (between X and Y)
        (r"between\s+([-+]?\d+\.?\d*)\s+and\s+([-+]?\d+\.?\d*)", "between"),
        // Comparison operators with text
        (r"(?:less\s+than|below|under)\s+([-+]?\d+\.?\d*)", "<"),
        (r"(?:greater\s+than|above|over)\s+([-+]?\d+\.?\d*)", ">"),
        (r"(?:at\s+most|no\s+more\s+than)\s+([-+]?\d+\.?\d*)", "<="),
        (r"(?:at\s+least|no\s+less\s+than)\s+([-+]?\d+\.?\d*)", ">="),
        (r"(?:equal\s+to|equals?)\s+([-+]?\d+\.?\d*)", "="),
        (r"(?:not\s+equal\s+to|not\s+equals?)\s+([-+]?\d+\.?\d*)", "!="),
        // Standard operators
        (r"([<>]=?|=)\s*([-+]?\d+\.?\d*)", "operator"),
    ];

    for (pattern_str, comp_type) in patterns {
        if let Ok(re) = Regex::new(pattern_str) {
            for caps in re.captures_iter(var0) {
                let original = caps.get(0).unwrap().as_str();

                match comp_type {
                    "between" => {
                        if let (Some(val1), Some(val2)) = (caps.get(1), caps.get(2)) {
                            if let (Ok(v1), Ok(v2)) = (val1.as_str().parse::<f64>(), val2.as_str().parse::<f64>()) {
                                results.push(NumericExpression {
                                    comparison: format!("between {} and {}", v1, v2),
                                    value: v1,
                                    original_text: original.to_string(),
                                });
                            }
                        }
                    },
                    "operator" => {
                        if let (Some(op), Some(val)) = (caps.get(1), caps.get(2)) {
                            if let Ok(v) = val.as_str().parse::<f64>() {
                                results.push(NumericExpression {
                                    comparison: op.as_str().to_string(),
                                    value: v,
                                    original_text: original.to_string(),
                                });
                            }
                        }
                    },
                    _ => {
                        if let Some(val) = caps.get(1) {
                            if let Ok(v) = val.as_str().parse::<f64>() {
                                results.push(NumericExpression {
                                    comparison: comp_type.to_string(),
                                    value: v,
                                    original_text: original.to_string(),
                                });
                            }
                        }
                    }
                }
            }
        }
    }

    // Remove duplicates while preserving order
    results.sort_by(|a, b| a.original_text.cmp(&b.original_text));
    results.dedup_by(|a, b| a.original_text == b.original_text);

    results
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_comparisons() {
        let input = "The value should be less than 5 and greater than 2";
        let results = extract_numerical_values(input);

        assert!(results.iter().any(|e| e.comparison == "<" && e.value == 5.0));
        assert!(results.iter().any(|e| e.comparison == ">" && e.value == 2.0));
    }

    #[test]
    fn test_text_comparisons() {
        let input = "The price is at least 100 but no more than 500";
        let results = extract_numerical_values(input);

        assert!(results.iter().any(|e| e.comparison == ">=" && e.value == 100.0));
        assert!(results.iter().any(|e| e.comparison == "<=" && e.value == 500.0));
    }

    #[test]
    fn test_range_expression() {
        let input = "The temperature should be between 20 and 30 degrees";
        let results = extract_numerical_values(input);

        assert!(results.iter().any(|e| e.comparison.contains("between") && e.value == 20.0));
    }

    #[test]
    fn test_floats() {
        let input = "greater than 3.14 and less than 2.71";
        let results = extract_numerical_values(input);

        assert!(results.iter().any(|e| e.comparison == ">" && e.value == 3.14));
        assert!(results.iter().any(|e| e.comparison == "<" && e.value == 2.71));
    }
}

fn main() {
    let test_string = "The value must be less than 100, between 10 and 50, or greater than 200. Also at least 5.5";
    let expressions = extract_numerical_values(test_string);

    println!("Extracted numerical expressions:");
    for expr in expressions {
        println!("  {} {} (original: \"{}\")", 
                 expr.comparison, expr.value, expr.original_text);
    }
}
