use ndarray::{array, Array2};

/// For each row in `df0`, find the column index with the largest value and
/// return the corresponding column name from `col_names`.
///
/// Returns Err if the number of column names does not equal the number of columns,
/// or if the array has zero columns.
fn argmax_column_names_for_rows<T>(
    df0: &Array2<T>,
    col_names: &[&str],
) -> Result<Vec<String>, String>
where
    T: PartialOrd + Copy,
{
    let ncols = df0.ncols();
    let nrows = df0.nrows();

    if ncols == 0 {
        return Err("df0 has zero columns".to_string());
    }
    if ncols != col_names.len() {
        return Err(format!(
            "number of column names ({}) does not match number of columns ({})",
            col_names.len(),
            ncols
        ));
    }

    let mut result = Vec::with_capacity(nrows);

    for i in 0..nrows {
        let row = df0.row(i);
        // Initialize with first element
        let mut max_idx = 0usize;
        let mut max_val = row[0];

        for (j, &v) in row.iter().enumerate().skip(1) {
            if v > max_val {
                max_val = v;
                max_idx = j;
            }
        }

        result.push(col_names[max_idx].to_string());
    }

    Ok(result)
}

fn main() {
    // Example: a 3x3 table (each row is an observation, columns are features)
    let df0: Array2<f64> = array![
        [1.0, 3.5, 2.2],
        [4.1, 2.0, 5.0],
        [0.0, 0.0, 0.0]
    ];
