fn remove_columns(mat0: &CsMat<f64>, columns_to_delete: &[usize]) -> CsMat<f64> {
    // Create a set of columns to delete for faster lookup
    let delete_set: std::collections::HashSet<usize> = columns_to_delete.iter().cloned().collect();

    // Filter out the columns we want to keep
    let num_cols = mat0.ncols();
    let mut retained_columns = Vec::with_capacity(num_cols);
    for col in 0..num_cols {
        if !delete_set.contains(&col) {
            retained_columns.push(col);
        }
    }

    // Create a new matrix with only the retained columns
    let mut indptr = vec![0];
    let mut indices = Vec::new();
    let mut data = Vec::new();

    for row in 0..mat0.nrows() {
        let start = mat0.indptr()[row];
        let end = mat0.indptr()[row + 1];
        for &(col, value) in mat0.outer_view().row(row).iter() {
