        }
        indptr.push(indices.len());
    }

    // Adjust the column count for the new matrix
    let new_num_cols = retained_columns.len();

    // Build and return the new matrix
    CsMat::new_csc((mat0.nrows(), new_num_cols), indptr, indices, data)
