        return Sprs::new(mat0.rows(), 0);
    }

    // Create a sorted set of columns to delete for efficient lookup
    let mut delete_set: Vec<usize> = columns_to_delete.to_vec();
    delete_set.sort();
    delete_set.dedup();

    // Calculate new number of columns
    let new_cols = mat0.cols() - delete_set.len();

    // Create new matrix with same number of rows but fewer columns
    let mut result = Sprs::new(mat0.rows(), new_cols);

    // Track current position in the result matrix
    let mut result_col = 0;
    let mut delete_idx = 0;

    // Iterate through original columns
    for orig_col in 0..mat0.cols() {
        // Check if this column should be deleted
        if delete_idx < delete_set.len() && delete_set[delete_idx] == orig_col {
            // Skip this column
            delete_idx += 1;
            continue;
        }

        // Copy all non-zero elements from this column to the result
        let col_start = mat0.col_ptr()[orig_col];
        let col_end = mat0.col_ptr()[orig_col + 1];

        for i in col_start..col_end {
            let row = mat0.row_ind()[i];
            let val = mat0.values()[i];
            result.push(row, result_col, val);
        }

        result_col += 1;
    }

    result
}

