# Rust Function to Remove Columns from a Matrix

```rust
use sprs::CsMat;

/// Remove columns from a sparse matrix based on their indices.
///
/// # Arguments
/// * `mat0` - The input sparse matrix
/// * `columns_to_delete` - A sequence of column indices to remove
///
/// # Returns
/// A new matrix with the specified columns removed
fn remove_columns<T: Clone + Default + sprs::MulAcc>(
    mat0: &CsMat<T>,
    columns_to_delete: &[usize],
) -> CsMat<T> {
    let mut cols_to_delete_set = std::collections::HashSet::new();
    for &col_idx in columns_to_delete {
        cols_to_delete_set.insert(col_idx);
    }

    let original_cols = mat0.cols();
    let original_rows = mat0.rows();

    // Create a mapping from old column indices to new column indices
    let mut col_mapping = Vec::new();
    let mut new_col_count = 0;
    for col_idx in 0..original_cols {
        if !cols_to_delete_set.contains(&col_idx) {
            col_mapping.push(Some(new_col_count));
            new_col_count += 1;
        } else {
            col_mapping.push(None);
        }
    }

    // Build the new matrix by iterating through non-zero elements
    let mut new_rows = Vec::new();
    let mut new_cols = Vec::new();
    let mut new_data = Vec::new();

    for (row_idx, col_idx, &val) in mat0.iter() {
        if let Some(new_col_idx) = col_mapping[col_idx] {
            new_rows.push(row_idx);
            new_cols.push(new_col_idx);
            new_data.push(val);
        }
    }

    // Create the new sparse matrix in COO format and convert to CSR
    let coo = sprs::TriMat::from_triplets(
        (original_rows, new_col_count),
        new_rows,
        new_cols,
        new_data,
    );

    coo.to_csr()
}

