    // Use a HashMap to count occurrences of each pair
    let mut frequency_map: HashMap<(String, String), usize> = HashMap::new();

    // Iterate through the table and count each pair
    for row in table {
        let pair = (row.col1.clone(), row.col2.clone());
        *frequency_map.entry(pair).or_insert(0) += 1;
    }

    // Convert HashMap to Vec of tuples
    let mut result: Vec<((String, String), usize)> = frequency_map
        .into_iter()
        .collect();

    // Sort by frequency (count) in descending order
    result.sort_by(|a, b| b.1.cmp(&a.1));

    result
}

