use chrono::{DateTime, Duration, TimeZone};
use std::collections::VecDeque;

#[derive(Debug)]
struct DataFrame {
    timestamps: Vec<DateTime<chrono::Utc>>,
    values: Vec<f64>,
}

impl DataFrame {
    fn moving_average(&self, window_duration: Duration) -> Vec<f64> {
        let mut moving_averages = Vec::new();
        let mut window: VecDeque<f64> = VecDeque::new();
        let mut window_sum = 0.0;

        let mut start_index = 0;

        for i in 0..self.timestamps.len() {
            // Add current value to the window and sum
            window.push_back(self.values[i]);
            window_sum += self.values[i];

            // Adjust the window: remove elements outside of the window_duration
            while start_index < i && self.timestamps[i] - self.timestamps[start_index] > window_duration {
                window_sum -= window.pop_front().unwrap();
                start_index += 1;
            }

            // Calculate the moving average
            let avg = if window.len() > 0 {
                window_sum / window.len() as f64
            } else {
                0.0
            };

            moving_averages.push(avg);
        }

        moving_averages
    }
}

