use polars::prelude::*;
use std::time::Duration;

/// Computes a time-based moving average of values in a DataFrame
///
/// # Arguments
/// * `df` - Input DataFrame containing the data
/// * `value_col` - Name of the column containing numeric values
/// * `time_col` - Name of the column containing timestamps
/// * `window_duration` - Duration of the moving window
///
/// # Returns
/// A new DataFrame with the moving average column added
pub fn time_based_moving_average(
    df: &DataFrame,
    value_col: &str,
    time_col: &str,
    window_duration: Duration,
) -> Result<DataFrame, PolarsError> {
    // Convert duration to milliseconds for polars
    let window_ms = window_duration.as_millis() as i64;

    // Ensure the columns exist
    if !df.column(time_col).is_ok() {
        return Err(PolarsError::ColumnNotFound(time_col.to_string()));
    }
    if !df.column(value_col).is_ok() {
        return Err(PolarsError::ColumnNotFound(value_col.to_string()));
    }

    // Convert time column to datetime if it isn't already
    let time_series = df.column(time_col)?
        .utf8()?
        .into_datetime()?
        .into_object()?;

    // Create a new DataFrame with just the time and value columns
    let df_filtered = df.lazy()
        .select(&[time_col, value_col])
        .collect()?;

    // Compute the moving average using rolling window
    let moving_avg = df_filtered.lazy()
        .with_column(
            col(value_col)
                .rolling_mean(window_ms, time_series)
                .over(time_col)
        )
        .collect()?;

    Ok(moving_avg)
}

