/// Computes a time-based moving average using time-series crate
pub fn time_based_moving_average_ts(
    values: &[f64],
    timestamps: &[i64], // timestamps in milliseconds since epoch
    window_duration: Duration,
) -> Vec<f64> {
    let window_ms = window_duration.as_millis() as i64;
    let mut result = Vec::with_capacity(values.len());

    for (i, &ts) in timestamps.iter().enumerate() {
        // Find all points within the window
        let start = ts - window_ms;
        let end = ts;

