    let mut filter_values = BooleanArray::builder(batch.num_rows());

    // Process each condition
    for (column_name, (op, value)) in conditions {
        // Find the column index
        let field = schema
            .field_with_name(column_name)
            .ok_or_else(|| format!("Column '{}' not found", column_name))?;

        // Get the array data
        let array = batch.column(field.index()).as_any().downcast_ref::<ArrayRef>()
            .ok_or_else(|| format!("Column '{}' has unsupported type", column_name))?;

