                if let Some(int_array) = array.downcast_ref::<Int32Array>() {
                    for i in 0..batch.num_rows() {
                        filter_values.append_value(int_array.value(i) > numeric_value as i32);
                    }
                } else {
                    return Err(format!("Column '{}' is not Int32", column_name));
                }
            }
            (DataType::Int32, "<", numeric_value) => {
                if let Some(int_array) = array.downcast_ref::<Int32Array>() {
                    for i in 0..batch.num_rows() {
                        filter_values.append_value(int_array.value(i) < numeric_value as i32);
                    }
                } else {
                    return Err(format!("Column '{}' is not Int32", column_name));
                }
            }
            (DataType::Int32, "=", numeric_value) => {
                if let Some(int_array) = array.downcast_ref::<Int32Array>() {
                    for i in 0..batch.num_rows() {
                        filter_values.append_value(int_array.value(i) == numeric_value as i32);
                    }
                } else {
                    return Err(format!("Column '{}' is not Int32", column_name));
                }
            }
            // String comparison
            (DataType::Utf8, "=", string_value) => {
                if let Some(string_array) = array.downcast_ref::<StringArray>() {
                    for i in 0..batch.num_rows() {
                        filter_values.append_value(
                            string_array.value(i).map_or(false, |s| s == string_value)
                        );
                    }
                } else {
                    return Err(format!("Column '{}' is not String", column_name));
                }
            }
            // Unsupported operation
            _ => return Err(format!("Unsupported operation '{}' for column '{}'", op, column_name)),
        }

        // Combine with existing filter values (AND operation)
        if !filter_values.is_empty() {
            let current_values = filter_values.finish();
            filter_values = BooleanArray::builder(batch.num_rows())
                .append(&current_values)
                .finish();
        }
    }

    // If no conditions, return the original batch
    if conditions.is_empty() {
        return Ok(batch.clone());
    }

    // Apply the final filter
    let filter_array = filter_values.finish();
    let filtered_batch = batch.slice(&filter_array);

