        .iter()
        .enumerate()
        .filter(|(_, &mask)| mask)
        .map(|(idx, _)| idx)
        .collect();

    // Create filtered batch
    let filtered_columns: Vec<Arc<dyn Array>> = batch
        .columns()
        .iter()
        .map(|col| {
            let filtered: Vec<Option<&dyn Array>> = selected_indices
                .iter()
                .map(|&idx| Some(col.as_ref()))
                .collect();
            // Use arrow's take function to filter
            arrow::compute::take(col.as_ref(), &Int64Array::from(
                selected_indices.iter().map(|&i| i as i64).collect::<Vec<i64>>()
            )).unwrap()
        })
        .collect();

    Ok(RecordBatch::try_new(batch.schema().clone(), filtered_columns)
        .map_err(|e| format!("Failed to create filtered batch: {}", e))?)
}

