        .as_any()
        .downcast_ref::<StringArray>()
        .ok_or("Failed to downcast to StringArray")?;

    let result: Vec<bool> = (0..string_array.len())
        .map(|i| {
            if string_array.is_null(i) {
                return false;
            }
            let cell_value = string_array.value(i);
            match operator {
                "eq" => cell_value == value,
                "neq" => cell_value != value,
                "gt" => cell_value > value,
                "gte" => cell_value >= value,
                "lt" => cell_value < value,
                "lte" => cell_value <= value,
                _ => false,
            }
        })
        .collect();

    Ok(result)
