        .downcast_ref::<Int64Array>()
        .ok_or("Failed to downcast to Int64Array")?;

    let compare_value: i64 = value
        .parse()
        .map_err(|_| format!("Invalid integer value: {}", value))?;

    let result: Vec<bool> = (0..int_array.len())
        .map(|i| {
            if int_array.is_null(i) {
