            match operator {
                "eq" => cell_value == compare_value,
                "neq" => cell_value != compare_value,
                "gt" => cell_value > compare_value,
                "gte" => cell_value >= compare_value,
                "lt" => cell_value < compare_value,
                "lte" => cell_value <= compare_value,
