use arrow::array::{Array, BooleanArray, RecordBatch};
use arrow::compute::kernels::boolean;
use arrow::datatypes::Schema;
use std::sync::Arc;

/// Filters a RecordBatch according to multiple conditions.
///
/// # Arguments
/// * `batch` - The input RecordBatch to filter
/// * `conditions` - A vector of BooleanArrays representing filter conditions.
///                  All conditions must have the same length as the batch.
///
/// # Returns
/// * A filtered RecordBatch containing only rows where all conditions are true
///
/// # Example
/// ```
/// use arrow::array::{BooleanArray, RecordBatch, StringArray, Int32Array};
/// use arrow::datatypes::{DataType, Field, Schema};
/// use std::sync::Arc;
///
/// // Create sample data
/// let schema = Arc::new(Schema::new(vec![
///     Field::new("name", DataType::Utf8, false),
///     Field::new("age", DataType::Int32, false),
/// ]));
///
/// let names = Arc::new(StringArray::from(vec!["Alice", "Bob", "Charlie"]));
/// let ages = Arc::new(Int32Array::from(vec![30, 25, 35]));
///
/// let batch = RecordBatch::try_new(
///     schema.clone(),
///     vec![names, ages],
/// ).unwrap();
///
/// // Create filter conditions
/// let condition1 = BooleanArray::from(vec![true, false, true]);  // age > 28
/// let condition2 = BooleanArray::from(vec![true, true, false]);  // name starts with 'A' or 'B'
///
/// let filtered = filter_rows(&batch, &vec![condition1, condition2]).unwrap();
/// assert_eq!(filtered.num_rows(), 1); // Only Alice matches both conditions
/// ```
pub fn filter_rows(
    batch: &RecordBatch,
    conditions: &[BooleanArray],
) -> Result<RecordBatch, Box<dyn std::error::Error>> {
    if conditions.is_empty() {
        return Ok(batch.clone());
    }

    // Validate that all conditions have the same length as the batch
    for condition in conditions {
        if condition.len() != batch.num_rows() {
            return Err("Condition length mismatch with batch row count".into());
        }
    }

    // Combine all conditions with AND operation
    let mut combined_filter = conditions[0].clone();

    for condition in &conditions[1..] {
        combined_filter = boolean::and(&combined_filter, condition)
            .map_err(|e| format!("Failed to combine conditions: {}", e))?;
    }

    // Apply the combined filter to the batch
    let filtered_batch = batch
        .filter(&combined_filter)
        .map_err(|e| format!("Failed to filter batch: {}", e))?;

    Ok(filtered_batch)
}

