///
/// # Returns
/// A new `LinkedHashMap` with entries sorted by the maximum value in each sequence in descending order.
pub fn sort_by_max_sequence<T: Ord + Copy>(mut map: LinkedHashMap<String, Vec<T>>) -> LinkedHashMap<String, Vec<T>> {
