```rust
use linked_hash_map::LinkedHashMap;
use std::hash::Hash;

/// Reorder entries of `map` so entries are sorted by the maximum value in the
/// associated `Vec<N>`, in descending order. Empty vectors are considered to
/// have no maximum and are placed after non-empty sequences.
///
/// Consumes the input `map` and returns a new `LinkedHashMap` with the desired order.
///
/// K: key type (consumed), N: numeric type which can be ordered and cloned.
pub fn reorder_by_max_desc<K, N>(map: LinkedHashMap<K, Vec<N>>) -> LinkedHashMap<K, Vec<N>>
where
    K: Eq + Hash,
    N: Ord + Clone,
{
    // Collect entries along with the computed max for each value vector.
    let mut entries: Vec<(Option<N>, K, Vec<N>)> = map
        .into_iter()
        .map(|(k, v)| {
            let max_opt = v.iter().max().cloned();
            (max_opt, k, v)
        })
        .collect();

    // Stable sort by the max: Some(x) > None, and among Some compare descending.
    entries.sort_by(|a, b| match (&a.0, &b.0) {
        (Some(x), Some(y)) => y.cmp(x),       // descending: larger max first
        (Some(_), None) => std::cmp::Ordering::Less,
        (None, Some(_)) => std::cmp::Ordering::Greater,
        (None, None) => std::cmp::Ordering::Equal,
    });

