/// # Arguments
/// * `map` - A LinkedHashMap where values are sequences (Vec<i32>)
///
/// # Returns
/// A new LinkedHashMap with entries sorted by max value in descending order
fn reorder_by_max_descending(
    map: LinkedHashMap<String, Vec<i32>>,
) -> LinkedHashMap<String, Vec<i32>> {
    // Convert to a vector of (key, value) pairs
    let mut entries: Vec<(String, Vec<i32>)> = map.into_iter().collect();

    // Sort by the maximum value in each sequence in descending order
    entries.sort_by(|a, b| {
        let max_a = a.1.iter().max().copied().unwrap_or(i32::MIN);
        let max_b = b.1.iter().max().copied().unwrap_or(i32::MIN);
        // Reverse the comparison for descending order
        max_b.cmp(&max_a)
    });

    // Rebuild the LinkedHashMap with sorted entries
    let mut result = LinkedHashMap::new();
    for (key, value) in entries {
        result.insert(key, value);
    }

    result
}

