use polars::prelude::*;

/// Groups a DataFrame by a string column and calculates mean and sum of another string column
/// 
/// # Arguments
/// * `df0` - Input DataFrame containing the data
/// * `str0` - Name of the column to group by (string type)
/// * `str1` - Name of the column to aggregate (string type, will be parsed as numeric)
/// 
/// # Returns
/// * `Result<DataFrame>` - DataFrame with group, mean, and sum columns
pub fn group_and_aggregate(df0: &DataFrame, str0: &str, str1: &str) -> PolarsResult<DataFrame> {
    // First, convert the string column to numeric (f64) for aggregation
    let df_with_numeric = df0
        .clone()
        .lazy()
        .with_column(
            col(str1)
                .str()
                .replace_all(",", "")  // Remove commas if present
                .str()
                .to_integer(LiteralValue::Int64(0))  // Parse as integer first
                .cast(DataType::Float64)  // Convert to float for mean calculation
                .alias("numeric_value")
        )
        .collect()?;

    // Group by the string column and aggregate
    let result = df_with_numeric
        .lazy()
        .group_by([col(str0)])
        .agg([
            col("numeric_value").mean().alias("mean"),
            col("numeric_value").sum().alias("sum"),
        ])
        .collect()?;

    Ok(result)
}

