fn calculate_means(data: &Array2<f64>, column_names: &[&str]) -> HashMap<String, f64> {
    let mut means = HashMap::new();

    // Group columns by their names
    let mut grouped_columns: HashMap<String, Vec<usize>> = HashMap::new();
