Code (copy into a file, add smallvec to Cargo.toml as shown after):

```rust
use smallvec::SmallVec;

/// Duplicate each element of `lst0` `var0` times and return the result in a SmallVec.
/// - `T: Clone` is required because we clone elements.
/// - `N` is the inline capacity (caller picks it via the return type).
///
/// Example:
/// let out: SmallVec<[i32; 4]> = duplicate_each(&[1, 2, 3], 2);
/// assert_eq!(&*out, &[1,1,2,2,3,3]);
pub fn duplicate_each<T: Clone, const N: usize>(lst0: &[T], var0: usize) -> SmallVec<[T; N]> {
    if var0 == 0 || lst0.is_empty() {
        return SmallVec::new();
    }

    // Prevent overflow in capacity calculation; saturating_mul returns usize::MAX on overflow.
    let total = lst0.len().saturating_mul(var0);
    let mut out: SmallVec<[T; N]> = SmallVec::with_capacity(total);

    for item in lst0 {
        for _ in 0..var0 {
            out.push(item.clone());
        }
    }

    out
}

