    fn basic_duplicates() {
        let v = [1, 2, 3];
        let out: SmallVec<[i32; 4]> = duplicate_each(&v, 2);
        assert_eq!(&*out, &[1,1,2,2,3,3]);
    }

    #[test]
    fn zero_times() {
        let v = [1, 2];
        let out: SmallVec<[i32; 2]> = duplicate_each(&v, 0);
