pub async fn reset_index(
    df: DataFrame,
    index_col_name: Option<&str>,
    new_index_name: &str,
) -> Result<DataFrame, Box<dyn std::error::Error>> {
    use datafusion::functions::row_number;
    use datafusion::window_frame::{WindowFrame, WindowFrameUnits};
    use datafusion::functions::BuiltinScalarFunction;

    let ctx = SessionContext::new();

    // Register the dataframe as a table
    let table_name = "temp_table";
    ctx.register_dataframe(table_name, df).await?;

    // Build the SQL query to add row number and optionally rename the index column
    let query = if let Some(idx_col) = index_col_name {
        // If there's an existing index column, keep it as a regular column and add row number
        format!(
            "SELECT 
                ROW_NUMBER() OVER (ORDER BY 1) AS {new_index_name},
                {idx_col},
                *
            FROM {table_name}
            EXCEPT 
            SELECT 
                ROW_NUMBER() OVER (ORDER BY 1) AS {new_index_name},
                {idx_col},
                {idx_col}
            FROM {table_name}"
        )
    } else {
        // If no existing index, just add row number to all columns
        format!(
            "SELECT 
                ROW_NUMBER() OVER (ORDER BY 1) AS {new_index_name},
                *
            FROM {table_name}"
        )
    };

    // Execute the query
    let result_df = ctx.sql(&query).await?;

    Ok(result_df)
