use polars::prelude::*;
use serde::Serialize;
use serde_value::Value;

/// Convert a labeled tabular dataset into a list of dictionaries, each representing one row
/// and including the row's index alongside its column-value pairs.
fn dataframe_to_dict_list(df: &DataFrame) -> Result<Vec<Value>, Box<dyn std::error::Error>> {
    // Ensure the DataFrame has a valid schema
    let schema = df.schema();

    // Create a vector to hold the serialized rows
    let mut dict_list = Vec::new();

    // Iterate over the rows of the DataFrame
    for (index, row) in df.iter_rows().enumerate() {
        // Create a map to hold the column-value pairs
        let mut row_map = std::collections::HashMap::new();

        // Insert the index as a key-value pair
        row_map.insert("index".to_string(), Value::Usize(index));

        // Iterate over the columns and their corresponding values in the current row
        for (field, value) in schema.fields().iter().zip(row.iter()) {
            // Serialize the value to a serde_value::Value
            let serialized_value = match value {
                AnyValue::Boolean(v) => Value::Bool(*v),
                AnyValue::Utf8(v) => Value::String(v.to_string()),
                AnyValue::Int32(v) => Value::I32(*v),
                AnyValue::Int64(v) => Value::I64(*v),
                AnyValue::Float32(v) => Value::F32(*v),
                AnyValue::Float64(v) => Value::F64(*v),
                _ => return Err(format!("Unsupported data type: {:?}", field.data_type()).into()),
            };

            // Insert the column name and serialized value into the map
            row_map.insert(field.name().to_string(), serialized_value);
        }

        // Convert the map to a serde_value::Value and add it to the list
        dict_list.push(Value::Map(row_map));
    }

    Ok(dict_list)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Example usage: create a sample DataFrame
    let s0 = Series::new("index", &[0, 1, 2]);
    let s1 = Series::new("name", &["Alice", "Bob", "Charlie"]);
    let s2 = Series::new("age", &[30, 25, 35]);
