    let df = DataFrame::new(vec![s1, s2, s3])?;

    // Convert the DataFrame to a list of dictionaries
    let dict_list = dataframe_to_dict_list(&df)?;

    // Print the result
    for value in dict_list {
        println!("{:?}", value);
    }

    Ok(())
}
```

