```rust
use serde_value::Value;

/// A minimal DataFrame-like structure for the example.
#[derive(Debug)]
struct DataFrame {
    /// Column names (labels)
    columns: Vec<String>,
    /// Row indices (one per row). Using serde_value::Value so indices can be strings or ints, etc.
    index: Vec<Value>,
    /// Rows: each row is a Vec of values (must match columns.len()).
    data: Vec<Vec<Value>>,
}

/// Convert the DataFrame into a list of dictionaries (serde_value::Value::Map),
/// each containing the row index under the key "index" and all column -> value pairs.
/// Returns Err on shape mismatch.
fn df_to_list_of_dicts(df: &DataFrame) -> Result<Vec<Value>, String> {
    let nrows = df.data.len();
    if df.index.len() != nrows {
        return Err(format!(
            "index length ({}) does not match number of rows ({})",
            df.index.len(),
            nrows
        ));
    }
    let ncols = df.columns.len();

    let mut out = Vec::with_capacity(nrows);
    for (i, row) in df.data.iter().enumerate() {
        if row.len() != ncols {
            return Err(format!(
                "row {} length ({}) does not match number of columns ({})",
                i,
                row.len(),
                ncols
            ));
        }

        // Build a Map: Vec<(Value, Value)>
        let mut map: Vec<(Value, Value)> = Vec::with_capacity(ncols + 1);

        // Insert the index under key "index"
        map.push((Value::String("index".into()), df.index[i].clone()));

        // Insert each column -> value
        for (col, val) in df.columns.iter().zip(row.iter()) {
            map.push((Value::String(col.clone()), val.clone()));
        }

        out.push(Value::Map(map));
    }

    Ok(out)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Example usage:
    let df = DataFrame {
        columns: vec!["name".into(), "score".into()],
        index: vec![Value::I64(0), Value::I64(1)],
        data: vec![
            vec![Value::String("Alice".into()), Value::I64(95)],
            vec![Value::String("Bob".into()), Value::I64(88)],
        ],
    };

    let list_of_dicts = df_to_list_of_dicts(&df)?;
    // Serialize to pretty JSON for demonstration:
    let json = serde_json::to_string_pretty(&list_of_dicts)?;
    println!("{}", json);

    Ok(())
}
```

