/// ```
/// use std::collections::HashMap;
/// use serde_json::Value;
///
/// let mut row1 = HashMap::new();
/// row1.insert("name".to_string(), "Alice".to_string());
/// row1.insert("age".to_string(), "30".to_string());
///
/// let mut row2 = HashMap::new();
/// row2.insert("name".to_string(), "Bob".to_string());
/// row2.insert("age".to_string(), "25".to_string());
///
/// let df = vec![row1, row2];
/// let result = labeled_tabular_to_dicts(df, "index");
/// ```
pub fn labeled_tabular_to_dicts(
    df: Vec<HashMap<String, String>>,
    index_name: &str,
) -> Vec<Value> {
    df.into_iter()
        .enumerate()
        .map(|(idx, row)| {
            // Create a new HashMap for the row, starting with the index
            let mut row_with_index = HashMap::new();

            // Add the index
            row_with_index.insert(index_name.to_string(), idx.to_string());

            // Add all column-value pairs from the original row
            for (key, value) in row {
                row_with_index.insert(key, value);
            }

            // Convert the HashMap to a serde_json::Value
            to_value(&row_with_index).unwrap_or(Value::Null)
        })
        .collect()
}

