# Rust Function: Convert DataFrame to List of Dictionaries

```rust
use serde_json::{json, Map, Value};

/// Converts a labeled tabular dataset into a list of dictionaries.
/// Each dictionary represents one row, including the row index and column-value pairs.
///
/// # Arguments
/// * `df` - A vector of vectors where the first row contains column headers
///
/// # Returns
/// A JSON array where each element is an object with the row index and column values
///
/// # Example
/// ```
/// let df = vec![
///     vec!["name", "age", "city"],
///     vec!["Alice", "30", "NYC"],
///     vec!["Bob", "25", "LA"],
/// ];
/// let result = dataframe_to_dicts(df);
/// // Result: [{"index": 0, "name": "Alice", "age": "30", "city": "NYC"}, ...]
/// ```
fn dataframe_to_dicts(df: Vec<Vec<&str>>) -> Value {
    if df.is_empty() {
        return Value::Array(vec![]);
    }

    let headers = &df[0];
    let mut result = Vec::new();

    for (row_index, row) in df.iter().skip(1).enumerate() {
        let mut row_dict = Map::new();

        // Add the row index
        row_dict.insert("index".to_string(), json!(row_index));

        // Add column-value pairs
        for (col_index, &header) in headers.iter().enumerate() {
            let value = row.get(col_index).unwrap_or(&"");
            row_dict.insert(header.to_string(), json!(value));
        }

        result.push(Value::Object(row_dict));
    }

    Value::Array(result)
}

fn main() {
    // Example usage
    let df = vec![
        vec!["name", "age", "city"],
        vec!["Alice", "30", "NYC"],
        vec!["Bob", "25", "LA"],
