///
/// Example:
///   let xs = vec!["a", "b", "a", "c"];
///   let codes = factorize(&xs); // -> [0, 1, 0, 2]
pub fn factorize<T>(items: &[T]) -> Vec<usize>
where
    T: Eq + Hash + Clone,
