pub fn reset_index(df0: DataFrame, index_name0: &str) -> Result<DataFrame> {
    // Add a new column with sequential row numbers starting from 0
    let n_rows = df0.height();
    let new_index = (0u32..n_rows as u32).collect::<Vec<u32>>();
