use ndarray::{Array1, Array2};
use ndarray_stats::SummaryStatisticsExt;

/// Replace missing entries (None) in `data` with the mean of their column.
///
/// - Input: Array2<Option<f64>>
/// - Output: Array2<f64> (missing entries replaced; columns that are entirely missing become NaN)
pub fn impute_column_means(data: &Array2<Option<f64>>) -> Array2<f64> {
    let (n_rows, n_cols) = data.dim();
    let mut out = Array2::<f64>::zeros((n_rows, n_cols));

    for j in 0..n_cols {
        // Collect non-missing values in column j
        let non_missing: Vec<f64> = data
            .column(j)
            .iter()
            .filter_map(|&v| v) // &Option<f64> -> Option<f64> via copy; keep only Some(x)
            .collect();

        // Compute mean using ndarray-stats (returns Option<f64>, None only if empty)
        let col_mean = if non_missing.is_empty() {
            f64::NAN
        } else {
            let arr: Array1<f64> = Array1::from(non_missing);
            arr.mean().unwrap_or(f64::NAN)
        };

        // Fill output: keep present values, substitute column mean for missing ones
        for i in 0..n_rows {
            out[(i, j)] = data[(i, j)].unwrap_or(col_mean);
        }
    }

    out
}
