/// * `col0_idx` - The index of the column to sort by first
/// * `col1_idx` - The index of the column to sort by second
///
/// # Returns
/// A new RecordBatch sorted by the specified columns
pub fn sort_record_batch(
    batch: &RecordBatch,
    col0_idx: usize,
    col1_idx: usize,
) -> Result<RecordBatch, arrow2::error::ArrowError> {
    // Get the schema and columns from the input batch
    let schema = batch.schema();
    let col0 = batch.column(col0_idx).clone();
    let col1 = batch.column(col1_idx).clone();

    // Create a new schema with the same fields (we'll reuse the original schema)
    let new_schema = schema.clone();

    // Create a new array that will hold the sorted indices
    let mut indices = (0..batch.num_rows()).collect::<Vec<_>>();

    // Sort the indices based on the values in col0 and col1
    indices.sort_by(|&i, &j| {
        // Compare col0 first
        let cmp0 = col0.value(i).cmp(&col1.value(j));
        if cmp0 != std::cmp::Ordering::Equal {
            return cmp0;
        }

        // If col0 values are equal, compare col1
        col0.value(i).cmp(&col1.value(j))
    });

    // Create a new RecordBatch with the rows in the new order
    let mut new_columns = Vec::with_capacity(batch.num_columns());
    for col_idx in 0..batch.num_columns() {
        let col = batch.column(col_idx).clone();
        let new_col = col.take().reorder(&indices)?;
        new_columns.push(new_col);
    }

    Ok(RecordBatch::try_new(new_schema, new_columns)?)
}

