```rust
use enum_map::{enum_map, Enum, EnumMap};

/// Convert an `EnumMap<K, V>` into a `Vec<(K, T)>`.
///
/// The element type `T` of the resulting sequence is determined by the
/// conversion closure `conv: F` which is applied to each map value `V`.
///
/// - `K` must be an enum type that implements `Enum` (derive with `#[derive(Enum)]`).
/// - `F` converts a `V` into the desired `T`.
///
/// Example:
/// ```
/// # use enum_map::{enum_map, Enum, EnumMap};
/// # use crate::enum_map_to_seq;
/// #[derive(Enum, Copy, Clone, Debug, PartialEq, Eq)]
/// enum Color { Red, Green, Blue }
///
/// let m: EnumMap<Color, i32> = enum_map! {
///     Color::Red => 10,
///     Color::Green => 20,
///     Color::Blue => 30,
/// };
///
/// // Convert values to strings; resulting Vec element type is (Color, String)
/// let seq = enum_map_to_seq(m, |v| format!("{} pcs", v));
/// println!("{:?}", seq);
/// ```
pub fn enum_map_to_seq<K, V, T, F>(map: EnumMap<K, V>, mut conv: F) -> Vec<(K, T)>
where
    K: Enum + Copy,
    F: FnMut(V) -> T,
{
    // EnumMap implements IntoIterator yielding (K, V) pairs
    map.into_iter().map(|(k, v)| (k, conv(v))).collect()
}

// Example usage in a main function
fn main() {
    #[derive(Enum, Copy, Clone, Debug, PartialEq, Eq)]
    enum Fruit { Apple, Banana, Orange }

    let m: EnumMap<Fruit, i32> = enum_map! {
        Fruit::Apple => 3,
        Fruit::Banana => 5,
        Fruit::Orange => 2,
    };

    // Produce Vec<(Fruit, String)> by specifying the conversion to String
    let seq: Vec<(Fruit, String)> = enum_map_to_seq(m, |count| format!("{} pcs", count));
    println!("{:?}", seq);
}
```

Notes:
- The caller controls the output tuple element type via the generic T and the conversion closure F.
- If you want to keep values by reference instead of moving them, accept `&EnumMap<K, V>` and use `.iter()` with an appropriate mapping to `(K, &V)` (requires adjusting bounds).

