```rust
use fancy_regex::Regex;

fn count_word_occurrences(text: &str, word: &str) -> usize {
    // Create a regular expression pattern that matches the specified word as a whole word
    // The `\b` ensures word boundaries
    let pattern = format!(r"\b{}\b", regex::escape(word));
    let regex = Regex::new(&pattern).unwrap();

    // Count occurrences
    let mut count = 0;
    let mut search_start = 0;

    while let Some(m) = regex.find(&text[search_start..]).unwrap() {
        count += 1;
        search_start += m.end(); // Move past the last match
    }

    count
}

fn main() {
    let text = "hello world! Hello there, hello";
    let word = "hello";
    let occurrences = count_word_occurrences(text, word);

    println!("The word '{}' occurs {} times.", word, occurrences);
}
