/// # Arguments
/// * `lst0` - The first input sequence
/// * `lst1` - The second input sequence (will be processed in reverse order)
///
/// # Returns
/// An ArrayDeque containing the interleaved elements
pub fn alternate_interleave<T: Clone, const N: usize>(
    lst0: &ArrayDeque<T, N, Wrapping>,
    lst1: &ArrayDeque<T, N, Wrapping>,
) -> ArrayDeque<T, { 2 * N }, Wrapping> {
    let mut result: ArrayDeque<T, { 2 * N }, Wrapping> = ArrayDeque::new();

    let len0 = lst0.len();
    let len1 = lst1.len();
    let max_len = len0.max(len1);

    for i in 0..max_len {
        // Take from lst0 if available
        if i < len0 {
            if let Some(element) = lst0.get(i) {
                result.push_back(element.clone());
            }
        }

        // Take from lst1 in reverse order if available
        if i < len1 {
            let reverse_index = len1 - 1 - i;
            if let Some(element) = lst1.get(reverse_index) {
                result.push_back(element.clone());
            }
        }
    }

    result
}

