use std::collections::VecDeque;

/// Generate a new sequence by alternately taking elements from lst0 and lst1 (in reverse).
/// 
/// # Arguments
/// * `lst0` - First input sequence
/// * `lst1` - Second input sequence (will be iterated in reverse)
/// 
/// # Returns
/// A VecDeque containing elements alternately taken from lst0 and lst1 (reversed)
/// 
/// # Example
/// ```
/// let lst0 = vec![1, 2, 3];
/// let lst1 = vec![10, 20, 30];
/// let result = alternate_sequences(lst0, lst1);
/// // Result: [1, 30, 2, 20, 3, 10]
/// ```
fn alternate_sequences<T: Clone>(lst0: Vec<T>, lst1: Vec<T>) -> VecDeque<T> {
    let mut result = VecDeque::new();
    let mut iter0 = lst0.into_iter();
    let mut iter1 = lst1.into_iter().rev();

    loop {
        match iter0.next() {
            Some(val) => result.push_back(val),
            None => break,
        }

        match iter1.next() {
            Some(val) => result.push_back(val),
            None => break,
        }
    }

    result
}

