pub fn sum_duplicate_columns(data: &CavDataset) -> CavResult<CavDataset> {
    // Get the headers from the dataset
    let headers = data.headers();

    // Create a map to track which columns to sum together
    // Key: header name, Value: list of column indices
    let mut header_groups: HashMap<&str, Vec<usize>> = HashMap::new();

    // Group column indices by their header names
    for (idx, header) in headers.iter().enumerate() {
        header_groups.entry(header.as_str())
            .or_insert_with(Vec::new)
            .push(idx);
    }

    // Get the number of rows in the dataset
    let num_rows = data.nrows();

    // Create vectors to hold the new column data
    let mut new_headers: Vec<String> = Vec::new();
    let mut new_columns: Vec<Vec<f64>> = Vec::new();

    // Process each unique header
    for (header, indices) in &header_groups {
        new_headers.push(header.to_string());

        // Initialize a vector to hold the summed values for this header
        let mut summed_column: Vec<f64> = vec![0.0; num_rows];

        // Sum the values from all columns with this header
        for &col_idx in indices {
            // Get the column data as f64 values
            if let Ok(column) = data.column(col_idx) {
                for (row_idx, value) in column.iter().enumerate() {
                    // Try to parse the value as f64, defaulting to 0.0 if it fails
                    if let Ok(num_val) = value.parse::<f64>() {
                        summed_column[row_idx] += num_val;
                    }
                }
            }
        }

        new_columns.push(summed_column);
    }

    // Build the new dataset from the processed columns
    let mut builder = CavDatasetBuilder::new();

    for (header, column) in new_headers.iter().zip(new_columns.iter()) {
        // Convert f64 values back to strings for the dataset
        let string_column: Vec<String> = column.iter()
            .map(|v| v.to_string())
