use std::collections::HashMap;
use itertools::Itertools; // from the itertools crate

#[derive(Clone, Debug)]
struct Row<K, V> {
    id: K,
    value: V,
}

/// Convert a sequence of rows (with fields `id` and `value`) into a HashMap<id, value>.
/// If an id appears multiple times, this version keeps the first occurrence (due to `unique_by`).
fn df0_to_map<K, V, I>(rows: I) -> HashMap<K, V>
where
    I: IntoIterator<Item = Row<K, V>>,
    K: Eq + std::hash::Hash + Clone,
{
    rows.into_iter()
        .unique_by(|r| r.id.clone()) // ensure unique ids; keeps the first seen
        .map(|r| (r.id, r.value))
        .collect()
}

fn main() {
    // Example input table `df0`
    let df0 = vec![
        Row { id: "a".to_string(), value: 10 },
        Row { id: "b".to_string(), value: 20 },
        Row { id: "a".to_string(), value: 30 }, // duplicate id; will be ignored here (first kept)
    ];

    let map = df0_to_map(df0);
    println!("{:?}", map); // prints something like {"a": 10, "b": 20}
}
```

