fn custom_sort(texts: Vec<&str>, positions: Option<Vec<usize>>) -> Vec<&str> {
    let mut sorted = texts.clone(); // Create a mutable clone of the texts

    if let Some(pos) = positions {
        // Get the elements at the specified positions to sort in descending order
        let mut descending_elements: Vec<&str> = pos.iter()
            .filter_map(|&i| sorted.get(i))
            .cloned()
            .collect();

        // Sort the descending elements
        descending_elements.sort_by(|a, b| b.cmp(a)); // Sort in descending order

        // Place them back to their original positions
        for (i, &val) in pos.iter().enumerate() {
            sorted[val] = descending_elements[i];
        }
    }

    // Sort the rest of the elements in ascending order
    let (asc_elements, mut descending_positions): (Vec<_>, Vec<_>) = sorted
        .iter()
        .enumerate()
        .partition(|(i, _)| positions.as_ref().map_or(true, |p| !p.contains(i)));

    // Sort the ascending elements
    let mut asc_sorted: Vec<_> = asc_elements.into_iter().map(|(_, &s)| s).collect();
    asc_sorted.sort_unstable();

    // Combine the sorted elements
    let mut result = Vec::with_capacity(sorted.len());
    let mut asc_index = 0;

    for i in 0..sorted.len() {
        if positions.as_ref().map_or(false, |p| p.contains(&i)) {
            // Use the element from the descending sorted list for this position
            result.push(descending_elements.pop().unwrap());
