///   are sorted among themselves in ascending order. Elements are written back to
///   their original indices (i.e., only the chosen positions are permuted among themselves).
///
/// Notes:
/// - Out-of-range indices in `positions` are ignored.
/// - Duplicate indices in `positions` are treated once.
/// - Uses `odqsort::sort_by` for the actual sorting steps.
///
/// Example:
/// let mut v = vec!["d".into(), "b".into(), "a".into(), "c".into()];
/// // sort indices 0 and 2 in descending among themselves, others ascending:
/// sort_text_with_mixed_dirs(&mut v, Some(&[0, 2]));
/// // result: indices {0,2} hold descending values among { "d", "a" } -> ["d", ... , "a", ...]
/// // the other indices are sorted ascending among themselves -> final vector accordingly.
pub fn sort_text_with_mixed_dirs(items: &mut [String], positions: Option<&[usize]>) {
    // If no special positions given, sort everything ascending.
    if positions.is_none() {
        // sort entire slice ascending using odqsort
        odqsort::sort_by(items, |a: &String, b: &String| a.cmp(b));
        return;
    }

    let len = items.len();
    // Build set of valid positions (deduplicated, in-range)
    let pos_set: HashSet<usize> = positions
        .unwrap()
        .iter()
        .copied()
        .filter(|&i| i < len)
        .collect();

    // If nothing valid, just sort all ascending.
    if pos_set.is_empty() {
        odqsort::sort_by(items, |a: &String, b: &String| a.cmp(b));
        return;
    }

    // Collect elements from the specified positions and from the other positions.
    let mut pos_elems: Vec<String> = pos_set.iter().copied().map(|i| items[i].clone()).collect();
    let mut other_elems: Vec<String> = (0..len)
        .filter(|i| !pos_set.contains(i))
        .map(|i| items[i].clone())
        .collect();

    // Sort the selected-position elements in descending order.
    odqsort::sort_by(&mut pos_elems, |a: &String, b: &String| b.cmp(a));
    // Sort the remaining elements in ascending order.
    odqsort::sort_by(&mut other_elems, |a: &String, b: &String| a.cmp(b));

    // Put them back into the original slice: for increasing indices,
    // fill from the corresponding sorted iterator.
    let mut pos_iter = pos_elems.into_iter();
    let mut other_iter = other_elems.into_iter();

    for i in 0..len {
        if pos_set.contains(&i) {
            // safe: pos_iter has exactly as many items as pos_set.len()
            items[i] = pos_iter.next().unwrap();
        } else {
            items[i] = other_iter.next().unwrap();
        }
    }
