/// Multiplies a numerical vector by a numerical matrix (dot product).
///
/// # Arguments
/// * `vector` - A slice of numerical values (f32 or f64)
/// * `matrix` - A 2D slice of numerical values (f32 or f64) where each row has the same length as the vector
///
/// # Returns
/// A new vector containing the result of the multiplication
///
/// # Panics
/// Panics if the vector length doesn't match the matrix row length
fn multiply_vector_by_matrix<T>(vector: &[T], matrix: &[T]) -> Vec<T>
where
    T: Copy + std::ops::Mul<Output = T> + std::ops::Add<Output = T>,
    T: std::ops::Mul<T, Output = T> + std::ops::Add<T, Output = T>,
    T: Default + std::ops::Sub<T, Output = T>,
{
    // Check dimensions
    if vector.len() != matrix.len() / matrix.iter().find_map(|row| row.len()).unwrap_or(0) {
        panic!("Vector length must match matrix row length");
    }

    // Calculate number of rows and columns in the matrix
    let rows = matrix.len();
    let cols = matrix.iter().find_map(|row| row.len()).unwrap_or(0);

    // Initialize result vector with default values
    let mut result = Vec::with_capacity(cols);

    // Perform matrix multiplication
    for j in 0..cols {
        let mut sum = T::default();
        for i in 0..rows {
            // Get the i-th row of the matrix
            let row_start = i * cols;
            let row_end = row_start + cols;
            let row = &matrix[row_start..row_end];

            // Multiply and accumulate
            sum = sum + vector[i] * row[j];
        }
        result.push(sum);
    }

    result
