fn convert_currency_to_floats(table: &mut Vec<Vec<String>>, currency_symbol: &str) -> Result<Vec<Vec<f64>>, String> {
    // Iterate through each row in the table
    for row in table.iter_mut() {
        // Check if there are at least two columns
        if row.len() < 2 {
            return Err(String::from("Each row should have at least two columns."));
        }

        // Get the penultimate column and strip the currency symbol
        let penultimate_index = row.len() - 2;
        let currency_value = &row[penultimate_index];

        // Strip currency symbol and parse to BigDecimal
        let stripped_value = currency_value
            .replace(currency_symbol, "")
            .trim();

        // Convert to BigDecimal and then to f64
        let bigdecimal_value = BigDecimal::from_str(stripped_value)
            .map_err(|_| format!("Failed to parse value: {}", stripped_value))?;

        // Store the result as f64 in the last column
        let float_value: f64 = bigdecimal_value.to_f64().ok_or_else(|| {
            format!("Failed to convert BigDecimal to f64: {}", bigdecimal_value)
