use bigdecimal::BigDecimal;
use bigdecimal::num_bigint::BigInt;
use std::str::FromStr;

/// Strips currency symbols from the penultimate column of a 2D table and converts
/// its entries to BigDecimal values.
///
/// # Arguments
/// * `table` - A 2D vector of strings representing the table
///
/// # Returns
/// A Result containing:
/// - Ok: A tuple of (the original table with modified penultimate column,
///   a vector of BigDecimal values from the penultimate column)
/// - Err: An error if conversion fails for any entry
///
/// # Example
/// ```
/// let table = vec![
///     vec!["ID".to_string(), "Amount".to_string(), "Description".to_string()],
///     vec!["1".to_string(), "$100.50".to_string(), "Purchase".to_string()],
///     vec!["2".to_string(), "€50.25".to_string(), "Payment".to_string()],
/// ];
/// let (modified_table, amounts) = strip_currency_and_convert(table).unwrap();
/// ```
pub fn strip_currency_and_convert(table: Vec<Vec<String>>) -> Result<(Vec<Vec<String>>, Vec<BigDecimal>), String> {
    // Check if table is empty or has no penultimate column
    if table.is_empty() || table[0].len() < 2 {
        return Err("Table must have at least 2 columns".to_string());
    }

    let penultimate_col_index = table[0].len() - 2;
    let mut amounts = Vec::with_capacity(table.len());
    let mut modified_table = table.clone();

    for row in &mut modified_table {
        if row.len() <= penultimate_col_index {
            return Err(format!("Row has insufficient columns (expected at least {} columns)", penultimate_col_index + 1));
        }

        let amount_str = &row[penultimate_col_index];
        let cleaned = strip_currency_symbol(amount_str)?;

        // Convert to BigDecimal
        let amount = BigDecimal::from_str(&cleaned)
            .map_err(|_| format!("Failed to parse '{}' as number", cleaned))?;

        amounts.push(amount);
        row[penultimate_col_index] = cleaned.to_string();
    }

    Ok((modified_table, amounts))
}

/// Helper function to strip common currency symbols from a string
fn strip_currency_symbol(s: &str) -> Result<String, String> {
    let cleaned = s.chars()
        .filter(|c| !c.is_ascii_whitespace() && !matches!(c, '$' | '€' | '£' | '¥' | '₽' | '₽' | '₿' | '₹' | '₩' | '₺'))
        .collect::<String>();

    if cleaned.is_empty() {
        Err("No valid number found after stripping currency symbols".to_string())
    } else {
        Ok(cleaned)
    }
}

