use bigdecimal::BigDecimal;
use num_traits::ToPrimitive;
use std::str::FromStr;

/// Extracts the penultimate column from each row of `table`, strips currency symbols/formatting,
/// parses the cleaned string as a BigDecimal, and converts to f64.
/// Returns a Vec<f64> in row order or an Err(String) describing the first failure.
pub fn extract_penultimate_currency_as_f64(table: &[Vec<String>]) -> Result<Vec<f64>, String> {
    let mut out = Vec::with_capacity(table.len());

    for (i, row) in table.iter().enumerate() {
        if row.len() < 2 {
            return Err(format!("row {} has fewer than 2 columns", i));
        }

        let raw = row[row.len() - 2].trim();
        if raw.is_empty() {
            return Err(format!("row {}: penultimate column is empty", i));
        }

        // Handle parentheses like "(1,234.56)" as a negative sign
        let mut negative = false;
        let mut s = raw.to_string();
        if s.starts_with('(') && s.ends_with(')') {
            negative = true;
            s = s.trim_start_matches('(').trim_end_matches(')').trim().to_string();
        }

        // Keep only characters useful for numeric parsing: digits, sign, decimal point, comma, exponent
        // This removes currency symbols and spaces. We'll remove thousands separators (commas) below.
        let mut cleaned = String::with_capacity(s.len());
        for ch in s.chars() {
            if ch.is_ascii_digit() || ch == '+' || ch == '-' || ch == '.' || ch == ',' || ch == 'e' || ch == 'E' {
                cleaned.push(ch);
            }
            // Note: Unicode digits or localized decimal marks are not handled here.
        }

        // Remove common thousands separator (comma)
        cleaned.retain(|c| c != ',');

        if cleaned.is_empty() {
            return Err(format!("row {}: value '{}' cleaned to empty string", i, raw));
        }

        // If parentheses indicated negativity, ensure '-' prefix
        if negative && !cleaned.starts_with('-') {
            cleaned = format!("-{}", cleaned);
        }

        // Parse with BigDecimal, then convert to f64
        let bd = BigDecimal::from_str(&cleaned)
            .map_err(|e| format!("row {}: BigDecimal parse error for '{}': {}", i, cleaned, e))?;
        let f = bd.to_f64().ok_or_else(|| format!("row {}: BigDecimal -> f64 conversion failed or overflowed for '{}'", i, cleaned))?;
        out.push(f);
    }

    Ok(out)
}

