    }

    let num_cols = table[0].len();
    if num_cols < 2 {
        panic!("Table must have at least 2 columns");
    }

    let penultimate_col_idx = num_cols - 2;

    table
        .into_iter()
        .map(|mut row| {
            let currency_str = &row[penultimate_col_idx];

            // Remove common currency symbols and whitespace
            let cleaned = currency_str
                .chars()
                .filter(|c| {
                    !matches!(c, '$' | '€' | '£' | '¥' | '₹' | '₽' | '¢' | '₩' | '₪' | '₦' | '₨' | '฿' | '₱' | '₡' | '₲' | '₴' | '₵')
