use polars::prelude::*;
use std::sync::Arc;

fn unpivot_dataframe(df0: &DataFrame, lst0: Vec<&str>) -> Result<DataFrame> {
    // Check if all columns in lst0 exist in the DataFrame
    for col in &lst0 {
        if !df0.get_column(col).is_ok() {
            return Err(PolarsError::ShapeError(format!("Column '{}' does not exist", col)));
        }
    }

    // Create a list to store the Series that will form the new "Var0" column (i.e., column names)
    let mut var0 = Vec::new();
    let mut var1 = Vec::new();

    // Iterate through each row of the DataFrame
    for row_idx in 0..df0.height() {
        for col in &lst0 {
            if let Ok(series) = df0.get_column(*col) {
                // Get the value at the current row for the column
                let value = series.get(row_idx);

                // Push the column name and value to var0 and var1 respectively
                var0.push(Arc::new(col.to_string())); // Var0 will hold the column names
                var1.push(value); // Var1 will hold the corresponding values
            }
        }
    }

    // Create new Series for var0 and var1
    let var0_series = Series::new("var0", var0);
    let var1_series = Series::new("var1", var1);

    // Combine var0 and var1 into a new DataFrame
    let result = DataFrame::new(vec![var0_series, var1_series])?;

    Ok(result)
}

