/// Sort `data0` (a 2D dataset represented as a DataFrame) by the columns listed in `col0`.
/// Returns the sorted DataFrame as `var0`.
///
/// - `data0`: input DataFrame (rows x columns)
/// - `col0`: slice of column indices (usize) describing sort priority (first is primary key)
///
/// Requirements on the DataFrame API used here:
/// - `nrows()` -> usize
/// - `row(i)` -> &[T]
/// - `DataFrame::from_rows(Vec<Vec<T>>) -> DataFrame<T>`
/// These are typical helpers; if your otertools version uses different names adapt accordingly.
pub fn sort_dataset<T: Ord + Clone>(data0: &DataFrame<T>, col0: &[usize]) -> DataFrame<T> {
    // Copy rows into a Vec<Vec<T>> so we can sort them
    let mut rows: Vec<Vec<T>> = (0..data0.nrows())
        .map(|i| data0.row(i).to_vec())
        .collect();

    // Sort rows lexicographically by the columns in col0 (in the given priority order)
    rows.sort_by(|a, b| {
        for &col in col0 {
            // If column index might be out of bounds, you could add checking here.
            match a[col].cmp(&b[col]) {
                Ordering::Equal => continue,
                non_eq => return non_eq,
            }
        }
        Ordering::Equal
    });

    // Build the sorted DataFrame and return it as var0
    let var0 = DataFrame::from_rows(rows);
    var0
}
