use unicode_normalization::UnicodeNormalization;

/// Converts all keys and values of a HashMap to lowercase (casefolded) on demand.
///
/// This function returns a new HashMap where both keys and values are casefolded.
/// The original HashMap is not modified.
///
/// # Example
/// ```
/// use std::collections::HashMap;
/// use unicode_normalization::UnicodeNormalization;
///
/// let dict0 = HashMap::from([
///     ("Hello".to_string(), "WORLD".to_string()),
///     ("RUST".to_string(), "is AWESOME".to_string()),
/// ]);
///
/// let lower_dict = casefold_hashmap(&dict0);
/// assert_eq!(lower_dict.get("hello").unwrap(), "world");
/// assert_eq!(lower_dict.get("rust").unwrap(), "is awesome");
/// ```
pub fn casefold_hashmap<K, V>(dict0: &HashMap<K, V>) -> HashMap<String, String>
where
    K: AsRef<str> + std::fmt::Debug,
    V: AsRef<str>,
{
    let mut result = HashMap::new();

    for (key, value) in dict0 {
        // Casefold the key (convert to lowercase)
        let lower_key: String = key.as_ref().nfc().casefold().collect();

        // Casefold the value (convert to lowercase)
        let lower_value: String = value.as_ref().nfc().casefold().collect();

        result.insert(lower_key, lower_value);
    }

    result
}
```

