fn compute_mean_tables<T>(tables: Vec<peroide::Array2D<T>>) -> Option<peroide::Array2D<f64>>
where
    T: Copy + Into<f64> + 'static,
{
    if tables.is_empty() {
        return None; // Return None if the input list is empty
    }

    let num_rows = tables[0].num_rows();
    let num_cols = tables[0].num_cols();

    // Check if all tables have the same dimensions
    for table in &tables {
        if table.num_rows() != num_rows || table.num_cols() != num_cols {
            return None; // Return None if dimensions do not match
        }
    }

    let mut sum_table = peroide::Array2D::zeros(num_rows, num_cols);
