        for r in 0..num_rows {
            for c in 0..num_cols {
                sum_table[(r, c)] += table[(r, c)].into();
            }
        }
    }

    // Compute mean by dividing the sum by the count
    let mean_table = sum_table.map(|value| value / count);

    Some(mean_table)
}

