///
/// The codes are assigned in order of first appearance: 0, 1, 2, ...
pub fn encode_columns<T0, T1>(table: &[(T0, T1)]) -> (Vec<usize>, Vec<usize>)
where
    T0: Eq + Hash + Clone,
    T1: Eq + Hash + Clone,
{
