    let mut map1: BiMap<T1, usize> = BiMap::new();
    let mut next0: usize = 0;
    let mut next1: usize = 0;

    let mut lst0 = Vec::with_capacity(table.len());
    let mut lst1 = Vec::with_capacity(table.len());

    for (v0, v1) in table {
        // get_or_insert-like behavior for column 0
        let code0 = if let Some(&c) = map0.get_by_left(v0) {
            c
        } else {
            let c = next0;
            map0.insert(v0.clone(), c);
            next0 += 1;
            c
        };

        // get_or_insert-like behavior for column 1
        let code1 = if let Some(&c) = map1.get_by_left(v1) {
