pub fn group_and_sum_by_var0(batch: &RecordBatch) -> Result<RecordBatch, arrow::error::ArrowError> {
    // Extract the column for grouping
    let var0_column = batch.column(0); // Assuming var0 is the first column
    let var0_array = var0_column.as_any().downcast_ref::<Int32Array>().unwrap();

    // Prepare a HashMap for aggregation
    let mut aggregation_map: std::collections::HashMap<i32, Vec<i64>> = std::collections::HashMap::new();

    // Iterate through the rows of the input batch
    for i in 0..batch.num_rows() {
        let key = var0_array.value(i);
        if let Some(sums) = aggregation_map.get_mut(&key) {
            for j in 1..batch.num_columns() {
                let value_array = batch.column(j).as_any().downcast_ref::<Int64Array>().unwrap();
                sums[j - 1] += value_array.value(i);
            }
