    let mut output_arrays: Vec<Arc<dyn Array>> = Vec::new();
    let mut group_keys: Vec<String> = groups.keys().cloned().collect();
    group_keys.sort();

    // Add var0 column (group keys)
    let var0_values: Vec<&str> = group_keys.iter().map(|s| s.as_str()).collect();
    output_arrays.push(Arc::new(StringArray::from(var0_values)));

    // Process other numeric columns
    for (col_idx, field) in schema.fields().iter().enumerate() {
        if col_idx == var0_idx {
            continue;
        }

        let column = batch.column(col_idx);

        match field.data_type() {
            DataType::Float64 => {
                if let Some(float_array) = column.as_any().downcast_ref::<Float64Array>() {
                    let mut sums = Vec::new();
                    for key in &group_keys {
                        let indices = &groups[key];
                        let sum: f64 = indices
                            .iter()
                            .filter_map(|&i| float_array.value_as_f64(i))
                            .sum();
                        sums.push(Some(sum));
                    }
                    output_arrays.push(Arc::new(Float64Array::from(sums)));
                } else {
                    return Err(format!("Column {} is not Float64", field.name()));
                }
            }
            DataType::Int64 => {
                if let Some(int_array) = column.as_any().downcast_ref::<Int64Array>() {
                    let mut sums = Vec::new();
                    for key in &group_keys {
                        let indices = &groups[key];
                        let sum: i64 = indices
                            .iter()
                            .filter_map(|&i| {
                                if int_array.is_valid(i) {
                                    Some(int_array.value(i))
                                } else {
                                    None
                                }
                            })
                            .sum();
                        sums.push(Some(sum));
                    }
                    output_arrays.push(Arc::new(Int64Array::from(sums)));
                } else {
                    return Err(format!("Column {} is not Int64", field.name()));
                }
            }
            _ => {
                return Err(format!(
                    "Column {} has unsupported type: {:?}",
                    field.name(),
                    field.data_type()
                ))
            }
        }
    }

    // Create output schema
    let mut output_fields = vec![Field::new("var0", DataType::Utf8, false)];
    for (col_idx, field) in schema.fields().iter().enumerate() {
        if col_idx != var0_idx {
            output_fields.push(field.clone());
        }
    }

    let output_schema = Arc::new(Schema::new(output_fields));

    // Create and return the result RecordBatch
    RecordBatch::try_new(output_schema, output_arrays)
        .map_err(|e| format!("Failed to create output batch: {}", e))
}
