/// 
/// # Returns
/// * A new Dataset with missing categorical values replaced by the mode (most frequent category)
pub fn fill_missing_categorical(df0: &Dataset<f64, f64, DenseMatrix<f64>, Vec<f64>>) -> Dataset<f64, f64, DenseMatrix<f64>, Vec<f64>> {
    let n_samples = df0.get_nsamples();
    let n_features = df0.get_nfeatures();

    // Get the feature matrix
    let features = df0.get_features();

    // Create a new feature matrix to store the imputed values
    let mut imputed_features = DenseMatrix::zeros(n_samples, n_features);

    // Process each column (feature)
    for col in 0..n_features {
        // Collect all non-None values in this column
        let mut value_counts: HashMap<f64, usize> = HashMap::new();
        let mut has_missing = false;

        for row in 0..n_samples {
            let value = features.get(row, col);
            if value.is_nan() {
                has_missing = true;
            } else {
                *value_counts.entry(value).or_insert(0) += 1;
            }
        }

        // Find the most frequent value (mode)
        let mode = if !value_counts.is_empty() {
            *value_counts.iter()
                .max_by(|a, b| a.1.cmp(b.1))
                .map(|(k, _)| k)
                .unwrap_or(&0.0)
        } else {
            0.0 // Default if all values are missing
        };

        // Fill in the column
        for row in 0..n_samples {
            let value = features.get(row, col);
            if value.is_nan() {
                imputed_features.set(row, col, mode);
            } else {
                imputed_features.set(row, col, value);
            }
        }
    }

    // Create and return the new dataset
    Dataset::new(
        imputed_features,
        df0.get_targets().clone(),
        df0.get_feature_names().clone(),
        df0.get_target_name().clone(),
