/// Divide a dataset into subsets based on distinct values in a column.
///
/// # Arguments
///
/// * `df0`: The input dataset.
/// * `var0`: The name of the column to divide by.
///
/// # Returns
///
/// A map where keys are unique values from the specified column and values are the corresponding subsets.
pub fn divide_dataset(df0: RecordBatch, var0: &str) -> std::collections::HashMap<String, RecordBatch> {
    // Get the index of the column to divide by
    let var0_idx = df0.schema().fields().iter().position(|f| f.name() == var0).unwrap();

    // Get the array for the column to divide by
    let var0_array = df0.column(var0_idx).as_any().downcast_ref::<StringArray>().unwrap();

    // Create a map to store the subsets
    let mut subsets: std::collections::HashMap<String, Vec<Array>> = std::collections::HashMap::new();

    // Iterate over the rows in the dataset
    for row in 0..df0.num_rows() {
        // Get the value of the column to divide by for this row
        let var0_value = var0_array.value(row).unwrap();

        // Convert the value to a string
        let var0_value_str = var0_value.to_string();

        // If this value is not already in the subsets map, add it
        if !subsets.contains_key(&var0_value_str) {
            subsets.insert(var0_value_str.clone(), vec![Array::new_empty(DataType::Int32); df0.num_columns()]);
        }

        // Add this row to the corresponding subset
        for col in 0..df0.num_columns() {
            let array = df0.column(col).clone();
