use std::collections::HashMap;
use std::error::Error;
use std::sync::Arc;

use arrow2::{
    array::{Array, ArrayRef, Utf8Array, UInt32Array},
    compute::take::take,
    datatypes::Schema,
    record_batch::RecordBatch,
};

/// Split `df0` into separate RecordBatches for each distinct value in column `var0`.
///
/// - `df0` is a RecordBatch containing a column named `var0` (assumed Utf8Array<i32> here).
/// - Returns a Vec<RecordBatch>, one batch per distinct value (including nulls) preserving the schema.
///
/// Note: Adjust downcast target (Utf8Array<i32> vs Utf8Array<i64>) depending on your arrays.
pub fn split_by_var0(df0: &RecordBatch, var0: &str) -> Result<Vec<RecordBatch>, Box<dyn Error>> {
    // Find the column index for var0
    let col_index = df0
        .schema()
        .fields
        .iter()
        .position(|f| f.name == var0)
        .ok_or_else(|| format!("column '{}' not found in schema", var0))?;

    // Downcast the column to Utf8Array<i32> (adjust to i64 if needed)
    let var0_array = df0
        .column(col_index)
        .as_any()
        .downcast_ref::<Utf8Array<i32>>()
        .ok_or_else(|| format!("column '{}' is not Utf8Array<i32>", var0))?;

    // Build groups: key = Option<String> (None == null), value = vector of row indices (u32)
    let mut groups: HashMap<Option<String>, Vec<u32>> = HashMap::new();
    for row in 0..var0_array.len() {
        let key = if var0_array.is_null(row) {
            None
        } else {
            // `value` returns &str for non-null entries
            Some(var0_array.value(row).to_string())
        };
        groups.entry(key).or_default().push(row as u32);
    }

    let mut out_batches: Vec<RecordBatch> = Vec::with_capacity(groups.len());
    let schema: Arc<Schema> = df0.schema().clone();

    // For each group, create a RecordBatch with rows selected by the group's indices
    for (_group_key, indices_vec) in groups.into_iter() {
        // Create a UInt32Array of indices for take()
        let indices = UInt32Array::from_slice(indices_vec);

        // For each column in the original batch, take the rows at indices
        let mut new_columns: Vec<ArrayRef> = Vec::with_capacity(df0.columns().len());
        for col in df0.columns() {
            // `take` returns a Box<dyn Array>
            let taken: Box<dyn Array> = take(col.as_ref(), &indices, None)?;
            new_columns.push(Arc::from(taken));
        }

        // Build a new RecordBatch with the same schema
        let new_batch = RecordBatch::try_new(schema.clone(), new_columns)?;
        out_batches.push(new_batch);
    }

    Ok(out_batches)
}
```

