use nom::{
    branch::alt,
    bytes::complete::{tag, take_while1},
    character::complete::char,
    combinator::{map, opt},
    multi::many0,
    sequence::tuple,
    IResult,
};

/// Divides input text at each comma, trims whitespace from segments, and returns the collection.
fn split_and_trim_by_comma(input: &str) -> Vec<String> {
    fn is_whitespace(c: char) -> bool {
        c.is_whitespace()
    }

    fn parse_whitespace(input: &str) -> IResult<&str, &str> {
        take_while1(is_whitespace)(input)
    }

    fn parse_segment(input: &str) -> IResult<&str, String> {
        let (input, _) = opt(parse_whitespace)(input)?;
        let (input, content) = take_while1(|c| c != ',')(input)?;
        let (input, _) = opt(parse_whitespace)(input)?;
        Ok((input, content.to_string()))
    }

    fn parse_segments(input: &str) -> IResult<&str, Vec<String>> {
        let (input, first) = parse_segment(input)?;
        let (input, rest) = many0(tuple((char(','), parse_segment)))(input)?;

        let mut segments = vec![first];
        for (_, segment) in rest {
            segments.push(segment);
        }

        Ok((input, segments))
    }

    match parse_segments(input) {
        Ok((_, segments)) => segments,
        Err(_) => vec![],
    }
}

