# Rust Function for Group Count Using DataFusion

```rust
use datafusion::prelude::*;
use std::sync::Arc;

/// Counts the number of rows for each distinct combination of values
/// in the specified key columns.
///
/// # Arguments
/// * `df` - A DataFrame containing the data
/// * `key_columns` - Vector of column names to group by
///
/// # Returns
/// A DataFrame with the key columns and a count column named "count"
///
/// # Example
/// ```
/// let key_cols = vec!["category".to_string(), "region".to_string()];
/// let result = group_count(df, key_cols).await.unwrap();
/// ```
pub async fn group_count(
    df: DataFrame,
    key_columns: Vec<String>,
) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Validate that key_columns is not empty
    if key_columns.is_empty() {
        return Err("key_columns cannot be empty".into());
    }

    // Group by the specified columns and count rows
    let result = df
        .clone()
        .aggregate(
            key_columns.iter().map(|col| col(col)).collect(),
            vec![count(lit(1)).alias("count")],
        )?
        .sort(
            key_columns
                .iter()
                .map(|col| datafusion::logical_expr::Expr::Column(datafusion::common::Column::from_name(col.clone())))
                .collect(),
        )?;

    Ok(result)
}

/// Alternative version that returns the result as a Vec of records for easier inspection
pub async fn group_count_collect(
    df: DataFrame,
    key_columns: Vec<String>,
) -> Result<Vec<(Vec<String>, i64)>, Box<dyn std::error::Error>> {
    let result_df = group_count(df, key_columns.clone()).await?;
    let batches = result_df.collect().await?;

    let mut results = Vec::new();

    for batch in batches {
        let num_rows = batch.num_rows();
        let mut key_arrays = Vec::new();

        // Collect all key column arrays
        for key_col in &key_columns {
            let col_index = batch
                .schema()
                .column_with_name(key_col)
                .ok_or(format!("Column {} not found", key_col))?
                .0;
            key_arrays.push(batch.column(col_index).clone());
        }

        // Collect the count column
        let count_col_index = batch
            .schema()
            .column_with_name("count")
            .ok_or("Count column not found")?
            .0;
        let count_array = batch.column(count_col_index);

        // Process each row
        for row_idx in 0..num_rows {
            let mut key_values = Vec::new();

            for key_array in &key_arrays {
                let value = format!("{:?}", key_array.slice(row_idx, 1));
                key_values.push(value);
            }

            let count = count_array
                .as_any()
                .downcast_ref::<arrow::array::Int64Array>()
                .ok_or("Count is not Int64")?
                .value(row_idx);

            results.push((key_values, count));
        }
    }

    Ok(results)
}

