use linked_hash_map::LinkedHashMap;

/// Sorts the keys of a mapping according to their associated values and returns a list of triples.
///
/// Args:
///     mapping (LinkedHashMap): The input mapping.
///
/// Returns:
///     Vec<(String, i32, usize)>: A list of triples containing each key, its value, and the index.
fn sort_keys_by_values(mapping: LinkedHashMap<String, i32>) -> Vec<(String, i32, usize)> {
    let mut result = Vec::new();
    let mut index = 0;

    // Iterate over the original mapping to store the index of each value
    let mut value_index_map: LinkedHashMap<i32, usize> = LinkedHashMap::new();
    for (_, value) in &mapping {
        if !value_index_map.contains_key(&value) {
            value_index_map.insert(*value, index);
            index += 1;
        }
    }

    // Sort the keys by their values
    let mut sorted_keys: Vec<_> = mapping.keys().cloned().collect();
    sorted_keys.sort_by_key(|key| mapping.get(key).unwrap());

    // Create the list of triples
    for key in sorted_keys {
        let value = *mapping.get(&key).unwrap();
        let index = value_index_map.get(&value).unwrap();
        result.push((key, value, *index));
    }

    result
}

fn main() {
    let mut mapping = LinkedHashMap::new();
    mapping.insert("a".to_string(), 5);
    mapping.insert("b".to_string(), 2);
    mapping.insert("c".to_string(), 8);
    mapping.insert("d".to_string(), 2);

    let result = sort_keys_by_values(mapping);
