```rust
use ndarray::{Array2, Axis};

/// Normalizes each column of a 2D array to [0, 1] using min-max scaling.
fn normalize_columns_minmax(mut df0: Array2<f64>) -> Array2<f64> {
    for col_idx in 0..df0.ncols() {
        let mut col = df0.column_mut(col_idx);

        let min = col.iter().cloned().fold(f64::INFINITY, f64::min);
        let max = col.iter().cloned().fold(f64::NEG_INFINITY, f64::max);

        let range = max - min;

        if range > 0.0 {
            col.mapv_inplace(|x| (x - min) / range);
        } else {
            col.mapv_inplace(|_| 0.0);
        }
    }

    df0
}
```

