/// Extracts all key-value pairs from a HashMap whose keys contain a specified sequence of characters.
///
/// # Arguments
/// * `map` - The source HashMap containing key-value pairs
/// * `sequence` - The character sequence that keys must contain
///
/// # Returns
/// A new HashMap containing only the pairs whose keys contain the specified sequence
///
/// # Example
/// ```
/// use std::collections::HashMap;
///
/// let mut map = HashMap::new();
/// map.insert("user_name", "John");
/// map.insert("user_email", "john@example.com");
/// map.insert("admin_id", "42");
/// map.insert("admin_role", "super");
///
/// let result = extract_pairs_with_sequence(&map, "user");
/// assert_eq!(result.len(), 2);
/// assert_eq!(result.get("user_name"), Some(&"John"));
/// ```
fn extract_pairs_with_sequence(
    map: &HashMap<&str, &str>,
    sequence: &str,
) -> HashMap<&str, &str> {
    // Escape special regex characters in the sequence
    let escaped_sequence = regex::escape(sequence);

    // Create a regex pattern that matches keys containing the sequence
    let pattern = match Regex::new(&escaped_sequence) {
        Ok(re) => re,
        Err(_) => return HashMap::new(), // Return empty map if regex is invalid
    };

    // Filter and collect matching key-value pairs
    map.iter()
        .filter(|(key, _)| pattern.is_match(key))
        .map(|(k, v)| (*k, *v))
        .collect()
}

