fn remove_consecutive_duplicates(df: DataFrame) -> PolarsResult<DataFrame> {
    if df.height() == 0 {
        return Ok(df);
    }

    // Create a boolean mask where True indicates we should keep the row
    let mut keep_mask = vec![true; df.height()];

    // Compare each row with the previous one
    for i in 1..df.height() {
        let curr_row = df.slice(i as i64, 1);
        let prev_row = df.slice((i - 1) as i64, 1);

        // Check if current row equals previous row
        if rows_equal(&curr_row, &prev_row) {
            keep_mask[i] = false;
        }
    }

    // Filter the dataframe using the mask
    let mask_series = Series::new("__mask", keep_mask);
    df.filter(&mask_series.bool()?)
}

/// Helper function to check if two single-row DataFrames are identical
fn rows_equal(row1: &DataFrame, row2: &DataFrame) -> bool {
    if row1.width() != row2.width() {
        return false;
