    for col_idx in 0..row1.width() {
        let col1 = &row1.get_columns()[col_idx];
        let col2 = &row2.get_columns()[col_idx];

        // Compare the first element of each column
        if !columns_equal_at_index(col1, col2, 0, 0) {
            return false;
        }
    }

    true
}

