use polars::prelude::*;
use std::collections::BTreeSet;

fn sanitize_column_name(s: &str) -> String {
    // Make a simple safe column name: keep alphanumeric, replace others with '_'
    s.chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '_' })
        .collect()
}

/// Expand distinct values of `col_name` in `df` into binary indicator columns.
/// Returns a new DataFrame that contains the original columns plus one indicator
/// column per distinct value of `col_name`. Nulls are treated as a distinct value
/// and column name for nulls will contain "__NULL__".
pub fn expand_var0_to_indicators(df: &DataFrame, col_name: &str) -> PolarsResult<DataFrame> {
    // Clone the original frame to append columns to it; keep original untouched.
    let mut out = df.clone();

    // Get the series and cast to Utf8 (string) for uniform processing.
    let col_series = out.column(col_name)?.clone();
    let col_utf8_series = col_series.cast(&DataType::Utf8)?;
    let col_utf8 = col_utf8_series.utf8()?;

    // Collect values once so we can iterate multiple times.
    let vals: Vec<Option<&str>> = col_utf8.into_iter().collect();

    // Determine unique non-null values, and track whether there are nulls.
    let has_null = vals.iter().any(|o| o.is_none());
    let mut unique: BTreeSet<&str> = BTreeSet::new();
    for &v in vals.iter().filter_map(|&o| o) {
        unique.insert(v);
    }
    if has_null {
        unique.insert("__NULL__"); // placeholder name for null value
    }

    // For each distinct value, build a UInt8Chunked of 0/1 and add as a column.
    for val in unique {
        let col_label = format!("{}_{}", col_name, sanitize_column_name(val));
        // Build iterator of Option<u8> (no missing values in indicators).
        let iter = vals.iter().map(move |&o| {
            let is_one = match o {
                Some(s) => s == val,
                None => val == "__NULL__",
            };
            Some(if is_one { 1u8 } else { 0u8 })
        });
        let chunked = UInt8Chunked::new_from_opt_iter(&col_label, iter);
        out.with_column(chunked.into_series())?;
    }

    Ok(out)
}

