fn one_hot_encode(df0: &Tensor, var0: &str) -> Result<Tensor, Box<dyn std::error::Error>> {
    // Get the column index for var0
    let col_idx = df0.column_names()
        .iter()
        .position(|name| name == var0)
        .ok_or_else(|| format!("Column '{}' not found", var0))?;

    // Extract the values from the specified column
    let column_values = df0.column(col_idx)?;

    // Get unique values from the column
    let mut unique_values: Vec<String> = Vec::new();
    let mut value_to_idx: HashMap<String, usize> = HashMap::new();

    for i in 0..column_values.len() {
        let val = column_values.get(i)?.to_string();
        if !value_to_idx.contains_key(&val) {
            value_to_idx.insert(val.clone(), unique_values.len());
            unique_values.push(val);
        }
    }

    let num_rows = df0.shape()[0];
    let num_unique = unique_values.len();

    // Create the one-hot encoded matrix
    let mut one_hot_data = vec![0.0f32; num_rows * num_unique];

    for i in 0..num_rows {
        let val = column_values.get(i)?.to_string();
        if let Some(&idx) = value_to_idx.get(&val) {
            one_hot_data[i * num_unique + idx] = 1.0;
        }
    }

    // Create column names for the new binary columns
    let mut new_column_names: Vec<String> = Vec::new();
    for val in &unique_values {
        new_column_names.push(format!("{}_{}", var0, val));
    }

    // Create the new tensor with one-hot encoded data
    let one_hot_tensor = Tensor::new(
        &[num_rows, num_unique],
        &one_hot_data,
        &new_column_names,
    )?;

    // Remove the original var0 column and add the new one-hot columns
    let mut result_columns: Vec<String> = Vec::new();
    let mut result_data: Vec<Vec<f32>> = Vec::new();

    // Get all original column names except var0
    for (i, col_name) in df0.column_names().iter().enumerate() {
        if col_name != var0 {
            result_columns.push(col_name.clone());
            let col_data = df0.column(i)?;
            let mut col_vec: Vec<f32> = Vec::new();
            for j in 0..col_data.len() {
                col_vec.push(col_data.get(j)?.parse::<f32>().unwrap_or(0.0));
            }
            result_data.push(col_vec);
        }
    }

    // Add the one-hot encoded columns
    for (i, col_name) in new_column_names.iter().enumerate() {
        result_columns.push(col_name.clone());
        let mut col_vec: Vec<f32> = Vec::new();
        for j in 0..num_rows {
            col_vec.push(one_hot_data[j * num_unique + i]);
        }
        result_data.push(col_vec);
    }

    // Transpose the data to match Tensor format (columns as rows in the data vector)
    let mut final_data: Vec<f32> = Vec::new();
    for j in 0..num_rows {
        for i in 0..result_columns.len() {
            final_data.push(result_data[i][j]);
        }
    }

    let result = Tensor::new(
        &[num_rows, result_columns.len()],
        &final_data,
        &result_columns,
    )?;

    Ok(result)
}

