use std::collections::{HashMap, BTreeSet};

/// One-hot encodes a column from a table
/// 
/// Takes a table with a column `var0` and creates binary indicator columns
/// for each distinct value in that column.
/// 
/// # Arguments
/// * `df0` - Input data as Vec<HashMap<String, String>> where each HashMap represents a row
/// 
/// # Returns
/// Vec<HashMap<String, i32>> where each row has the original columns plus binary indicators
fn one_hot_encode_column(df0: Vec<HashMap<String, String>>) -> Vec<HashMap<String, i32>> {
    // Find all distinct values in var0
    let mut distinct_values: BTreeSet<String> = BTreeSet::new();

    for row in &df0 {
        if let Some(value) = row.get("var0") {
            distinct_values.insert(value.clone());
        }
    }

    // Create the output table
    let mut result: Vec<HashMap<String, i32>> = Vec::new();

    for row in df0 {
        let mut new_row: HashMap<String, i32> = HashMap::new();

        // Get the value of var0 for this row
        let var0_value = row.get("var0").cloned().unwrap_or_default();

        // Create binary indicator columns for each distinct value
        for distinct_val in &distinct_values {
            let column_name = format!("var0_{}", distinct_val);
            let indicator = if var0_value == *distinct_val { 1 } else { 0 };
            new_row.insert(column_name, indicator);
        }

        result.push(new_row);
    }

    result
}

