use std::collections::HashMap;
use dxhash::dxhash;

fn sort_by_order_a(a: &mut [String], b: &[String]) -> usize {
    // First, create a hash map of elements in B with their indices
    let mut b_indices = HashMap::with_capacity(b.len());
    for (i, &item) in b.iter().enumerate() {
        b_indices.insert(dxhash(item.as_bytes()), i);
    }

    // Count how many elements in A are not in B
    let mut not_in_b = 0;
    for item in a.iter() {
        if !b_indices.contains_key(&dxhash(item.as_bytes())) {
            not_in_b += 1;
        }
    }

    // Partition A into elements in B and not in B
    let mut partition_point = 0;
    for i in 0..a.len() {
        if b_indices.contains_key(&dxhash(&a[i])) {
            // Swap with the first element that's not in B
            if partition_point < i {
                a.swap(i, partition_point);
            }
            partition_point += 1;
        }
    }

    // Sort the elements that are in B according to B's order
    let b_elements: Vec<_> = b.iter().map(|s| dxhash(s.as_bytes())).collect();
    a[partition_point..].sort_by(|a, b| {
        let a_hash = dxhash(a.as_bytes());
        let b_hash = dxhash(b.as_bytes());

        // Find the positions in B for each element
        let a_pos = match b_indices.get(&a_hash) {
            Some(&pos) => pos,
            None => return std::cmp::Ordering::Greater, // shouldn't happen due to partition
        };
        let b_pos = match b_indices.get(&b_hash) {
            Some(&pos) => pos,
            None => return std::cmp::Ordering::Less,  // shouldn't happen due to partition
        };

        a_pos.cmp(&b_pos)
    });

    not_in_b
}

