    for (index, &item) in b.iter().enumerate() {
        order_map.insert(item, index);
    }

    // Sort A using the order map
    // Items not in B get usize::MAX as their order value, placing them first
    // Items in B are sorted by their position in B
    // Within ties, maintain stable sort
    let mut result = a.to_vec();
    result.sort_by(|x, y| {
        let x_order = order_map.get(x).copied().unwrap_or(usize::MAX);
        let y_order = order_map.get(y).copied().unwrap_or(usize::MAX);

        match x_order.cmp(&y_order) {
            Ordering::Equal => {
                // If both have same order (including both being usize::MAX),
                // maintain relative order or sort by value for stability
                x.cmp(y)
            }
            other => other,
        }
    });

    result
}

