///
/// - `reader`: any reader that yields the DSV input (e.g. a File or &str.as_bytes())
/// - `sum_column`: name of the column to sum (parsed as f64)
/// - `filter_column`: name of the column to test with the predicate
/// - `predicate`: a closure that receives the filter column string and returns true for rows to include
///
/// Returns the sum as f64, or an error if the reader/columns are not valid.
pub fn sum_column_if<R, F>(
    reader: R,
    sum_column: &str,
    filter_column: &str,
    predicate: F,
) -> Result<f64, Box<dyn Error>>
where
    R: Read,
    F: Fn(&str) -> bool,
{
    let mut rdr = ReaderBuilder::new()
        .has_headers(true)
        .from_reader(reader);

    // Read headers to find column indices
    let headers = rdr.headers()?.clone();
    let sum_idx = headers
        .iter()
        .position(|h| h == sum_column)
        .ok_or_else(|| format!("sum column '{}' not found", sum_column))?;
    let filter_idx = headers
        .iter()
        .position(|h| h == filter_column)
        .ok_or_else(|| format!("filter column '{}' not found", filter_column))?;

    let mut total = 0f64;
    for result in rdr.records() {
        let record = result?;
