use indexmap::IndexMap;
use std::collections::BTreeMap;

/// Sorts the keys of a mapping by their associated values and returns both the sorted keys and a list containing each value's original index position.
///
/// # Arguments
///
/// * `dict0` - The input mapping.
///
/// # Returns
///
/// A tuple containing a vector of sorted keys and a vector of original index positions.
fn sort_keys_by_values(dict0: IndexMap<String, i32>) -> (Vec<String>, Vec<usize>) {
    // Create a BTreeMap to sort the keys by their associated values
    let mut sorted_map: BTreeMap<i32, Vec<(String, usize)>> = BTreeMap::new();
    dict0.into_iter().enumerate().for_each(|(index, (key, value))| {
        sorted_map.entry(value).or_insert(Vec::new()).push((key, index));
