    // Extract sorted keys and original index positions
    let mut sorted_keys = Vec::new();
    let mut original_indices = Vec::new();
    for (_, vec) in sorted_map.into_iter() {
        for (key, index) in vec {
            sorted_keys.push(key);
            original_indices.push(index);
        }
    }

    (sorted_keys, original_indices)
}

