use std::simd::{Simd, SimdPartialEq, ToBitMask, LaneCount, SupportedLaneCount};

/// Creates three new sequences from an input sequence by:
/// - Subtracting 1, 0, and -1 from elements at odd positions
/// - Replacing elements at even positions with zero
/// 
/// Returns a Vec of three sequences: [subtract_1, subtract_0, subtract_minus_1]
pub fn create_sequences<T, const N: usize>(input: &[T]) -> Vec<Vec<T>>
where
    T: std::ops::Sub<Output = T> + Copy + Default + std::cmp::PartialEq,
    Simd<T, N>: SimdPartialEq<Mask = Simd<<T as std::simd::SimdElement>::Mask, N>>,
    LaneCount<N>: SupportedLaneCount,
    [T; N]: std::convert::From<Simd<T, N>>,
{
    if input.is_empty() {
        return vec![vec![], vec![], vec![]];
    }

    let len = input.len();
    let mut result1 = vec![T::default(); len];
    let mut result2 = vec![T::default(); len];
    let mut result3 = vec![T::default(); len];

    // Process in chunks of N elements using SIMD
    let chunks = len / N;
    let remainder = len % N;

    // Create masks for odd positions (1, 3, 5, ...)
    let odd_mask = create_odd_mask::<T, N>();

    for chunk_idx in 0..chunks {
        let start = chunk_idx * N;
        let chunk = Simd::<T, N>::from_slice(&input[start..start + N]);

        // For odd positions: subtract 1, 0, and -1
        // For even positions: set to zero
        let ones = Simd::<T, N>::splat(T::one());
        let zeros = Simd::<T, N>::splat(T::zero());
        let neg_ones = Simd::<T, N>::splat(T::neg_one());

        // Apply operations only at odd positions, zero at even positions
        let result1_chunk = chunk - ones;
        let result2_chunk = chunk - zeros;
        let result3_chunk = chunk - neg_ones;

        // Zero out even positions
        let result1_chunk = result1_chunk.select(odd_mask, zeros);
        let result2_chunk = result2_chunk.select(odd_mask, zeros);
        let result3_chunk = result3_chunk.select(odd_mask, zeros);

        // Store results
        result1[start..start + N].copy_from_slice(&result1_chunk.to_array());
        result2[start..start + N].copy_from_slice(&result2_chunk.to_array());
        result3[start..start + N].copy_from_slice(&result3_chunk.to_array());
    }

    // Handle remaining elements
    if remainder > 0 {
        let start = chunks * N;
        for i in start..len {
            if i % 2 == 1 {  // odd position
                result1[i] = input[i] - T::one();
                result2[i] = input[i] - T::zero();
                result3[i] = input[i] - T::neg_one();
            }
            // even positions remain zero (already initialized)
        }
    }

    vec![result1, result2, result3]
}

/// Helper trait to provide one() and neg_one() for numeric types
trait NumericConstants {
    fn one() -> Self;
    fn zero() -> Self;
    fn neg_one() -> Self;
}

impl NumericConstants for i32 {
    fn one() -> Self { 1 }
    fn zero() -> Self { 0 }
    fn neg_one() -> Self { -1 }
}

impl NumericConstants for f32 {
    fn one() -> Self { 1.0 }
    fn zero() -> Self { 0.0 }
    fn neg_one() -> Self { -1.0 }
}

impl NumericConstants for f64 {
    fn one() -> Self { 1.0 }
    fn zero() -> Self { 0.0 }
    fn neg_one() -> Self { -1.0 }
}

/// Creates a SIMD mask where odd positions are true and even positions are false
fn create_odd_mask<T, const N: usize>() -> Simd<T, N>::Mask
where
    T: std::simd::SimdElement,
    Simd<T, N>: SimdPartialEq<Mask = Simd<T::Mask, N>>,
    LaneCount<N>: SupportedLaneCount,
{
    let mut mask_bits = [false; N];
    for i in 0..N {
        mask_bits[i] = i % 2 == 1;  // odd positions
    }
    Simd::<T, N>::Mask::from_array(mask_bits)
}

