use serde_json::{Value, Map};
use std::cmp::Ordering;

fn sort_maps_by_lst_order(
    lst0: Vec<Map<String, Value>>,
    lst1: Vec<Value>,
    var0: usize,
) -> Vec<Map<String, Value>> {
    // Create a mapping from value to its position in lst1
    let mut value_to_position = Vec::with_capacity(lst1.len());
    for (i, value) in lst1.iter().enumerate() {
        value_to_position.push((value.clone(), i));
    }

    // Sort lst0 based on the position in lst1
    let mut sorted = lst0;
    sorted.sort_by(|a, b| {
        // Get the value from a at var0 position
        let key = format!("key_{}", var0);
        let a_value = a.get(&key)
            .and_then(|v| v.as_str())
            .or_else(|| v.as_f64().map(|f| f.to_string()))
            .or_else(|| v.as_i64().map(|i| i.to_string()))
            .unwrap_or_default();

        // Get the value from b at var0 position
        let b_value = b.get(&key)
            .and_then(|v| v.as_str())
            .or_else(|| v.as_f64().map(|f| f.to_string()))
            .or_else(|| v.as_i64().map(|i| i.to_string()))
            .unwrap_or_default();

        // Find the positions in lst1 for these values
        let a_pos = value_to_position
            .iter()
            .position(|(v, _)| v == &Value::String(a_value.clone()))
            .or_else(|| value_to_position
                .iter()
                .position(|(v, _)| v == &Value::Number(serde_json::Number::from_f64(
                    a_value.parse::<f64>().unwrap_or(0.0)
                ))))
            .unwrap_or(usize::MAX);

        let b_pos = value_to_position
            .iter()
            .position(|(v, _)| v == &Value::String(b_value.clone()))
            .or_else(|| value_to_position
                .iter()
                .position(|(v, _)| v == &Value::Number(serde_json::Number::from_f64(
                    b_value.parse::<f64>().unwrap_or(0.0)
                ))))
            .unwrap_or(usize::MAX);

        a_pos.cmp(&b_pos)
    });

    sorted
}

// Example usage:
