use serde_value::Value;
use std::collections::BTreeMap;

/// Sorts a list of associative maps according to the order defined by values in a second list.
///
/// # Arguments
/// * `lst0` - A list of associative maps (Value::Map) to be sorted
/// * `lst1` - A list defining the sort order
/// * `var0` - The key to look up in each map of lst0 to determine its sort position
///
/// # Returns
/// A sorted Vec<Value> where the maps from lst0 are reordered according to lst1
pub fn sort_by_order_list(
    lst0: Vec<Value>,
    lst1: Vec<Value>,
    var0: &Value,
) -> Vec<Value> {
    // Create a lookup map from lst1 values to their indices
    let order_map: BTreeMap<Value, usize> = lst1
        .into_iter()
        .enumerate()
        .map(|(index, value)| (value, index))
        .collect();

    // Sort lst0 using an inline closure to determine the sort key
    let mut sorted = lst0;
    sorted.sort_by(|a, b| {
        // Extract the value at var0 from each map
        let key_a = get_map_value(a, var0);
        let key_b = get_map_value(b, var0);

        // Get the order index for each key, defaulting to usize::MAX if not found
        let order_a = order_map.get(&key_a).copied().unwrap_or(usize::MAX);
        let order_b = order_map.get(&key_b).copied().unwrap_or(usize::MAX);

        // Compare based on order
        order_a.cmp(&order_b)
    });

    sorted
}

/// Helper function to extract a value from a serde_value::Value map
fn get_map_value<'a>(map: &'a Value, key: &Value) -> Value {
    match map {
        Value::Map(entries) => {
            entries
                .iter()
                .find(|(k, _)| k == key)
                .map(|(_, v)| v.clone())
                .unwrap_or(Value::Unit) // Return Unit if key not found
        }
        _ => Value::Unit, // Return Unit if not a map
    }
}

