use serde_json::{json, Value};

/// Sort a list of associative maps according to the order defined by a second list.
///
/// # Arguments
/// * `lst0` - List of associative maps (objects) to be sorted
/// * `lst1` - List defining the sort order
/// * `var0` - The key/field name to extract from each map in lst0
///
/// # Returns
/// A new vector of Values sorted according to the order in lst1
fn sort_by_reference_list(lst0: &[Value], lst1: &[Value], var0: &str) -> Vec<Value> {
    let mut sorted = lst0.to_vec();

    sorted.sort_by(|a, b| {
        // Extract the value at var0 from each map
        let key_a = a.get(var0).and_then(|v| extract_comparable_value(v));
        let key_b = b.get(var0).and_then(|v| extract_comparable_value(v));

        // Find positions in lst1
        let pos_a = key_a.as_ref().and_then(|k| find_position_in_list(lst1, k));
        let pos_b = key_b.as_ref().and_then(|k| find_position_in_list(lst1, k));

        match (pos_a, pos_b) {
            (Some(p_a), Some(p_b)) => p_a.cmp(&p_b),
            (Some(_), None) => std::cmp::Ordering::Less,
            (None, Some(_)) => std::cmp::Ordering::Greater,
            (None, None) => std::cmp::Ordering::Equal,
        }
    });

    sorted
}

/// Helper function to extract a comparable value from a JSON Value
fn extract_comparable_value(v: &Value) -> Option<Value> {
    match v {
        Value::Null => None,
        _ => Some(v.clone()),
    }
}

/// Helper function to find the position of a value in a list
fn find_position_in_list(lst: &[Value], target: &Value) -> Option<usize> {
    lst.iter().position(|v| values_equal(v, target))
}

/// Helper function to compare two JSON Values for equality
fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Number(x), Value::Number(y)) => x == y,
        (Value::String(x), Value::String(y)) => x == y,
        (Value::Array(x), Value::Array(y)) => x == y,
        (Value::Object(x), Value::Object(y)) => x == y,
        _ => false,
    }
}

