// Self-contained implementation with an "algoritms" module.
// Call `sort_list(&lst0)` to get a new sorted Vec<i32>.

pub mod algoritms {
    // Public merge sort: returns a new Vec<i32> sorted ascending.
    pub fn merge_sort(v: &[i32]) -> Vec<i32> {
        let n = v.len();
        if n <= 1 {
            return v.to_vec();
        }
        let mid = n / 2;
        let left = merge_sort(&v[..mid]);
        let right = merge_sort(&v[mid..]);
        merge(&left, &right)
    }

    // Merge two sorted slices into one sorted Vec.
    fn merge(left: &[i32], right: &[i32]) -> Vec<i32> {
        let mut res = Vec::with_capacity(left.len() + right.len());
        let mut i = 0;
        let mut j = 0;
        while i < left.len() && j < right.len() {
            if left[i] <= right[j] {
                res.push(left[i]);
                i += 1;
            } else {
                res.push(right[j]);
                j += 1;
            }
        }
        if i < left.len() {
            res.extend_from_slice(&left[i..]);
        }
        if j < right.len() {
            res.extend_from_slice(&right[j..]);
        }
        res
    }
}

