use std::sync::Arc;
use datafusion::prelude::*;
use datafusion::error::Result;
use datafusion::dataframe::DataFrame;

/// Return true if there exists any row in `df0` where `var0` is between `var1` and `var2` (inclusive).
///
/// `df0` is expected to have columns named "var0", "var1", and "var2".
pub async fn any_var0_in_range(df0: Arc<dyn DataFrame>) -> Result<bool> {
    // Build expression: var0 >= var1 AND var0 <= var2
    let expr = col("var0").gt_eq(col("var1")).and(col("var0").lt_eq(col("var2")));

    // Filter the dataframe by the expression
    let filtered = df0.filter(expr)?;

    // Collect the execution results. If any RecordBatch has rows, a matching row exists.
    let batches = filtered.collect().await?;
    for batch in batches {
        if batch.num_rows() > 0 {
            return Ok(true);
        }
    }
    Ok(false)
}

