    let mut stack = Vec::new();
    let mut result = Vec::new();
    let mut first_element_extracted = false;

    while let Some(event) = parser.next() {
        match event {
            Ok(JsonEvent::ObjectStart) | Ok(JsonEvent::ArrayStart) => {
                stack.push(event.unwrap());
                first_element_extracted = false;
            }
