///
/// # Arguments
/// * `value` - The current JSON value being traversed
/// * `results` - Mutable reference to the results vector
fn extract_first_elements_recursive(value: &js0n::Value, results: &mut Vec<String>) {
    match value {
        // If it's an array, check if it contains only primitive values (innermost subcollection)
        js0n::Value::Array(arr) => {
            // Check if this is an innermost array (contains only non-array values)
            let is_innermost = arr.iter().all(|item| !matches!(item, js0n::Value::Array(_)));

