/// Formats a JSON value as a string for inclusion in results.
///
/// # Arguments
/// * `value` - The JSON value to format
///
/// # Returns
/// * `String` - The string representation of the value
fn format_value(value: &js0n::Value) -> String {
    match value {
        js0n::Value::String(s) => s.clone(),
        js0n::Value::Number(n) => n.to_string(),
        js0n::Value::Bool(b) => b.to_string(),
        js0n::Value::Null => "null".to_string(),
