fn extract_recursive(value: &JsonValue, results: &mut Vec<JsonValue>) {
    match value {
        JsonValue::Array(arr) => {
            // Check if this is an innermost collection (contains no arrays/objects)
            let is_innermost = arr.iter().all(|item| {
                !matches!(item, JsonValue::Array(_) | JsonValue::Object(_))
            });

            if is_innermost && !arr.is_empty() {
                // This is an innermost subcollection, extract the first element
                results.push(arr[0].clone());
            } else {
                // Recurse into nested collections
                for item in arr {
                    extract_recursive(item, results);
                }
            }
        }
        JsonValue::Object(obj) => {
            // Recurse into object values
            for (_, val) in obj {
                extract_recursive(val, results);
            }
        }
        _ => {}
    }
}

