use arrow2::compute::sort::sort_to_indices;
use arrow2::datatypes::{DataType, Field, Schema};
use arrow2::record_batch::RecordBatch;
use std::sync::Arc;

fn sort_record_batch_by_columns(df0: RecordBatch, column_names: &[&str]) -> Result<RecordBatch, String> {
    // Find the indices of the columns to sort by
    let column_indices: Vec<usize> = column_names
        .iter()
        .map(|name| df0.schema().index_of(name).ok_or_else(|| format!("Column {} not found", name)))
        .collect::<Result<Vec<_>, _>>()?;

    // Collect the arrays to sort by
    let arrays: Vec<Arc<dyn Array>> = column_indices
        .iter()
        .map(|&index| df0.column(index).clone())
        .collect();

    // Sort the indices based on the arrays
    let sort_options = vec![true; column_indices.len()]; // Ascending order for all columns
    let sort_indices = sort_to_indices(&arrays, &sort_options)
        .map_err(|e| format!("Error sorting record batch: {}", e))?;

    // Reorder all columns in the RecordBatch based on the sort indices
    let sorted_columns: Vec<Arc<dyn Array>> = df0
        .columns()
        .iter()
        .map(|array| {
            array.take(&sort_indices)
                .map_err(|e| format!("Error reordering array: {}", e))
        })
        .collect::<Result<Vec<_>, _>>()?;

    // Create a new RecordBatch with the sorted columns
    RecordBatch::try_new(df0.schema().clone(), sorted_columns)
        .map_err(|e| format!("Error creating sorted RecordBatch: {}", e))
}

