    let var2 = Arc::new(PrimitiveArray::<f64>::from_slice(&[3.0, 1.0, 2.0])) as Arc<dyn Array>;

    let df0 = RecordBatch::try_new(schema.clone(), vec![var0, var1, var2]).unwrap();

    match sort_record_batch_by_columns(df0, &["var0", "var1"]) {
        Ok(sorted_df) => {
