use std::sync::Arc;

use arrow2::array::ArrayRef;
use arrow2::compute::sort::{lexsort_to_indices, SortOptions};
use arrow2::compute::take::take;
use arrow2::record_batch::RecordBatch;

/// Return a version of `df0` sorted by its columns `var0` and `var1` (lexicographic).
///
/// All sorting is ascending and places nulls last by default. Adjust SortOptions if you need
/// descending or different null ordering.
///
/// Errors if either column name is not found or if any compute step fails.
pub fn sort_df_by_two_columns(
    df0: &RecordBatch,
    var0: &str,
    var1: &str,
) -> Result<RecordBatch, Box<dyn Error>> {
    // look up the two key columns
    let col0 = df0
        .column_by_name(var0)
        .ok_or_else(|| format!("column '{}' not found in input RecordBatch", var0))?;
    let col1 = df0
        .column_by_name(var1)
        .ok_or_else(|| format!("column '{}' not found in input RecordBatch", var1))?;

    // Sort options: ascending, nulls last. Change if needed.
    let opts = SortOptions {
        descending: false,
        nulls_first: false,
    };

    // Build keys slice: first var0, then var1 for lexicographic ordering
    let keys: Vec<(&dyn arrow2::array::Array, SortOptions)> =
        vec![(col0.as_ref(), opts), (col1.as_ref(), opts)];

    // Compute permutation indices for lexicographic sort
    let indices = lexsort_to_indices(&keys, None).map_err(|e| Box::new(e) as Box<dyn Error>)?;

    // Reorder every column using the computed indices
    let new_columns: Result<Vec<ArrayRef>, Box<dyn Error>> = df0
        .columns()
        .iter()
        .map(|col| {
            // take returns Box<dyn Array>, convert to ArrayRef
            let taken = take(col.as_ref(), indices.as_ref(), None)
                .map_err(|e| Box::new(e) as Box<dyn Error>)?;
            Ok(taken)
        })
        .collect();

    let new_columns = new_columns?;

    // Build a new RecordBatch with same schema and reordered columns
    let new_rb = RecordBatch::try_new(Arc::clone(df0.schema()), new_columns)
        .map_err(|e| Box::new(e) as Box<dyn Error>)?;

    Ok(new_rb)
}
```

