/// Sorts a tabular data object (Arrow2 Chunk) by the specified columns
/// 
/// # Arguments
/// * `df0` - The input Chunk containing tabular data
/// * `var0` - Name of the first column to sort by
/// * `var1` - Name of the second column to sort by
/// * `schema` - The schema defining the structure of the chunk
///
/// # Returns
/// A new Chunk sorted by var0 (primary) and var1 (secondary)
fn sort_dataframe_by_columns(
    df0: &Chunk<Box<dyn Array>>,
    var0: &str,
    var1: &str,
    schema: &Schema,
) -> Chunk<Box<dyn Array>> {
    // Get column indices
    let col0_idx = schema.names.iter().position(|name| name == var0)
        .expect("Column var0 not found");
    let col1_idx = schema.names.iter().position(|name| name == var1)
        .expect("Column var1 not found");

    // Create indices and sort them
    let mut indices: Vec<usize> = (0..df0.len()).collect();

    indices.sort_by(|&a, &b| {
        // Compare by first column
        let col0 = &df0.arrays()[col0_idx];
        let cmp0 = compare_values(col0, a, b);

        if cmp0 == std::cmp::Ordering::Equal {
            // If equal, compare by second column
            let col1 = &df0.arrays()[col1_idx];
            compare_values(col1, a, b)
        } else {
            cmp0
        }
    });

    // Reorder all columns according to sorted indices
    let sorted_arrays = df0.arrays()
        .iter()
        .map(|array| reorder_array(array.as_ref(), &indices))
        .collect::<Vec<_>>();

    Chunk::new(sorted_arrays)
}

/// Helper function to compare two values in an array
fn compare_values(array: &dyn Array, idx_a: usize, idx_b: usize) -> std::cmp::Ordering {
    use arrow2::array::*;
    use std::cmp::Ordering;

    // Handle different array types
    if let Some(arr) = array.as_any().downcast_ref::<PrimitiveArray<i32>>() {
        arr.value(idx_a).cmp(&arr.value(idx_b))
    } else if let Some(arr) = array.as_any().downcast_ref::<PrimitiveArray<i64>>() {
        arr.value(idx_a).cmp(&arr.value(idx_b))
    } else if let Some(arr) = array.as_any().downcast_ref::<PrimitiveArray<f32>>() {
        arr.value(idx_a).partial_cmp(&arr.value(idx_b)).unwrap_or(Ordering::Equal)
    } else if let Some(arr) = array.as_any().downcast_ref::<PrimitiveArray<f64>>() {
        arr.value(idx_a).partial_cmp(&arr.value(idx_b)).unwrap_or(Ordering::Equal)
    } else if let Some(arr) = array.as_any().downcast_ref::<Utf8Array<i32>>() {
        arr.value(idx_a).cmp(arr.value(idx_b))
    } else if let Some(arr) = array.as_any().downcast_ref::<BinaryArray<i32>>() {
        arr.value(idx_a).cmp(arr.value(idx_b))
    } else {
        Ordering::Equal
    }
}

/// Helper function to reorder array elements according to indices
fn reorder_array(array: &dyn Array, indices: &[usize]) -> Box<dyn Array> {
    use arrow2::array::*;

    if let Some(arr) = array.as_any().downcast_ref::<PrimitiveArray<i32>>() {
        let reordered: PrimitiveArray<i32> = indices
            .iter()
            .map(|&i| arr.value(i))
            .collect::<Vec<_>>()
            .into();
        Box::new(reordered)
    } else if let Some(arr) = array.as_any().downcast_ref::<PrimitiveArray<i64>>() {
        let reordered: PrimitiveArray<i64> = indices
            .iter()
            .map(|&i| arr.value(i))
            .collect::<Vec<_>>()
            .into();
        Box::new(reordered)
    } else if let Some(arr) = array.as_any().downcast_ref::<Utf8Array<i32>>() {
        let reordered: Utf8Array<i32> = indices
            .iter()
            .map(|&i| arr.value(i))
            .collect::<Vec<_>>()
            .into();
        Box::new(reordered)
    } else {
        // Fallback: return clone of original
        array.to_boxed()
    }
}
