use futures::stream::{self, StreamExt};
use std::pin::Pin;
use std::task::{Context, Poll};

// Define a custom stream struct to merge two streams into pairs
struct MergeStreams<S1, S2> {
    stream1: Pin<Box<S1>>,
    stream2: Pin<Box<S2>>,
}

impl<S1, S2, T1, T2> MergeStreams<S1, S2>
where
    S1: Stream<Item = T1>,
    S2: Stream<Item = T2>,
{
    fn new(stream1: S1, stream2: S2) -> Self {
        MergeStreams {
            stream1: Box::pin(stream1),
            stream2: Box::pin(stream2),
        }
    }
}

// Implement the Stream trait for MergeStreams
impl<S1, S2, T1, T2> Stream for MergeStreams<S1, S2>
where
    S1: Stream<Item = T1>,
    S2: Stream<Item = T2>,
{
    type Item = (T1, T2);

    fn poll_next(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        // Poll both streams for their next items
        let item1 = ready!(self.stream1.as_mut().poll_next(cx));
        let item2 = ready!(self.stream2.as_mut().poll_next(cx));

        // If either stream has ended, return None
        match (item1, item2) {
            (Some(t1), Some(t2)) => Poll::Ready(Some((t1, t2))),
            _ => Poll::Ready(None),
        }
    }
}

// Function to create a merged stream from two input streams
fn merge_streams<S1, S2, T1, T2>(stream1: S1, stream2: S2) -> impl Stream<Item = (T1, T2)>
where
    S1: Stream<Item = T1> + 'static,
    S2: Stream<Item = T2> + 'static,
    T1: 'static,
    T2: 'static,
{
