/// * `first` - The first input sequence (stream)
/// * `second` - The second input sequence (stream)
///
/// # Returns
/// A stream of pairs (tuples) containing elements from the same position
/// in both input sequences.
pub fn merge_sequences<S1, S2>(
    first: S1,
    second: S2,
) -> impl Stream<Item = (S1::Item, S2::Item)>
where
    S1: Stream + Unpin,
    S2: Stream + Unpin,
{
    MergeStream {
        first: first.fuse(),
        second: second.fuse(),
    }
}

/// Internal stream implementation for merging two sequences
struct MergeStream<S1, S2> {
    first: futures::stream::Fuse<S1>,
    second: futures::stream::Fuse<S2>,
}

impl<S1, S2> Stream for MergeStream<S1, S2>
where
    S1: Stream + Unpin,
    S2: Stream + Unpin,
{
    type Item = (S1::Item, S2::Item);

    fn poll_next(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        // Try to get the next element from both streams
        let first_item = self.first.poll_next_unpin(cx);
        let second_item = self.second.poll_next_unpin(cx);

        match (first_item, second_item) {
            // Both streams have elements - create a pair
            (Poll::Ready(Some(a)), Poll::Ready(Some(b))) => Poll::Ready(Some((a, b))),

            // Either stream has ended - stop the merged stream
            (Poll::Ready(None), _) | (_, Poll::Ready(None)) => Poll::Ready(None),

            // Both streams are pending - wait for more data
            (Poll::Pending, Poll::Pending) => Poll::Pending,

            // One stream is pending while the other is ready
            // This shouldn't happen with fused streams, but handle it gracefully
            (Poll::Ready(Some(_)), Poll::Pending) | (Poll::Pending, Poll::Ready(Some(_))) => {
                // Wake up to try again
                cx.waker().wake_by_ref();
                Poll::Pending
            }
        }
    }
}

