    let ncols = labels.len();
    if ncols == 0 {
        // no columns -> empty grouped table with same number of rows
        return Ok((Vec::new(), vec![Vec::new(); table.len()]));
    }

    // validate row lengths
    for (ridx, row) in table.iter().enumerate() {
        if row.len() != ncols {
            return Err(format!(
                "Row {} length {} does not match labels length {}",
                ridx,
                row.len(),
                ncols
            ));
        }
    }

    // Determine group order (labels in order of first appearance) and map each label to group index
    let mut label_to_group: HashMap<String, usize> = HashMap::new();
    let mut group_labels: Vec<String> = Vec::new();
    for lbl in labels {
        let s = lbl.as_ref().to_string();
        if !label_to_group.contains_key(&s) {
            let idx = group_labels.len();
            group_labels.push(s.clone());
            label_to_group.insert(s, idx);
        }
    }

    let ngroups = group_labels.len();
    // Prepare output table: same number of rows, ngroups columns initialized to 0.0
    let mut out: Vec<Vec<f64>> = vec![vec![0.0; ngroups]; table.len()];

    // Sum columns into groups
    for (col_idx, lbl) in labels.iter().enumerate() {
        let s = lbl.as_ref();
        // safe unwrap: label_to_group was built from the same labels
        let gidx = *label_to_group
            .get(s)
            .expect("label missing in label_to_group map");
        for (ridx, row) in table.iter().enumerate() {
            out[ridx][gidx] += row[col_idx];
        }
    }

    Ok((group_labels, out))
}

