/// Sorts a collection of elements by their second component in ascending order.
/// 
/// Each element in the input collection must be a collection with at least two items.
/// Returns a new sorted vector without modifying the original input.
/// 
/// # Arguments
/// * `items` - A collection of items, where each item is itself a collection with at least 2 elements
/// 
/// # Returns
/// A Vec sorted by the second component of each element in ascending order
/// 
/// # Example
/// ```
/// let data = vec![
///     vec![1, 5],
///     vec![2, 3],
///     vec![3, 4],
/// ];
/// let sorted = sort_by_second_component(data);
/// assert_eq!(sorted, vec![
///     vec![2, 3],
///     vec![3, 4],
///     vec![1, 5],
/// ]);
/// ```
fn sort_by_second_component<T: Ord + Clone>(items: Vec<Vec<T>>) -> Vec<Vec<T>> {
    let mut result = items.clone();

    result.sort_by(|a, b| {
        // Compare the second element (index 1) of each sub-collection
        if a.len() < 2 || b.len() < 2 {
            return Ordering::Equal;
        }
        a[1].cmp(&b[1])
    });

    result
}

// Alternative version that works with any indexable collection type
fn sort_by_second_component_generic<T: Ord + Clone, C: AsRef<[T]> + Clone>(
    items: Vec<C>,
) -> Vec<C> {
    let mut result = items.clone();

    result.sort_by(|a, b| {
        let a_slice = a.as_ref();
        let b_slice = b.as_ref();

        if a_slice.len() < 2 || b_slice.len() < 2 {
            return Ordering::Equal;
        }

        a_slice[1].cmp(&b_slice[1])
    });

    result
}

// Example usage
