use ndarray::Array1;
use std::cmp::Ordering;

/// Return the indices of the top `n` largest elements in `arr`.
/// If `n` is 0 returns an empty Vec. If `n` >= arr.len() returns all indices
/// sorted by value descending. T only needs to implement PartialOrd.
///
/// Ties are broken arbitrarily (stable order not guaranteed).
pub fn top_n_indices<T>(arr: &Array1<T>, n: usize) -> Vec<usize>
where
    T: PartialOrd,
{
    let len = arr.len();
    if n == 0 || len == 0 {
        return Vec::new();
    }

    // Collect indices 0..len, then sort them by comparing the referenced values.
    let mut inds: Vec<usize> = (0..len).collect();
    inds.sort_by(|&i, &j| {
        // compare arr[j] to arr[i] so sorting is descending (largest first)
        match arr.get(j).unwrap().partial_cmp(arr.get(i).unwrap()) {
            Some(ord) => ord,
            // If comparison is None (e.g., NaN if using floats), treat as equal.
            None => Ordering::Equal,
        }
    });

    if n >= inds.len() {
        inds
    } else {
        inds.truncate(n);
        inds
    }
}

fn main() {
    // Example usage:
    let a = Array1::from(vec![3.0, 1.0, 4.0, 1.5, 2.5]);
    let top3 = top_n_indices(&a, 3);
    println!("Top 3 indices: {:?}", top3);
    // For this array one possible output: Top 3 indices: [2, 0, 4]
}
```

