use ndarray::Array1;
use ndarray_stats::QuantileExt;

/// Find the indices of the N highest values in a list
/// 
/// # Arguments
/// * `data` - A slice of f64 values
/// * `n` - Number of highest values to find
/// 
/// # Returns
/// * `Vec<usize>` - Vector of indices of the N highest values (sorted in descending order of values)
/// 
/// # Panics
/// * If `n` is greater than the length of the data
/// * If the data is empty
pub fn indices_of_n_highest_values(data: &[f64], n: usize) -> Vec<usize> {
    assert!(!data.is_empty(), "Data cannot be empty");
    assert!(n <= data.len(), "n cannot be greater than data length");

    // Convert slice to ndarray Array1
    let arr = Array1::from_vec(data.to_vec());

    // Find the threshold value (the nth highest value)
    // We use quantile to find the value at position (1 - n/data.len())
    let threshold = if n == data.len() {
        // If n equals data length, threshold is the minimum value
        *arr.min().unwrap()
    } else {
        // Find the value at the (n-1)th position from the top
        let quantile = 1.0 - (n as f64 - 1.0) / data.len() as f64;
        *arr.quantile_axis_mut(ndarray::Axis(0), ndarray_stats::Quantile::new(quantile)).unwrap()
    };

    // Collect indices of values >= threshold
    let mut indices: Vec<usize> = data.iter()
        .enumerate()
        .filter(|(_, &val)| val >= threshold)
        .map(|(idx, _)| idx)
        .collect();

    // Sort indices by their corresponding values in descending order
    indices.sort_by(|&a, &b| data[b].partial_cmp(&data[a]).unwrap());

    // If we have more indices than needed (due to ties), trim to n
    indices.truncate(n);

    indices
}

