use ndarray::Array1;
use ndarray_stats::QuantileExt;

/// Determines the indices of the N highest values in a list.
/// 
/// # Arguments
/// * `data` - A slice of numeric values
/// * `n` - The number of highest values to find
/// 
/// # Returns
/// A vector of indices corresponding to the N highest values, sorted in descending order by value
/// 
/// # Example
/// ```
/// let data = vec![10.0, 5.0, 20.0, 15.0, 3.0];
/// let indices = find_n_highest_indices(&data, 3);
/// // Returns: [2, 3, 0] (values: 20.0, 15.0, 10.0)
/// ```
fn find_n_highest_indices(data: &[f64], n: usize) -> Vec<usize> {
    if data.is_empty() || n == 0 {
        return Vec::new();
    }

    let n = n.min(data.len());

    // Create an array from the data
    let array = Array1::from(data.to_vec());

    // Create a vector of (index, value) pairs
    let mut indexed_data: Vec<(usize, f64)> = array
        .iter()
        .enumerate()
        .map(|(idx, &val)| (idx, val))
        .collect();

    // Sort by value in descending order
    indexed_data.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));

    // Extract the indices of the top N values
    indexed_data
        .iter()
        .take(n)
        .map(|(idx, _)| *idx)
        .collect()
}

