/// // Sum: 2 + 3 + 4 + 6 + 8 + 12 = 35
/// assert_eq!(result, 35);
/// ```
fn sum_of_subset_products(list: &[i64], k: usize) -> i64 {
    if k == 0 || k > list.len() {
        return if k == 0 { 1 } else { 0 };
