pub fn categorical_to_indices<T>(
    df0: Vec<Vec<T>>,
    col0: usize,
) -> (Vec<Vec<T>>, IndexMap<T, usize>)
where
    T: Serialize + for<'a> Deserialize<'a> + Eq + std::hash::Hash + Clone,
