use rxrust::prelude::*;

fn adjacent_pairs_greater_than_10(numbers: Vec<i32>) -> Vec<(i32, i32)> {
    let mut result = Vec::new();

    observable::of(numbers)
        .pipe(
            operators::flat_map(|nums| {
                observable::from_iter(
                    nums.windows(2)
                        .map(|window| (window[0], window[1]))
                        .collect::<Vec<_>>()
                )
            }),
            operators::filter(|(a, b)| a + b > 10),
        )
        .subscribe(|pair| {
            result.push(pair);
        });

    result
}

