use ndarray::prelude::*;
use ndarray::Axis;

fn remove_zero_columns(data: Array2<f64>) -> Array2<f64> {
    // Check which columns are all zeros
    let all_zero_mask = data.sum_axis(Axis(0)).mapv(|x| x == 0.0);

    // Select columns that are not all zeros
    let selected_columns = all_zero_mask
        .iter()
        .enumerate()
        .filter_map(|(i, &is_zero)| if !is_zero { Some(i) } else { None })
        .collect::<Vec<_>>();

    // Slice the array to keep only the selected columns
    data.select(Axis(1), &selected_columns)
}

fn main() {
