```rust
use hashlink::LinkedHashMap;

/// Assigns a unique integer to each distinct value in the order they first appear.
/// 
/// # Arguments
/// * `values` - A slice of values to be assigned unique integers
/// 
/// # Returns
/// A vector of tuples containing (original_value, unique_id)
/// 
/// # Example
/// ```
/// let values = vec!["apple", "banana", "apple", "cherry", "banana"];
/// let result = assign_unique_ids(values);
/// // result: [("apple", 0), ("banana", 1), ("apple", 0), ("cherry", 2), ("banana", 1)]
/// ```
fn assign_unique_ids<T: Clone + Eq + std::hash::Hash>(
    values: Vec<T>,
) -> Vec<(T, u32)> {
    let mut map: LinkedHashMap<T, u32> = LinkedHashMap::new();
    let mut next_id: u32 = 0;
    let mut result = Vec::new();

    for value in values {
        let id = if let Some(&existing_id) = map.get(&value) {
            existing_id
        } else {
            map.insert(value.clone(), next_id);
            let new_id = next_id;
            next_id += 1;
            new_id
        };
        result.push((value, id));
    }

    result
}

