```rust
use arrow::array::{Array, Float64Array, StringArray};
use arrow::datatypes::{DataType, Field, Schema};
use arrow::record_batch::RecordBatch;
use std::sync::Arc;

/// Replace missing values in `target_column` with corresponding values from `source_column`
/// 
/// # Arguments
/// * `batch` - The input RecordBatch containing the data
/// * `target_column` - Name of the column where missing values should be replaced
/// * `source_column` - Name of the column providing replacement values
/// 
/// # Returns
/// * `Result<RecordBatch, String>` - A new RecordBatch with missing values replaced, or an error message
pub fn replace_missing_values(
    batch: &RecordBatch,
    target_column: &str,
    source_column: &str,
) -> Result<RecordBatch, String> {
    // Find column indices
    let target_idx = batch
        .schema()
        .index_of(target_column)
        .map_err(|e| format!("Target column '{}' not found: {}", target_column, e))?;

    let source_idx = batch
        .schema()
        .index_of(source_column)
        .map_err(|e| format!("Source column '{}' not found: {}", source_column, e))?;

    // Get the arrays
    let target_array = batch.column(target_idx);
    let source_array = batch.column(source_idx);

    // Check data types match
    if target_array.data_type() != source_array.data_type() {
        return Err(format!(
            "Column data types don't match: target is {:?}, source is {:?}",
            target_array.data_type(),
            source_array.data_type()
        ));
    }

    // Process based on data type
    let new_array: Arc<dyn Array> = match target_array.data_type() {
        DataType::Float64 => {
            let target = target_array
                .as_any()
                .downcast_ref::<Float64Array>()
                .ok_or("Failed to downcast target to Float64Array")?;
            let source = source_array
                .as_any()
                .downcast_ref::<Float64Array>()
                .ok_or("Failed to downcast source to Float64Array")?;

            let values: Vec<f64> = (0..target.len())
                .map(|i| {
                    if target.is_null(i) {
                        source.value(i)
                    } else {
                        target.value(i)
                    }
                })
                .collect();

            Arc::new(Float64Array::from(values))
        }
        DataType::Utf8 => {
            let target = target_array
                .as_any()
                .downcast_ref::<StringArray>()
                .ok_or("Failed to downcast target to StringArray")?;
            let source = source_array
                .as_any()
                .downcast_ref::<StringArray>()
                .ok_or("Failed to downcast source to StringArray")?;

            let values: Vec<Option<&str>> = (0..target.len())
                .map(|i| {
                    if target.is_null(i) {
                        if source.is_null(i) {
                            None
                        } else {
                            Some(source.value(i))
                        }
                    } else {
                        Some(target.value(i))
                    }
                })
                .collect();

            Arc::new(StringArray::from(values))
        }
        _ => return Err(format!(
            "Unsupported data type: {:?}",
            target_array.data_type()
        )),
    };

    // Build new schema and record batch
    let mut fields = batch.schema().fields().clone();
    fields[target_idx] = Arc::new(Field::new(target_column, new_array.data_type().clone(), true));

    let new_schema = Arc::new(Schema::new(fields));

    let mut columns = batch.columns().to_vec();
    columns[target_idx] = new_array;

    RecordBatch::try_new(new_schema, columns)
        .map_err(|e| format!("Failed to create new RecordBatch: {}", e))
}

// Example usage
#[cfg(test)]
mod tests {
    use super::*;
    use arrow::array::Float64Array;
    use arrow::datatypes::Field;
    use std::sync::Arc;

    #[test]
    fn test_replace_missing_values() {
        // Create test data
        let schema = Arc::new(Schema::new(vec![
            Field::new("a", DataType::Float64, true),
            Field::new("b", DataType::Float64, true),
        ]));

        let a = Float64Array::from(vec![Some(1.0), None, Some(3.0), None]);
        let b = Float64Array::from(vec![Some(10.0), Some(20.0), None, Some(40.0)]);

        let batch = RecordBatch::try_new(schema, vec![Arc::new(a), Arc::new(b)]).unwrap();

        // Replace missing values in column "a" with values from column "b"
        let result = replace_missing_values(&batch, "a", "b").unwrap();

        // Check results
        let result_a = result
            .column(0)
            .as_any()
            .downcast_ref::<Float64Array>()
            .unwrap();

        assert_eq!(result_a.value(0), 1.0);  // Original value
        assert_eq!(result_a.value(1), 20.0); // Replaced missing value
        assert_eq!(result_a.value(2), 3.0);  // Original value
        assert_eq!(result_a.value(3), 40.0); // Replaced missing value
    }
}
