///     [1.0, 2.0],
///     [2.0, 3.0],
///     [3.0, 4.0],
///     [4.0, 5.0]
/// ];
///
/// let corr = calculate_correlation(&df, 0, 1).unwrap();
/// assert!((corr - 1.0).abs() < f64::EPSILON);
/// ```
pub fn calculate_correlation(df0: &Array2<f64>, var0: usize, var1: usize) -> Result<f64, Box<dyn Error>> {
    // Validate column indices
    if var0 >= df0.ncols() || var1 >= df0.ncols() {
        return Err("Column indices out of bounds".into());
    }

    // Extract the two columns as vectors
    let col0 = df0.column(var0).to_owned();
