    // Convert to Array1 for correlation calculation
    let col0_array: Array1<f64> = col0.into();
    let col1_array: Array1<f64> = col1.into();

    // Calculate Pearson correlation
    let corr = pearson(&col0_array, &col1_array);

    Ok(corr)
}
