/// ```
/// use polars::prelude::*;
///
/// let df = df! {
///     "col1" => &[1, 2, 3],
///     "col2" => &[Some(1.0), None, Some(3.0)],
///     "col3" => &["a", "b", "c"],
/// }.unwrap();
///
/// let cols_with_missing = find_columns_with_missing_values(&df);
/// assert_eq!(cols_with_missing, vec!["col2"]);
/// ```
fn find_columns_with_missing_values(df: &DataFrame) -> Vec<String> {
    df.get_columns()
        .iter()
        .filter_map(|col| {
            // Check if the column has any null values
            if col.null_count() > 0 {
                Some(col.name().to_string())
            } else {
                None
            }
        })
        .collect()
}

