            "col2" => &[Some(1.0), None, Some(3.0)],
            "col3" => &["a", "b", "c"],
            "col4" => &[Some("x"), Some("y"), None],
        }.unwrap();

        let cols_with_missing = find_columns_with_missing_values(&df);
        assert_eq!(cols_with_missing.len(), 2);
        assert!(cols_with_missing.contains(&"col2".to_string()));
