```rust
use ndarray::{Array2};

/// Replace NaN entries in each column with the column mean.
/// Input and output are `Array2<f64>`. Missing entries are expected as `f64::NAN`.
pub fn impute_column_means(mut data: Array2<f64>) -> Array2<f64> {
    let (nrows, ncols) = data.dim();
    for j in 0..ncols {
        // Compute mean of non-NaN values in column j
        let mut sum = 0.0;
        let mut count = 0usize;
        for i in 0..nrows {
            let v = data[(i, j)];
            if !v.is_nan() {
                sum += v;
                count += 1;
            }
        }
        let mean = if count > 0 {
            sum / (count as f64)
        } else {
            // If whole column is missing, choose 0.0 (alternatively choose NaN or other sentinel)
            0.0
        };

        // Replace NaNs with the computed mean
        for i in 0..nrows {
            if data[(i, j)].is_nan() {
                data[(i, j)] = mean;
            }
        }
    }
    data
}
```

