/// Reorders a sequence of tuples based on a desired ordering sequence.
/// This version uses a cycle detection algorithm to avoid requiring Default trait.
///
/// # Arguments
/// * `lst0` - A mutable vector of tuples to be reordered
/// * `lst1` - A slice defining the desired ordering (as indices)
///
/// # Panics
/// Panics if `lst1` contains indices that are out of bounds for `lst0`
/// or if `lst1` doesn't contain all indices from 0 to lst0.len()-1
pub fn reorder_by_sequence_no_default<T>(lst0: &mut Vec<T>, lst1: &[usize]) {
    assert_eq!(
        lst0.len(),
        lst1.len(),
        "lst1 must have the same length as lst0"
    );

    let n = lst0.len();

    // Create a mapping from current position to desired position
    // desired_position[old_index] = new_position
    let mut desired_position = vec![0usize; n];
    for (new_pos, &old_idx) in lst1.iter().enumerate() {
        assert!(
            old_idx < n,
            "Index {} in lst1 is out of bounds for lst0 (length {})",
            old_idx,
            n
        );
        desired_position[old_idx] = new_pos;
    }

    // Apply permutation using cycle decomposition
    let mut visited = vec![false; n];

    for i in 0..n {
        if visited[i] {
            continue;
        }

        // Start a new cycle
        let mut current = i;
        let mut cycle_elements = Vec::new();

        while !visited[current] {
            visited[current] = true;
            cycle_elements.push(current);
            current = desired_position[current];
        }

        // Rotate the cycle
        if cycle_elements.len() > 1 {
            // Save the first element
            let temp = std::mem::replace(
                &mut lst0[cycle_elements[0]],
                unsafe { std::mem::zeroed() } // Placeholder, will be overwritten
            );

            // Shift elements along the cycle
            for j in 1..cycle_elements.len() {
                lst0[cycle_elements[j-1]] = std::mem::replace(
                    &mut lst0[cycle_elements[j]],
                    unsafe { std::mem::zeroed() }
                );
            }

            // Place the saved element at the end of the cycle
            let last_idx = cycle_elements[cycle_elements.len() - 1];
            lst0[last_idx] = temp;
        }
    }
}

// Example usage
