use sorted_vec::SortedVec;

/// Reorders lst0 according to the order specified in lst1.
/// 
/// # Arguments
/// * `lst0` - A vector of tuples to be reordered
/// * `lst1` - A vector that defines the desired ordering (first element of tuples in lst0)
///
/// # Returns
/// A new vector with lst0's tuples reordered according to lst1
///
/// # Example
/// ```
/// let lst0 = vec![(3, "three"), (1, "one"), (2, "two")];
/// let lst1 = vec![2, 3, 1];
/// let result = reorder_by_sequence(lst0, lst1);
/// assert_eq!(result, vec![(2, "two"), (3, "three"), (1, "one")]);
/// ```
fn reorder_by_sequence<T: Clone + Eq + Ord>(
    lst0: Vec<(T, String)>,
    lst1: Vec<T>,
) -> Vec<(T, String)> {
    // Create a mapping from values in lst1 to their desired position
    let order_map: std::collections::HashMap<&T, usize> =
        lst1.iter().enumerate().map(|(idx, val)| (val, idx)).collect();

    // Create a SortedVec that maintains ordering based on lst1's sequence
    let mut sorted_tuples: SortedVec<_> = SortedVec::new();

    for tuple in lst0 {
        // Get the desired position from our order map
        let position = order_map.get(&tuple.0).copied().unwrap_or(usize::MAX);

        // Insert a wrapper that sorts by position
        sorted_tuples.insert((position, tuple));
    }

    // Extract the reordered tuples, filtering out any that weren't in lst1
    sorted_tuples
        .iter()
        .filter(|(pos, _)| *pos != usize::MAX)
        .map(|(_, tuple)| tuple.clone())
        .collect()
}

// Alternative implementation without sorted-vec (more practical)
fn reorder_by_sequence_simple<T: Clone + Eq + Ord>(
    lst0: Vec<(T, String)>,
    lst1: Vec<T>,
) -> Vec<(T, String)> {
    let mut result = vec![None; lst1.len()];
    let order_map: std::collections::HashMap<&T, usize> =
        lst1.iter().enumerate().map(|(idx, val)| (val, idx)).collect();

    for tuple in lst0 {
        if let Some(&idx) = order_map.get(&tuple.0) {
            result[idx] = Some(tuple);
        }
    }

    result.into_iter().filter_map(|x| x).collect()
}

