use linfa::prelude::*;
use linfa_trees::DecisionTree;
use std::collections::VecDeque;

fn extract_decision_rules(tree: &DecisionTree<f64>, feature_names: &[&str]) -> Vec<String> {
    let mut rules = Vec::new();
    let mut queue = VecDeque::new();

    // Start with the root node
    queue.push_back((0, String::new()));

    while let Some((node_index, condition)) = queue.pop_front() {
        match tree.nodes()[node_index] {
            linfa_trees::Node::Decision { feature_index, threshold, left_child, right_child } => {
                let feature_name = feature_names[*feature_index as usize];
                let left_condition = format!("{} AND {} <= {}", condition, feature_name, threshold);
                let right_condition = format!("{} AND {} > {}", condition, feature_name, threshold);

                queue.push_back((*left_child, left_condition.clone()));
                queue.push_back((*right_child, right_condition));
            },
            linfa_trees::Node::Leaf { value } => {
                let class = value.argmax().unwrap();
                let rule = format!("{} THEN class = {}", condition, class);
                rules.push(rule);
            },
        }
    }

    rules
}

