///
/// # Arguments
///
/// * `tree0`: The trained decision tree object.
/// * `feature_names0`: The list of feature names corresponding to the tree's features.
///
/// # Returns
///
/// A vector of human-readable decision rules as strings.
fn extract_decision_rules(tree0: &DecisionTree, feature_names0: &[String]) -> Vec<String> {
    let mut rules = Vec::new();

