        if let Some(feature_index) = node.feature_index() {
            // Get the feature name from the feature names list
            let feature_name = &feature_names0[feature_index as usize];

            // Get the threshold value for the decision
            let threshold = node.threshold();

            // Determine the operator based on the decision type
            let operator = match node.decision_type() {
                linfatrees::DecisionType::LessThan => "<",
                linfatrees::DecisionType::GreaterThan => ">",
                linfatrees::DecisionType::LessThanOrEqual => "<=",
                linfatrees::DecisionType::GreaterThanOrEqual => ">=",
                linfatrees::DecisionType::Equal => "==",
                linfatrees::DecisionType::NotEqual => "!=",
            };

            // Construct the decision rule as a human-readable string
            let rule = format!("{} {} {}", feature_name, operator, threshold);

            // Add the rule to the list of rules
            rules.push(rule);
        }
    }

