/// Extracts human-readable decision rules from a trained decision tree.
///
/// # Arguments
/// * `tree` - A reference to the trained DecisionTree object
/// * `feature_names` - A slice of feature names corresponding to the features used in training
///
/// # Returns
/// A vector of strings, each containing a human-readable decision rule
pub fn extract_decision_rules(
    tree: &DecisionTree,
    feature_names: &[String],
) -> Vec<String> {
    let mut rules = Vec::new();
    let mut current_conditions: Vec<String> = Vec::new();

    // Start recursive traversal from the root node
    traverse_tree(tree, 0, feature_names, &mut current_conditions, &mut rules);

    rules
}

/// Recursively traverses the decision tree to extract rules
fn traverse_tree(
    tree: &DecisionTree,
    node_index: usize,
    feature_names: &[String],
    current_conditions: &mut Vec<String>,
    rules: &mut Vec<String>,
) {
    // Get the node information
    let node = tree.get_node(node_index);

    // Check if this is a leaf node
    if node.is_leaf() {
        // Build the complete rule string
        let mut rule = String::new();
        rule.push_str("IF ");

        for (i, condition) in current_conditions.iter().enumerate() {
            if i > 0 {
                rule.push_str(" AND ");
            }
            rule.push_str(condition);
        }

        // Add the prediction
        let prediction = node.get_prediction();
        write!(rule, " THEN predict = {}", prediction).unwrap();

        rules.push(rule);
    } else {
        // This is a decision node
        let feature_index = node.get_feature_index();
        let threshold = node.get_threshold();

        // Get the feature name (with fallback)
        let feature_name = if feature_index < feature_names.len() {
            &feature_names[feature_index]
        } else {
            &format!("feature_{}", feature_index)
        };

        // Left child (feature <= threshold)
        let left_condition = format!("{} <= {:.4}", feature_name, threshold);
        current_conditions.push(left_condition);
        traverse_tree(
            tree,
            node.get_left_child(),
            feature_names,
            current_conditions,
            rules,
        );
        current_conditions.pop();

        // Right child (feature > threshold)
        let right_condition = format!("{} > {:.4}", feature_name, threshold);
        current_conditions.push(right_condition);
        traverse_tree(
            tree,
            node.get_right_child(),
            feature_names,
            current_conditions,
            rules,
        );
        current_conditions.pop();
    }
}

