            .map(|_| batch.schema().index_of(col_name))?;

        let mut col_values: Vec<Option<String>> = vec![];
        for row in &expanded_rows {
            col_values.push(row[col_idx].clone());
        }

        let string_array = StringArray::from(col_values);
        new_columns.push(Arc::new(string_array));
    }

    Ok(RecordBatch::try_new(new_schema, new_columns)?)
