    let priority_set: std::collections::HashSet<&str> = priority_order.iter().cloned().collect();

    // Function to reorder columns in a single row
    fn reorder_row(
        row: IndexMap<String, String>,
        priority_order: &[&str],
        priority_set: &std::collections::HashSet<&str>,
    ) -> IndexMap<String, String> {
        let mut new_row = IndexMap::new();

        // Add priority columns in the specified order
        for &col_name in priority_order {
