use indexmap::IndexMap;
use std::collections::HashMap;

/// Concatenates new columns onto a base table while preserving the specified column order.
///
/// # Arguments
/// * `base_table` - The original table as a map of column names to their data
/// * `new_columns` - A map of new column names to their data
/// * `priority_order` - The desired column order, with specified columns first
///
/// # Returns
/// A new table with columns in the specified order, followed by remaining columns
/// in their original relative positions
pub fn concatenate_with_order(
    base_table: &IndexMap<String, Vec<f64>>,
    new_columns: &IndexMap<String, Vec<f64>>,
    priority_order: &[String],
) -> IndexMap<String, Vec<f64>> {
    // First collect all unique columns from both tables
    let mut all_columns = IndexMap::new();
    all_columns.extend(base_table.iter().map(|(k, v)| (k.clone(), v.clone())));
    all_columns.extend(new_columns.iter().map(|(k, v)| (k.clone(), v.clone())));

    // Create a map from column name to its position in the priority order
    let mut priority_map = HashMap::new();
    for (i, col) in priority_order.iter().enumerate() {
        if all_columns.contains_key(col) {
            priority_map.insert(col.clone(), i);
        }
    }

    // Sort columns by priority (lower number = higher priority)
    let mut sorted_columns: Vec<_> = all_columns
        .into_iter()
        .map(|(k, v)| (k, v))
        .collect();

    sorted_columns.sort_by(|(a, _), (b, _)| {
        priority_map.get(a).cmp(&priority_map.get(b))
            .then_with(|| a.cmp(b)) // If not in priority list, maintain original order
    });

    // Convert back to IndexMap (IndexMap preserves insertion order)
    sorted_columns.into_iter().collect()
}

