/// - the priority block is inserted at the position of the first occurrence of any of those priority
///   names in the original `base` order (or appended if none appear in `base`),
/// - all other columns keep their original relative order.
///
/// T must be Clone (column data cloned when merged).
///
/// Example:
/// let mut base: IndexMap<String, Vec<i32>> = IndexMap::new();
/// base.insert("A".into(), vec![1]);
/// base.insert("B".into(), vec![2]);
/// base.insert("C".into(), vec![3]);
///
/// let mut new_cols: IndexMap<String, Vec<i32>> = IndexMap::new();
/// new_cols.insert("X".into(), vec![9]);
/// new_cols.insert("B".into(), vec![20]); // replaces base B
///
/// let priority = vec!["X".into(), "B".into()];
///
/// let merged = merge_columns_with_priority(base, new_cols, &priority);
/// // merged keys order: A, X, B, C   (priority inserted at position of first priority found in base (B at index 1),
/// // and X placed before B according to priority_order)
///
pub fn merge_columns_with_priority<T: Clone>(
    base: IndexMap<String, Vec<T>>,
    new_cols: IndexMap<String, Vec<T>>,
    priority_order: &[String],
) -> IndexMap<String, Vec<T>> {
    // Start with merged = base, then insert/replace with new_cols (new insertions go to the end of merged).
    let mut merged = base.clone();
    for (k, v) in new_cols.into_iter() {
        merged.insert(k, v);
    }

    // Keep base key order for determining insertion position and for preserving relative order of non-priority columns.
    let base_keys: Vec<String> = base.keys().cloned().collect();
    let priority_set: HashSet<&String> = priority_order.iter().collect();

    // Find earliest index in base_keys where a priority column appears; if none, append at end.
    let insertion_index = base_keys
        .iter()
        .position(|k| priority_set.contains(k))
        .unwrap_or(base_keys.len());

    let mut result: IndexMap<String, Vec<T>> = IndexMap::new();

    // Add base columns before the insertion index, skipping any priority columns (they will be added in the block).
    for k in base_keys.iter().take(insertion_index) {
        if !priority_set.contains(k) {
            if let Some(col) = merged.get(k) {
                result.insert(k.clone(), col.clone());
            }
        }
    }

    // Insert priority columns in the exact requested sequence, but only if they exist in the merged data.
    for pname in priority_order.iter() {
        if let Some(col) = merged.get(pname) {
            result.insert(pname.clone(), col.clone());
        }
    }

    // Add remaining base columns after the insertion index, skipping priority columns.
    for k in base_keys.iter().skip(insertion_index) {
        if !priority_set.contains(k) {
            if let Some(col) = merged.get(k) {
                result.insert(k.clone(), col.clone());
            }
        }
    }

    // Finally, append any columns present in `merged` that haven't been inserted yet
    // (these are new columns that were not in `base` and not in `priority_order`).
    for (k, col) in merged.into_iter() {
        if !result.contains_key(&k) {
            result.insert(k, col);
        }
    }

    result
}

