///
/// let priority = vec!["c", "a"];
/// let result = reorder_columns(base, priority);
///
/// // Result columns: c, a, b, d
/// assert_eq!(result[0].keys().cloned().collect::<Vec<_>>(), vec!["c", "a", "b", "d"]);
/// ```
pub fn reorder_columns<T: Clone>(
    base_table: Vec<IndexMap<String, T>>,
    priority_columns: Vec<&str>,
) -> Vec<IndexMap<String, T>> {
    if base_table.is_empty() {
        return base_table;
    }

    // Collect all column names from the first row (assuming all rows have same columns)
    let all_columns: Vec<&str> = base_table[0].keys().map(|k| k.as_str()).collect();

    // Build the new column order
    let mut new_order: Vec<&str> = Vec::new();
    let mut seen = std::collections::HashSet::new();

    // First, add priority columns in the specified order
    for col in &priority_columns {
        if all_columns.contains(col) && seen.insert(col) {
            new_order.push(col);
        }
    }

    // Then, add remaining columns in their original order
    for col in &all_columns {
        if seen.insert(col) {
            new_order.push(col);
        }
    }

    // Reorder each row according to the new column order
    base_table
        .into_iter()
        .map(|row| {
            let mut new_row = IndexMap::new();
            for col in &new_order {
                if let Some(value) = row.get(*col) {
                    new_row.insert(col.to_string(), value.clone());
                }
            }
            new_row
        })
        .collect()
}

