use indexmap::IndexMap;

/// Concatenates new columns onto a base table while preserving a specified column order.
///
/// # Arguments
/// * `base_table` - A map representing the base table where keys are column names and values are column data
/// * `new_columns` - A map of additional columns to append
/// * `priority_order` - A vector of column names defining the desired order for priority columns
///
/// # Returns
/// A new IndexMap with columns ordered according to the priority_order, followed by remaining columns
/// in their original relative order.
///
/// # Example
/// ```
/// use indexmap::IndexMap;
///
/// let mut base = IndexMap::new();
/// base.insert("name".to_string(), vec!["Alice", "Bob"]);
/// base.insert("age".to_string(), vec!["30", "25"]);
///
/// let mut new = IndexMap::new();
/// new.insert("city".to_string(), vec!["NYC", "LA"]);
/// new.insert("id".to_string(), vec!["1", "2"]);
///
/// let priority = vec!["id".to_string(), "name".to_string()];
///
/// let result = merge_columns_with_priority(&base, &new, &priority);
/// // Result order: id, name, age, city
/// ```
fn merge_columns_with_priority<T: Clone>(
    base_table: &IndexMap<String, T>,
    new_columns: &IndexMap<String, T>,
    priority_order: &[String],
) -> IndexMap<String, T> {
    let mut result: IndexMap<String, T> = IndexMap::new();

    // First, add columns in priority order
    for col_name in priority_order {
        if let Some(col_data) = base_table.get(col_name) {
            result.insert(col_name.clone(), col_data.clone());
        } else if let Some(col_data) = new_columns.get(col_name) {
            result.insert(col_name.clone(), col_data.clone());
        }
    }

    // Then, add remaining columns from base_table in their original order
    for (col_name, col_data) in base_table.iter() {
        if !result.contains_key(col_name) {
            result.insert(col_name.clone(), col_data.clone());
        }
    }

    // Finally, add remaining columns from new_columns in their original order
    for (col_name, col_data) in new_columns.iter() {
        if !result.contains_key(col_name) {
            result.insert(col_name.clone(), col_data.clone());
        }
    }

    result
}

