fn group_by_hierarchical_index(df0: DataFrame, var0: &str) -> Result<DataFrame, PolarsError> {
    // Get unique values from the grouping column
    let group_values = df0.column(var0)?.unique()?;
    let group_values_vec: Vec<AnyValue> = group_values.iter().collect();

    // Create a mapping from group values to indices
    let mut group_indices: HashMap<AnyValue, Vec<usize>> = HashMap::new();

    // Iterate through the DataFrame to collect indices for each group
    for (idx, row) in df0.iter().enumerate() {
        let group_val = row.get(0).unwrap(); // Get the value from the first column (grouping column)
        group_indices.entry(group_val.clone())
            .or_insert_with(Vec::new)
            .push(idx);
    }

    // Create the hierarchical index columns
    let mut hierarchical_index_cols: Vec<Series> = Vec::new();
    let mut hierarchical_index_names: Vec<String> = Vec::new();

    // Add the group column as the first level of the hierarchical index
