    hierarchical_index_cols.push(group_series);
    hierarchical_index_names.push(var0.to_string());

    // Create a second level index (within-group index)
    let mut within_group_indices: Vec<u32> = Vec::new();
    for group_val in group_values_vec.iter() {
        let indices = group_indices.get(group_val).unwrap();
        for (i, _) in indices.iter().enumerate() {
            within_group_indices.push(i as u32);
        }
    }

    let within_group_series = Series::new("within_group_index", &within_group_indices);
    hierarchical_index_cols.push(within_group_series);
    hierarchical_index_names.push("within_group_index".to_string());

    // Create the hierarchical index DataFrame
    let hierarchical_index_df = DataFrame::new(hierarchical_index_cols)?;

