use serde_json::{Value, Map};
use std::collections::HashMap;

// Function to sort records by a specified key according to a custom order
pub fn sort_by_custom_order<T: serde::Serialize + serde::de::DeserializeOwned>(
    records: Vec<T>,
    key_path: &str,
    custom_order: Vec<Value>,
) -> Vec<T>
where
    for<'de> T: serde::Deserialize<'de>,
{
    // Create a mapping from value to its position in the custom order
    let mut value_to_position: HashMap<Value, usize> = HashMap::new();
    for (position, value) in custom_order.iter().enumerate() {
        value_to_position.insert(value.clone(), position);
    }

    // Sort the records based on the custom order
    let mut sorted_records = records;
    sorted_records.sort_by(|a, b| {
        // Extract the key value from both records
        let a_key = extract_key_value(a, key_path).unwrap_or_else(|| Value::Null);
        let b_key = extract_key_value(b, key_path).unwrap_or_else(|| Value::Null);

        // Compare based on the custom order
        match (value_to_position.get(&a_key), value_to_position.get(&b_key)) {
            (Some(pos_a), Some(pos_b)) => pos_a.cmp(pos_b),
            (Some(_), None) => std::cmp::Ordering::Less,  // a_key is in order, b_key isn't
            (None, Some(_)) => std::cmp::Ordering::Greater,  // a_key isn't in order, b_key is
            (None, None) => std::cmp::Ordering::Equal,  // neither is in order
        }
    });

    sorted_records
}

// Helper function to extract a nested value from a serde_json::Value
fn extract_key_value(value: &Value, key_path: &str) -> Option<Value> {
    let keys: Vec<&str> = key_path.split('.').collect();
    let mut current = value;

    for key in keys {
        if let Value::Object(map) = current {
            if let Some(next_value) = map.get(key) {
                current = next_value;
                continue;
            } else {
                return None;
            }
        } else {
            return None;
        }
    }

    Some(current.clone())
}

