///     [("name", "Charlie"), ("status", "active")].iter().cloned().collect::<HashMap<&str, &str>>(),
/// ];
///
/// let order = vec!["pending", "active"];
/// let result = sort_by_custom_order(&records, "status", &order);
/// ```
fn sort_by_custom_order<T: Clone + Eq + std::hash::Hash + std::fmt::Debug>(
    records: &[HashMap<String, T>],
    sort_key: &str,
    order: &[T],
) -> Vec<HashMap<String, T>> {
    // Create a mapping from each value to its position in the order sequence
    let position_map: HashMap<&T, usize> = order
        .iter()
        .enumerate()
        .map(|(idx, val)| (val, idx))
        .collect();

    // Clone and sort the records
    let mut sorted = records.to_vec();
    sorted.sort_by(|a, b| {
        // Get the sort key values from both records
        let a_val = a.get(sort_key);
        let b_val = b.get(sort_key);

        match (a_val, b_val) {
            // Both have the key: compare by position in order sequence
            (Some(a_value), Some(b_value)) => {
                let a_pos = position_map.get(a_value).copied().unwrap_or(usize::MAX);
                let b_pos = position_map.get(b_value).copied().unwrap_or(usize::MAX);
                a_pos.cmp(&b_pos)
            }
            // Only a has the key: it comes after
            (Some(_), None) => std::cmp::Ordering::Greater,
            // Only b has the key: it comes before
            (None, Some(_)) => std::cmp::Ordering::Less,
            // Neither has the key: maintain original order
