```rust
use streaming_iterator::StreamingIterator;

/// A tiny StreamingIterator wrapper around a slice.
/// The iterator's current element is at `pos`; `get()` returns the item at `pos` (if any)
/// and `advance()` moves to the next element.
pub struct SliceStream<'a, T> {
    slice: &'a [T],
    pos: usize,
}

impl<'a, T> SliceStream<'a, T> {
    pub fn new(slice: &'a [T]) -> Self {
        SliceStream { slice, pos: 0 }
    }
}

impl<'a, T> StreamingIterator for SliceStream<'a, T> {
    type Item = T;

    fn advance(&mut self) {
        if self.pos < self.slice.len() {
            self.pos += 1;
        }
    }

    fn get(&self) -> Option<&Self::Item> {
        if self.pos < self.slice.len() {
            Some(&self.slice[self.pos])
        } else {
            None
        }
    }
}

/// Combine a variable number of lists into a single list by following `sequence`.
///
/// `lists` is a slice of Vec<T> (you may pass a Vec<Vec<T>> as &lists).
/// `sequence` is a slice of indices: at each step it indicates which input list to draw the next element from.
/// The function returns an error if any requested stream is out of bounds or already exhausted.
///
/// Example:
/// let lists = vec![vec![1,2,3], vec![4,5], vec![6]];
/// let seq = vec![0,1,2,0,0,1];
/// combine_by_sequence(&lists, &seq) -> Ok(vec![1,4,6,2,3,5])
pub fn combine_by_sequence<T: Clone>(
    lists: &[Vec<T>],
    sequence: &[usize],
) -> Result<Vec<T>, String> {
    // Wrap input lists in streaming iterators.
    let mut streams: Vec<SliceStream<T>> = lists.iter().map(|v| SliceStream::new(v)).collect();

    let mut out = Vec::with_capacity(sequence.len());

    for (pos, &idx) in sequence.iter().enumerate() {
        if idx >= streams.len() {
            return Err(format!(
                "sequence contains index {} at position {}, but there are {} streams",
                idx,
                pos,
                streams.len()
            ));
        }
        let stream = &mut streams[idx];
        match stream.get() {
            Some(item) => {
                out.push(item.clone());
                stream.advance();
            }
            None => {
                return Err(format!(
                    "stream {} exhausted when requested at sequence position {}",
                    idx, pos
                ));
            }
        }
    }

    Ok(out)
}

#[cfg(test)]
