    #[test]
    fn basic_combination() {
        let lists = vec![vec![1, 2, 3], vec![4, 5], vec![6]];
        let seq = vec![0, 1, 2, 0, 0, 1];
        let result = combine_by_sequence(&lists, &seq).unwrap();
        assert_eq!(result, vec![1, 4, 6, 2, 3, 5]);
    }

    #[test]
    fn error_on_exhausted_stream() {
        let lists = vec![vec![10], vec![20]];
        let seq = vec![0, 0]; // requests two elements from stream 0, but it only has 1
        assert!(combine_by_sequence(&lists, &seq).is_err());
