    let boundaries: Vec<NaiveDateTime> = lst0
        .iter()
        .map(|b| parse_datetime(b).expect("Failed to parse boundary"))
        .collect();

    // Validate boundaries are sorted
    for i in 1..boundaries.len() {
        assert!(
            boundaries[i] > boundaries[i - 1],
            "Boundaries must be sorted in chronological order"
        );
    }

    let mut result: HashMap<String, Vec<HashMap<String, String>>> = HashMap::new();

    // Initialize result with empty vectors for each interval
    for i in 0..boundaries.len() - 1 {
        let interval_label = format!("{}-{}", lst0[i], lst0[i + 1]);
        result.insert(interval_label, Vec::new());
    }

    // Add a catch-all for entries after the last boundary
    if !boundaries.is_empty() {
        let last_label = format!("{}-inf", lst0.last().unwrap());
        result.insert(last_label, Vec::new());
    }

    // Process each entry
    for entry in &df0 {
        if let Some(str0_value) = entry.get("str0") {
            let entry_datetime = parse_datetime(str0_value)
                .expect("Failed to parse entry datetime");

            // Find which interval this entry belongs to
            let mut assigned = false;

            for i in 0..boundaries.len() - 1 {
                if entry_datetime >= boundaries[i] && entry_datetime < boundaries[i + 1] {
                    let interval_label = format!("{}-{}", lst0[i], lst0[i + 1]);
                    if let Some(entries) = result.get_mut(&interval_label) {
                        entries.push(entry.clone());
                    }
                    assigned = true;
                    break;
                }
            }

            // If not assigned to any interval, put it in the catch-all
            if !assigned && !boundaries.is_empty() {
                let last_label = format!("{}-inf", lst0.last().unwrap());
                if let Some(entries) = result.get_mut(&last_label) {
                    entries.push(entry.clone());
                }
            }
        }
    }

    result
}

/// Helper function to parse a string into NaiveDateTime
/// Supports both date-only (YYYY-MM-DD) and datetime (YYYY-MM-DD HH:MM:SS) formats
fn parse_datetime(s: &str) -> Option<NaiveDateTime> {
    // Try parsing as full datetime first
    if let Ok(dt) = NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M:%S") {
        return Some(dt);
    }

    // Try parsing as date only (assume midnight)
    if let Ok(date) = NaiveDate::parse_from_str(s, "%Y-%m-%d") {
        return Some(date.and_hms_opt(0, 0, 0).unwrap());
    }

    None
}

