use chrono::{DateTime, Utc, NaiveDateTime};
use std::cmp::Ordering;

/// Segments entries in a DataFrame column into intervals defined by boundary values.
///
/// # Arguments
/// * `df0` - Vector of tuples containing column name and vector of string values
/// * `str0` - The name of the column to segment
/// * `lst0` - Vector of boundary values (as strings) that define interval boundaries
///
/// # Returns
/// A vector of interval labels indicating which interval each entry falls into
///
/// # Example
/// ```
/// let data = vec![("values".to_string(), vec!["5".to_string(), "15".to_string(), "25".to_string()])];
/// let boundaries = vec!["0".to_string(), "10".to_string(), "20".to_string(), "30".to_string()];
/// let result = segment_into_intervals(&data, "values", &boundaries);
/// // Returns: vec!["[0, 10)".to_string(), "[10, 20)".to_string(), "[20, 30)".to_string()]
/// ```
pub fn segment_into_intervals(
    df0: &Vec<(String, Vec<String>)>,
    str0: &str,
    lst0: &Vec<String>,
) -> Vec<String> {
    // Find the column with the matching name
    let column_data = df0
        .iter()
        .find(|(col_name, _)| col_name == str0)
        .map(|(_, data)| data)
        .expect("Column not found in dataframe");

    // Sort boundaries and convert to floats
    let mut boundaries: Vec<f64> = lst0
        .iter()
        .filter_map(|b| b.parse::<f64>().ok())
        .collect();
    boundaries.sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));

    // Segment each entry
    column_data
        .iter()
        .map(|entry| {
            let value = entry
                .parse::<f64>()
                .unwrap_or(f64::NEG_INFINITY);

            // Find which interval this value falls into
            for i in 0..boundaries.len() - 1 {
                if value >= boundaries[i] && value < boundaries[i + 1] {
                    return format!("[{}, {})", boundaries[i], boundaries[i + 1]);
                }
            }

            // If value is beyond the last boundary
            if value >= boundaries[boundaries.len() - 1] {
                return format!("[{}, ∞)", boundaries[boundaries.len() - 1]);
            }

            // If value is before the first boundary
            format!("(-∞, {})", boundaries[0])
        })
        .collect()
}

