# Rust Function to Convert Date Column

```rust
use time::format_description;
use time::Date;

/// Converts the 'Date' column of a dataset from string to native date-time values.
/// 
/// # Arguments
/// * `df0` - A mutable reference to a Vec of records (each record is a HashMap with string keys/values)
/// 
/// # Example
/// ```
/// use std::collections::HashMap;
/// 
/// let mut records = vec![
///     {
///         let mut map = HashMap::new();
///         map.insert("Date".to_string(), "25-12-2023".to_string());
///         map.insert("Value".to_string(), "100".to_string());
///         map
///     }
/// ];
/// 
/// convert_date_column(&mut records);
/// ```
pub fn convert_date_column(df0: &mut [std::collections::HashMap<String, String>]) -> Result<(), Box<dyn std::error::Error>> {
    // Define the date format pattern: "DD-MM-YYYY"
    let format = format_description::parse("[day]-[month]-[year]")?;

    for record in df0.iter_mut() {
        if let Some(date_str) = record.get("Date") {
            match Date::parse(date_str, &format) {
                Ok(parsed_date) => {
                    // Store the parsed date back as a string representation
                    // (since HashMap values are strings in this example)
                    record.insert("Date".to_string(), parsed_date.to_string());
                }
                Err(e) => {
                    eprintln!("Failed to parse date '{}': {}", date_str, e);
                    return Err(Box::new(e));
                }
            }
        }
    }

    Ok(())
}

// Alternative version that returns Result with parsed Date objects
pub fn convert_date_column_typed(
    date_strings: Vec<String>,
) -> Result<Vec<Date>, Box<dyn std::error::Error>> {
    let format = format_description::parse("[day]-[month]-[year]")?;

    date_strings
        .into_iter()
        .map(|date_str| {
            Date::parse(&date_str, &format)
                .map_err(|e| Box::new(e) as Box<dyn std::error::Error>)
        })
        .collect()
}

