use std::collections::HashSet;

use arrow::array::{ArrayRef, StringArray, UInt32Builder, new_empty_array};
use arrow::compute::take;
use arrow::datatypes::DataType;
use arrow::error::Result;
use arrow::record_batch::RecordBatch;

/// Return a RecordBatch containing only the rows from `df0` where the
/// Utf8 column `col_name` has a value contained in `lst0`.
///
/// - `df0` : input RecordBatch
/// - `col_name` : name of a Utf8 (string) column in `df0`
/// - `lst0` : slice of string-like values to test membership against
///
/// Returns an Arrow Result<RecordBatch>.
pub fn filter_record_batch_by_utf8_values(
    df0: &RecordBatch,
    col_name: &str,
    lst0: &[&str],
) -> Result<RecordBatch> {
    // find column index for the given name
    let col_index = df0.schema().index_of(col_name)?;

    // get the column and downcast to StringArray
    let col = df0.column(col_index);
    let string_col = col
        .as_any()
        .downcast_ref::<StringArray>()
        .ok_or_else(|| arrow::error::ArrowError::ComputeError(format!("column '{}' is not Utf8", col_name)))?;

    // build a HashSet for fast membership tests
    let set: HashSet<&str> = lst0.iter().cloned().collect();

    // collect matching row indices into a UInt32 array
    let mut indices_builder = UInt32Builder::new(df0.num_rows());
    for row_idx in 0..string_col.len() {
        if string_col.is_null(row_idx) {
            continue; // treat nulls as non-matching
        }
        let v = string_col.value(row_idx);
        if set.contains(v) {
            indices_builder.append_value(row_idx as u32)?;
        }
    }
    let indices = indices_builder.finish();

    // If no indices, return empty arrays for each column (preserve schema)
    let new_columns: Vec<ArrayRef> = if indices.len() == 0 {
        df0
            .schema()
            .fields()
            .iter()
            .map(|f| new_empty_array(f.data_type()).into())
            .collect()
    } else {
        // Use take on each column to produce filtered columns
        df0
            .columns()
            .iter()
            .map(|col| take(col.as_ref(), &indices, None).map(Arc::from))
            .collect::<Result<Vec<ArrayRef>>>()?
    };

    RecordBatch::try_new(df0.schema(), new_columns)
}
```

