    let max_len = std::cmp::max(lst0.len(), lst1.len());
    let lst0: Vec<String> = lst0.into_iter().chain(std::iter::repeat(String::new()).take(max_len - lst0.len())).collect();
    let lst1: Vec<String> = lst1.into_iter().chain(std::iter::repeat(String::new()).take(max_len - lst1.len())).collect();

    // Add rows to the table.
    for (elem0, elem1) in lst0.into_iter().zip(lst1.into_iter()) {
        table.add_row(Row::new(vec![
            Cell::new(&elem0),
            Cell::new(&elem1),
        ]));
    }

    table
}

