/// let order = vec![3, 1, 2];
/// reorder_by_values(&mut items, &order);
/// assert_eq!(items, vec!["b", "c", "a"]);
/// ```
pub fn reorder_by_values<T, U: Ord>(lst0: &mut [T], lst1: &[U]) {
    assert_eq!(lst0.len(), lst1.len(), "Both slices must have the same length");

    if lst0.len() <= 1 {
        return;
    }

    // Create indices and sort them based on the values in lst1
    let mut indices: Vec<usize> = (0..lst0.len()).collect();
    indices.sort_by_key(|&i| &lst1[i]);

    // Apply the permutation to lst0
    // We use a cycle-following approach to apply the permutation in-place
    let mut visited = vec![false; lst0.len()];

    for i in 0..lst0.len() {
        if visited[i] {
            continue;
        }

        // Start a new cycle
        let mut current = i;
        let mut temp: Option<T> = None;

        while !visited[current] {
            visited[current] = true;
            let next = indices[current];

            if next == current {
                // Element is already in correct position
                break;
            }

            // Swap elements
            if temp.is_none() {
                // Take the element at current position
                let mut ptr = lst0.as_mut_ptr();
                unsafe {
                    temp = Some(std::ptr::read(ptr.add(current)));
                }
            }

            // Move element from next position to current position
            let mut ptr = lst0.as_mut_ptr();
            unsafe {
                let next_element = std::ptr::read(ptr.add(next));
                std::ptr::write(ptr.add(current), next_element);
            }

            current = next;
        }

        // Place the saved element at the end of the cycle
        if let Some(value) = temp {
            let mut ptr = lst0.as_mut_ptr();
            unsafe {
                std::ptr::write(ptr.add(current), value);
            }
        }
    }
