use smartcore::numerics::basics::mean;
use smartcore::linalg::basic::matrix::Matrix;
use smartcore::linalg::basic::vector::Vector;

/// Replaces missing entries in a 2D table with the mean of their respective column.
///
/// # Arguments
///
/// * `table` - A 2D table where `NaN` represents missing values.
///
/// # Returns
///
/// A new 2D table where missing entries are replaced with column means.
fn replace_with_column_means(table: Matrix<f64>) -> Matrix<f64> {
    let (rows, cols) = table.shape();
    let mut result = table.clone();

    for col in 0..cols {
        // Filter out NaN values from the column
        let column: Vector<f64> = table.column(col).filter(|&x| !x.is_nan());

        // If the column is empty (all NaN), we cannot compute a mean, so skip it
        if column.len() == 0 {
            continue;
        }

        // Compute the mean of the non-NaN values in the column
        let mean = mean(&column);

        // Replace NaN values in the column with the computed mean
        for row in 0..rows {
            if result.get(row, col).is_nan() {
                result.set(row, col, mean);
            }
        }
    }

    result
}

