pub fn replace_missing_with_column_mean(data: &[Vec<f64>]) -> Vec<Vec<f64>> {
    if data.is_empty() || data[0].is_empty() {
        panic!("Input data cannot be empty");
    }

    let n_rows = data.len();
    let n_cols = data[0].len();

    // Verify all rows have the same length
    for (i, row) in data.iter().enumerate() {
        if row.len() != n_cols {
            panic!("Row {} has inconsistent length: expected {}, got {}", 
                   i, n_cols, row.len());
        }
    }

    // Create a DenseMatrix from the input data
    let matrix = DenseMatrix::from_2d_array(data);

    // Calculate column means, ignoring NaN values
    let mut column_means = vec![0.0_f64; n_cols];
    for col in 0..n_cols {
        let mut sum = 0.0_f64;
        let mut count = 0;

        for row in 0..n_rows {
            let value = matrix.get(row, col);
            if !value.is_nan() {
                sum += value;
                count += 1;
            }
        }

        if count == 0 {
            panic!("Column {} contains only NaN values, cannot compute mean", col);
        }

        column_means[col] = sum / count as f64;
