use itertools::Itertools;
use std::collections::HashSet;

fn remove_duplicate_rows<T: PartialEq + Clone>(
    table: Vec<Vec<T>>,
    cols: &[usize],
) -> Vec<Vec<T>> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    for row in table {
        // Create a key based on the specified columns
        let key: Vec<_> = cols.iter().filter_map(|&col| row.get(col)).collect();

        // If the key is unique, add the row to the result and mark the key as seen
        if seen.insert(key) {
            result.push(row);
        }
