```rust
use itertools::Itertools;
use std::collections::HashSet;

/// Removes rows from a table that contain duplicate values across specified columns.
///
/// # Arguments
/// * `table` - A vector of rows, where each row is a vector of values.
/// * `columns` - A vector of column indices to check for duplicates.
///
/// # Returns
/// A new table with rows that don't have duplicate values in the specified columns.
///
/// # Example
/// ```
/// use std::collections::HashSet;
///
/// let table = vec![
///     vec!["a", "1", "x"],
///     vec!["b", "2", "y"],
///     vec!["a", "3", "z"],  // This will be removed because "a" is duplicated in column 0
///     vec!["c", "4", "w"],
/// ];
/// let columns = vec![0];  // Check only the first column
///
/// let result = remove_duplicate_rows(table, columns);
/// assert_eq!(result.len(), 2);
/// ```
pub fn remove_duplicate_rows<T: std::hash::Hash + Eq + Clone>(
    table: Vec<Vec<T>>,
    columns: Vec<usize>,
) -> Vec<Vec<T>> {
    // Create a set to track seen values in the specified columns
    let mut seen = HashSet::new();

    // Process rows in reverse order to avoid index shifting issues
    let mut result = table
        .into_iter()
        .enumerate()
        .filter(|(_, row)| {
            // Create a key from the specified columns
            let key: Vec<_> = columns
                .iter()
                .filter_map(|&col| row.get(col).cloned())
                .collect();

            // Check if this key has been seen before
            let is_duplicate = seen.contains(&key);
            if !is_duplicate {
                seen.insert(key);
            }
            !is_duplicate
        })
        .map(|(_, row)| row)
        .collect();

    result
}

