```rust
use itertools::Itertools;
use std::hash::Hash;

/// Remove rows from `table` that are duplicates with respect to the columns in `cols`.
///
/// - `table` is a slice of rows; each row is a Vec<T>.
/// - `cols` is a slice of column indices to consider when checking duplicates.
/// - Keeps the first occurrence of each distinct key (values at the given columns).
///
/// Returns Err if any column index is out of bounds for any row.
pub fn remove_duplicate_rows_by_columns<T>(
    table: &[Vec<T>],
    cols: &[usize],
) -> Result<Vec<Vec<T>>, String>
where
    T: Clone + Eq + Hash,
{
    // Validate that for each row, all requested column indices are valid.
    for (r_idx, row) in table.iter().enumerate() {
        for &c in cols {
            if c >= row.len() {
                return Err(format!("Column index {} out of bounds for row {}", c, r_idx));
            }
        }
    }

    // Use itertools::unique_by to keep first row for each distinct key (values at cols).
    let result = table
        .iter()
        .cloned() // operate on owned rows
        .unique_by(|row: Vec<T>| {
            cols.iter().map(|&i| row[i].clone()).collect::<Vec<T>>()
        })
        .collect::<Vec<Vec<T>>>();

    Ok(result)
}

fn main() {
    // Example usage with String cells
    let table = vec![
        vec!["id1".to_string(), "Alice".to_string(), "NY".to_string()],
        vec!["id2".to_string(), "Bob".to_string(), "CA".to_string()],
        vec!["id3".to_string(), "Alice".to_string(), "NY".to_string()], // duplicate on cols [1,2]
        vec!["id4".to_string(), "Alice".to_string(), "TX".to_string()],
    ];

    // Remove rows that duplicate values across columns 1 (name) and 2 (state)
    let deduped = remove_duplicate_rows_by_columns(&table, &[1, 2]).unwrap();

    for row in deduped {
        println!("{:?}", row);
    }
    // Output will keep the first occurrence of ("Alice","NY") and drop the later duplicate:
    // ["id1", "Alice", "NY"]
    // ["id2", "Bob", "CA"]
    // ["id4", "Alice", "TX"]
}
```

Notes:
- If `cols` is empty, all rows will be considered duplicates of each other (empty key), so only the first row is kept.
- The function preserves the original row ordering (keeps first occurrences).

