/// - Date parsing fails
/// - Date formatting fails
pub fn reformat_datetime_column(
    df: DataFrame,
    col_name: &str,
    format_str: &str,
) -> Result<DataFrame, DateReformatError> {
    // Check if column exists
    if !df.column_names().contains(&col_name.to_string()) {
        return Err(DateReformatError::ColumnNotFound(col_name.to_string()));
    }

    let mut df = df.clone();

    // Get the original column
    let original_series = df
        .column(col_name)
        .ok_or_else(|| DateReformatError::ColumnNotFound(col_name.to_string()))?;

    // Check if the column is a date/time type
    let original_dtype = original_series.dtype();
    if !matches!(
        original_dtype,
