    ) {
        return Err(DateReformatError::TypeMismatch(original_dtype.to_string()));
    }

    // Convert to Series<DateTime<Utc>> for processing
    let datetime_series: Series<DateTime<Utc>> = match original_dtype {
        DataType::Datetime(_) => original_series
            .as_any()
            .downcast_ref::<Series<DateTime<Utc>>>()
            .ok_or_else(|| DateReformatError::TypeMismatch(original_dtype.to_string()))?
            .clone(),
        DataType::Timestamp(_) => original_series
            .as_any()
            .downcast_ref::<Series<DateTime<Utc>>>()
            .ok_or_else(|| DateReformatError::TypeMismatch(original_dtype.to_string()))?
            .clone(),
        _ => return Err(DateReformatError::TypeMismatch(original_dtype.to_string())),
