/// 
/// # Arguments
/// * `input_table` - A slice of tuples where each tuple contains (col0, col1)
///   - col0: A string slice representing a date in "YYYY-MM-DD" format
///   - col1: A string slice representing a time in "HH:MM:SS" format
///
/// # Returns
/// * `Result<Vec<PrimitiveDateTime>, String>` - A vector of combined date-time values or an error message
///
/// # Example
/// ```
/// use time::macros::datetime;
/// 
/// let input = vec![
///     ("2024-01-15", "14:30:00"),
///     ("2024-03-20", "09:15:45"),
/// ];
/// 
/// let result = combine_date_time(&input).unwrap();
/// assert_eq!(result[0], datetime!(2024-01-15 14:30:00));
/// assert_eq!(result[1], datetime!(2024-03-20 09:15:45));
/// ```
pub fn combine_date_time(
    input_table: &[(&str, &str)]
) -> Result<Vec<PrimitiveDateTime>, String> {
    let mut result = Vec::with_capacity(input_table.len());

    for (row_idx, (date_str, time_str)) in input_table.iter().enumerate() {
        // Parse the date string (expected format: "YYYY-MM-DD")
        let date_parts: Vec<&str> = date_str.split('-').collect();
        if date_parts.len() != 3 {
            return Err(format!("Row {}: Invalid date format '{}'. Expected YYYY-MM-DD", row_idx, date_str));
        }

        let year: i32 = date_parts[0].parse()
            .map_err(|_| format!("Row {}: Invalid year in date '{}'", row_idx, date_str))?;
        let month: u8 = date_parts[1].parse()
            .map_err(|_| format!("Row {}: Invalid month in date '{}'", row_idx, date_str))?;
        let day: u8 = date_parts[2].parse()
            .map_err(|_| format!("Row {}: Invalid day in date '{}'", row_idx, date_str))?;

        let month = Month::try_from(month)
            .map_err(|_| format!("Row {}: Invalid month value {} in date '{}'", row_idx, month, date_str))?;

        let date = Date::from_calendar_date(year, month, day)
            .map_err(|_| format!("Row {}: Invalid calendar date '{}'", row_idx, date_str))?;

        // Parse the time string (expected format: "HH:MM:SS")
        let time_parts: Vec<&str> = time_str.split(':').collect();
        if time_parts.len() != 3 {
            return Err(format!("Row {}: Invalid time format '{}'. Expected HH:MM:SS", row_idx, time_str));
