        let time = Time::from_hms(hour, minute, second)
            .map_err(|_| format!("Row {}: Invalid time '{}'", row_idx, time_str))?;

        // Combine date and time into a PrimitiveDateTime
        result.push(PrimitiveDateTime::new(date, time));
    }

