```rust
/// Split `input` on commas, except commas that appear between paired double quotes.
///
/// Rules:
/// - Commas outside quotes separate segments.
/// - A double quote toggles "in-quote" state, unless it is a doubled quote ("")
///   inside a quoted region, which is interpreted as an escaped quote and becomes a single `"`
///   in the output.
/// - Outer quotes are removed for quoted fields.
/// - Other characters are preserved exactly (including spaces outside quotes).
///
/// Examples:
/// - `a,b,"c,d",e` -> ["a", "b", "c,d", "e"]
/// - `"a""b",c` -> [r#"a"b"#, "c"]
pub fn split_ignoring_quoted_commas(input: &str) -> Vec<String> {
    let mut segments = Vec::new();
    let mut cur = String::new();
    let mut chars = input.chars().peekable();
    let mut in_quotes = false;

    while let Some(ch) = chars.next() {
        match ch {
            '"' => {
                if in_quotes {
                    // If next is also a quote, it's an escaped quote -> append one quote and consume the second.
                    if let Some('"') = chars.peek() {
                        chars.next(); // consume the escaped quote
                        cur.push('"');
                    } else {
                        // Closing quote: do not append to output (outer quotes are removed)
                        in_quotes = false;
                    }
                } else {
                    // Opening quote: do not append to output (outer quotes are removed)
                    in_quotes = true;
                }
            }
            ',' => {
                if in_quotes {
                    // Comma inside quotes is part of the field.
                    cur.push(',');
                } else {
                    // Comma outside quotes -> end of segment.
                    segments.push(cur);
                    cur = String::new();
                }
            }
            _ => cur.push(ch),
        }
    }

    // Push last field (even if empty)
    segments.push(cur);
    segments
}

