/// Returns the indices that would sort `arr0` in descending order.
///
/// # Arguments
/// * `arr0` - A one-dimensional array to be sorted in descending order.
///
/// # Returns
/// A vector of indices that, when used to reorder `arr0`, would sort it in descending order.
fn descending_sort_indices<T: PartialOrd + Copy>(arr0: &[T]) -> Vec<usize> {
    // Create a vector of indices (0..arr0.len())
    let mut indices: Vec<usize> = (0..arr0.len()).collect();

