use hashbrown::HashMap;

#[derive(Debug, Clone)]
struct Record {
    a: String,
    b: i32,
}

fn remove_duplicates(records: Vec<Record>) -> Vec<Record> {
    let mut map: HashMap<String, Record> = HashMap::new();

    for record in records {
        map.entry(record.a.clone())
            .and_modify(|existing_record| {
                if record.b > existing_record.b {
                    *existing_record = record.clone(); // Update to the record with the higher 'b'
                }
            })
            .or_insert(record);
    }

    map.into_iter()
        .map(|(_, record)| record)
        .collect()
}

fn main() {
    let records = vec![
        Record { a: String::from("A1"), b: 1 },
        Record { a: String::from("A1"), b: 3 },
        Record { a: String::from("A2"), b: 2 },
        Record { a: String::from("A2"), b: 4 },
        Record { a: String::from("A3"), b: 5 },
    ];

