    let dfa = DFA::new(r"([A-Z])\1*").unwrap();

    let mut result = String::new();
    let mut last_end = 0;

    // Find all matches of consecutive uppercase runs
    let input = Input::new(text);
    let mut state = dfa.start_state(&input);

    for i in 0..text.len() {
        // Check if we're at the start of a match
        if dfa.is_match_state(state) {
            let match_len = dfa.match_len(&input, state);
            let start = i - match_len;
            let end = i;

            // Add any non-matching text before this match
            if start > last_end {
                result.push_str(&text[last_end..start]);
            }

            // Add the lowercase version of the first character in the run
            if let Some(c) = text[start..end].chars().next() {
