/// * `target_size` - The desired number of elements in each inner group
/// * `fill_element` - The element to append to groups that are shorter than target_size
///
/// # Panics
/// Panics if any inner ArrayVec doesn't have enough capacity to reach the target_size,
/// or if trying to pad a group that's already larger than target_size would exceed capacity.
///
/// # Example
/// ```
/// use arrayvec::ArrayVec;
///
/// let mut groups: [ArrayVec<i32, 5>; 3] = [
///     ArrayVec::from([1, 2]),
///     ArrayVec::from([3]),
///     ArrayVec::from([4, 5, 6]),
/// ];
///
/// pad_inner_groups(&mut groups, 5, 0);
///
/// assert_eq!(groups[0].len(), 5);
/// assert_eq!(groups[1].len(), 5);
/// assert_eq!(groups[2].len(), 5);
/// ```
fn pad_inner_groups<T: Clone, const INNER_CAP: usize>(
    nested: &mut [ArrayVec<T, INNER_CAP>],
    target_size: usize,
    fill_element: T,
) {
    for group in nested {
        // Only pad groups that are shorter than the target size
        if group.len() < target_size {
            let padding_needed = target_size - group.len();

            // Attempt to extend the group with the fill element
            for _ in 0..padding_needed {
                group.push(fill_element.clone());
            }
        }
    }
}

