use arrow2::array::{Array, PrimitiveArray, Utf8Array};
use arrow2::datatypes::{DataType, Field, Schema};
use arrow2::record_batch::RecordBatch;
use arrow2::compute::filter::filter;

fn remove_rows_and_reset_indices(df0: RecordBatch, var0: &str, var1: &str) -> Result<RecordBatch, Box<dyn std::error::Error>> {
    // Find the index of the column `var0`
    let col_index = df0.schema().fields.iter().position(|f| f.name() == var0)
        .ok_or_else(|| format!("Column '{}' not found", var0))?;

    // Ensure the column `var0` is of type Utf8
    let col_array = df0.column(col_index).as_any().downcast_ref::<Utf8Array<i32>>()
        .ok_or_else(|| format!("Column '{}' is not of type Utf8", var0))?;

    // Create a boolean array indicating which rows to keep
    let filter_mask = col_array.iter().map(|value| value.map_or(false, |v| v != var1)).collect::<PrimitiveArray<bool>>();

    // Filter the record batch based on the mask
    let filtered_columns = df0.columns().iter()
        .map(|col| filter(col, &filter_mask))
        .collect::<Result<Vec<_>, _>>()?;

    // Create a new schema (same as the original)
    let schema = df0.schema();

    // Create a new record batch with the filtered data
    let filtered_batch = RecordBatch::try_new(schema.clone(), filtered_columns)?;

    Ok(filtered_batch)
}

