use std::sync::Arc;

use arrow2::array::Array;
use arrow2::chunk::Chunk;
use arrow2::compute::comparison::eq_scalar;
use arrow2::compute::boolean::not;
use arrow2::compute::filter::filter as compute_filter;
use arrow2::error::Result;
use arrow2::scalar::Scalar;

/// Remove all rows from `df` where the value in column `col_index` equals `value`,
/// and return a new Chunk with the remaining rows (row indices implicitly reset).
///
/// - `df` is an arrow2 Chunk of boxed arrays (table-like columns).
/// - `col_index` selects the column to compare against `value`.
/// - `value` is an arrow2 Scalar (typed) to compare with.
///
/// Returns a new Chunk containing filtered columns.
pub fn remove_rows_eq_and_reset_indices(
    df: &Chunk<Box<dyn Array>>,
    col_index: usize,
    value: &Scalar,
) -> Result<Chunk<Box<dyn Array>>> {
    // bounds check
    if col_index >= df.arrays().len() {
        return Err(arrow2::error::Error::OutOfSpec(format!(
            "column index {} out of bounds ({} columns)",
            col_index,
            df.arrays().len()
        )));
    }

    // get the column to compare
    let cmp_col = &df.arrays()[col_index];

    // compute mask where cmp_col == value
    let eq_mask = eq_scalar(cmp_col.as_ref(), value)?;

    // invert mask to get rows we want to KEEP (not equal)
    let keep_mask = not(&eq_mask)?;

    // filter every column by keep_mask
    let mut new_cols: Vec<Box<dyn Array>> = Vec::with_capacity(df.arrays().len());
    for col in df.arrays() {
        let filtered = compute_filter(col.as_ref(), &keep_mask)?;
        new_cols.push(filtered);
    }

    Ok(Chunk::new(new_cols))
}
