/// Returns a list of positions where the elements of `lst0` are non-zero.
///
/// # Arguments
/// * `lst0` - A slice of f64 values (can be dense or sparse)
///
/// # Returns
/// A Vec of usize indices where the elements are non-zero.
pub fn find_non_zero_positions(lst0: &[f64]) -> Vec<usize> {
    // Convert the input slice into a SparseVector for processing
    let sparse_vec = SparseVector::from_dense(lst0);

    // Collect the indices where the values are non-zero
    let mut non_zero_indices = Vec::new();
    for (index, value) in sparse_vec.iter() {
        if value.abs() > f64::EPSILON { // Check for non-zero (accounting for floating-point precision)
            non_zero_indices.push(index);
        }
    }

    // Sort the indices (since SparseVector may not be in order)
    non_zero_indices.sort();

    non_zero_indices
}

