/// Return a sequence of indices at which elements of `lst0` are non-zero.
/// Indexing is 0-based.
/// 
/// This function accepts a SIRS `Value` that should be a sequence and returns
/// a SIRS `Value::Sequence` of integer indices.
pub fn nonzero_positions(lst0: Value) -> Value {
    // Expect the input to be a sequence; if not, return an empty sequence.
    let seq = match lst0 {
        Value::Sequence(s) => s,
        _ => return Value::Sequence(vec![]),
    };

    let mut out: Vec<Value> = Vec::new();

    for (i, v) in seq.into_iter().enumerate() {
        let is_nonzero = match v {
            Value::Int(n) => n != 0,
            Value::Float(f) => f != 0.0,
            Value::Bool(b) => b,                // true considered non-zero
            Value::Sequence(ref s) => !s.is_empty(), // non-empty sequence considered non-zero
            // For any other kind of value, treat it as non-zero
            _ => true,
        };

        if is_nonzero {
            out.push(Value::Int(i as i64));
        }
    }

    Value::Sequence(out)
}

