use intrusive_collections::linked_list::{LinkedList, Link};
use std::cmp::Ordering;

/// A wrapper around a LinkedList that maintains elements in sorted order
#[derive(Debug)]
struct SortedLinkedList<T> {
    list: LinkedList<T>,
    // We need to implement PartialOrd for T to maintain ordering
    // This is just a placeholder - you'll need to implement it for your type
    // or provide a custom comparator
}

impl<T: Ord> SortedLinkedList<T> {
    /// Creates a new empty sorted list
    pub fn new() -> Self {
        Self {
            list: LinkedList::new(),
        }
    }

    /// Inserts an element into the list while maintaining order
    pub fn insert(&mut self, value: T) {
        let mut current = self.list.head_mut();
        let mut prev = None;

        while let Some(node) = current {
            if value <= node.data() {
                // Insert before current node
                let mut new_node = LinkedList::new();
                new_node.push(value);
                if let Some(prev_node) = prev {
                    prev_node.insert_after(new_node);
                } else {
                    self.list.push_front(new_node);
                }
                return;
            }
            prev = Some(node);
            current = node.next();
        }

        // If we get here, we need to append to the end
        self.list.push_back(value);
    }

    /// Removes all elements that satisfy the predicate
    pub fn remove_if<F>(&mut self, predicate: F) -> Vec<T>
    where
        F: FnMut(&T) -> bool,
    {
        let mut removed = Vec::new();
        let mut current = self.list.head_mut();
        let mut prev = None;

        while let Some(node) = current {
            let node_data = node.data();
            if predicate(node_data) {
                // Remove this node
                if let Some(prev_node) = prev {
                    prev_node.remove(node);
                } else {
                    self.list.pop_front();
                }
                removed.push(node_data);
                current = prev.map(|n| n.next()).unwrap_or(None);
            } else {
                prev = Some(node);
                current = node.next();
            }
        }

        removed
    }

    /// Returns an iterator over the elements in sorted order
    pub fn iter(&self) -> impl Iterator<Item = &T> {
        self.list.iter()
    }
}

#[cfg(test)]
