```rust
use linfa::prelude::*;
use linfa_clustering::KMeans;
use ndarray::Array2;

/// Partitions a one-dimensional data sequence into k clusters using k-means algorithm.
/// 
/// # Arguments
/// * `arr0` - A slice of f64 values representing the one-dimensional data sequence
/// * `n_clusters` - The number of clusters to partition the data into
/// 
/// # Returns
/// A `Result` containing a vector of integer labels indicating each element's cluster assignment,
/// or an error if clustering fails
/// 
/// # Example
/// ```
/// let data = vec![1.0, 2.0, 8.0, 9.0, 10.0];
/// let labels = kmeans_clustering(&data, 2).unwrap();
/// // labels might be: [0, 0, 1, 1, 1]
/// ```
pub fn kmeans_clustering(arr0: &[f64], n_clusters: usize) -> Result<Vec<usize>, Box<dyn std::error::Error>> {
    // Validate input
    if arr0.is_empty() {
        return Err("Input array cannot be empty".into());
    }

    if n_clusters == 0 {
        return Err("Number of clusters must be greater than 0".into());
    }

    if n_clusters > arr0.len() {
        return Err("Number of clusters cannot exceed number of data points".into());
    }

    // Reshape 1D array into 2D array (required by linfa)
    // Each row represents one data point with one feature
    let data = Array2::from_shape_vec(
        (arr0.len(), 1),
        arr0.to_vec(),
    )?;

    // Create a DatasetBase from the array
    let dataset = DatasetBase::from(data);

    // Apply K-means clustering
    let model = KMeans::params(n_clusters)
        .max_n_iterations(100)
        .fit(&dataset)?;

    // Predict cluster assignments for all points
    let predictions = model.predict(&dataset);

    // Convert predictions to Vec<usize>
    let labels: Vec<usize> = predictions.iter().map(|&label| label as usize).collect();

    Ok(labels)
}

