# Rust Function to Calculate Time Difference in Hours and Minutes

```rust
use chrono::Duration;

fn calculate_time_difference(df0: &[(chrono::DateTime<chrono::Utc>, chrono::DateTime<chrono::Utc>)]) -> Vec<(u64, u64)> {
    df0.iter()
        .map(|(col0, col1)| {
            let diff = col1.signed_duration_since(*col0);

            let total_seconds = diff.num_seconds().abs() as u64;
            let hours = total_seconds / 3600;
            let minutes = (total_seconds % 3600) / 60;

            (hours, minutes)
        })
        .collect()
}

