use kido::{KdTree, KdPoint};

fn find_closest_point_index(lst0: &[f64], lst1: &[f64], var0: f64, var1: f64) -> Option<usize> {
    if lst0.len() != lst1.len() || lst0.is_empty() {
        return None;
    }

    // Create a vector of points from the given sequences
    let points: Vec<KdPoint<f64>> = lst0.iter().zip(lst1.iter())
        .map(|(&x, &y)| KdPoint::new(vec![x, y]))
        .collect();

    // Build the k-d tree
    let mut kd_tree = KdTree::default();
    for (i, point) in points.iter().enumerate() {
        kd_tree.add(i, point);
    }

    // Search for the nearest point
    let query_point = KdPoint::new(vec![var0, var1]);
    match kd_tree.nearest(&query_point) {
        Some((index, _)) => Some(index),
        None => None,
    }
}

