    let target_y = 3.5;

    match closest_point(&x_coords, &y_coords, target_x, target_y) {
        Some(idx) => println!("Closest point is at index {}: ({}, {})", 
            idx, x_coords.get(idx).unwrap(), y_coords.get(idx).unwrap()),
        None => println!("No points to compare"),
    }
}
