    group_by_col: &str,
    max_col: &str,
) -> Result<RecordBatch> {
    let group_by_array = batch
        .column(batch.schema().index_of(group_by_col)?)
        .as_any()
        .downcast_ref::<StringArray>()
        .ok_or_else(|| anyhow::anyhow!("Group by column must be a StringArray"))?;

