        Field::new(max_col, DataType::Float64, false),
    ]);

    let group_array = StringArray::from(keys);
    let max_val_array = Float64Array::from(max_values);

    let result_batch = RecordBatch::try_new(Arc::new(schema), vec![
        Arc::new(group_array) as Arc<dyn Array>,
        Arc::new(max_val_array) as Arc<dyn Array>,
