use arrow2::array::{PrimitiveArray, Utf8Array};
use arrow2::compute::sort::sort_to_indices;
use arrow2::datatypes::{DataType, Field, Schema};
use arrow2::record_batch::RecordBatch;
use arrow2::types::i32_type::I32Type;

fn group_by_max(
    batch: &RecordBatch,
    group_by_col: &str,
    max_col: &str,
) -> Result<RecordBatch, Box<dyn std::error::Error>> {
    // Get the index of the group_by column
    let group_by_index = batch.schema().index_of(group_by_col)?;
    // Get the index of the max_col column
    let max_col_index = batch.schema().index_of(max_col)?;

    // Ensure the max_col is a primitive type (e.g., i32)
    if !matches!(batch.column(max_col_index).data_type(), DataType::Int32) {
        return Err("max_col must be an Int32 type".into());
    }

    // Create a map to store the indices of the max rows for each group
    let mut group_max_indices = std::collections::HashMap::<String, usize>::new();

    // Iterate over the rows
    for i in 0..batch.num_rows() {
        // Get the group key
        let group_key = match batch.column(group_by_index) {
            array @ Utf8Array::<i32>::_ => array.value(i).to_string(),
            _ => return Err("group_by_col must be a Utf8 type".into()),
        };

        // Get the current max value for the group
        let current_max_value = match batch.column(max_col_index) {
            array @ PrimitiveArray::<I32Type>::_ => array.value(i),
            _ => unreachable!(),
        };

        // If the group doesn't exist or the current value is greater than the stored max, update the map
        if let Some(&max_index) = group_max_indices.get(&group_key) {
            let max_value = match batch.column(max_col_index) {
                array @ PrimitiveArray::<I32Type>::_ => array.value(max_index),
                _ => unreachable!(),
            };
            if current_max_value > max_value {
                group_max_indices.insert(group_key, i);
            }
        } else {
            group_max_indices.insert(group_key, i);
        }
    }

    // Collect the max rows for each group
    let max_row_indices: Vec<usize> = group_max_indices.into_values().collect();

    // Sort the indices to maintain the order of the original RecordBatch
    let sorted_indices = sort_to_indices(&PrimitiveArray::<I32Type>::from_iter_values(max_row_indices), None, true)?;

    // Create new columns for the result RecordBatch
    let mut new_columns = Vec::with_capacity(batch.columns().len());
    for (col_index, col) in batch.columns().iter().enumerate() {
        let mut values = Vec::with_capacity(sorted_indices.len());
        for &index in sorted_indices.iter() {
            values.push(col.value(index));
        }
        new_columns.push(values.into_arrow_array(col.data_type()));
    }

    // Create the result RecordBatch
    let result_batch = RecordBatch::try_new(batch.schema().clone(), new_columns)?;

    Ok(result_batch)
}

