                        e.insert(max_by_value);
                        max_indices.insert(group_key, i);
                    }
                    std::collections::hash_map::Entry::Occupied(mut e) => {
                        let current_max = e.get();
                        if max_by_value > *current_max {
                            e.insert(max_by_value);
                            max_indices.insert(group_key, i);
                        }
                    }
                }
            }
            None => {
