                "Max column is not Int64".to_string(),
            )
        })?;

    // HashMap to store the maximum value and row index for each group
    let mut group_max: HashMap<String, (i64, usize)> = HashMap::new();

    // Iterate through all rows
    for row_idx in 0..data.len() {
        let group_value = group_by_array.value(row_idx).to_string();
        let current_value = max_array.value(row_idx);

        // Update the maximum for this group if needed
        match group_max.get(&group_value) {
            Some(&(max_val, _)) if current_value <= max_val => {
                // Current value is not greater, skip
