                group_max.insert(group_value, (current_value, row_idx));
            }
        }
    }

    // Extract just the row indices
    let result: HashMap<String, usize> = group_max
        .into_iter()
        .map(|(group, (_, row_idx))| (group, row_idx))
        .collect();

    Ok(result)
