    let mut pairs: Vec<(K, &V)> = dict0.iter().map(|(k, v)| (k.clone(), v)).collect();

    // Sort by the value (ascending). Rust's sort is stable.
    pairs.sort_by(|a, b| a.1.cmp(b.1));

