/// Computes the dot product of two sequences by element-wise multiplication
/// followed by summation.
///
/// # Arguments
/// * `a` - First sequence of numbers
/// * `b` - Second sequence of numbers
///
/// # Returns
/// The sum of element-wise products, or 0 if sequences are empty
///
/// # Panics
/// Panics if sequences have different lengths
fn dot_product<T>(a: Vec<T>, b: Vec<T>) -> T
where
    T: std::ops::Mul<Output = T> + std::ops::Add<Output = T> + Default + Copy,
{
    assert_eq!(
        a.len(),
        b.len(),
        "Sequences must have the same length"
    );

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x * y)
        .fold(T::default(), |acc, product| acc + product)
}

// Alternative implementation using taster's iterator capabilities
fn dot_product_taster<T>(a: Vec<T>, b: Vec<T>) -> T
where
    T: std::ops::Mul<Output = T> + std::ops::Add<Output = T> + Default + Copy,
{
    assert_eq!(
        a.len(),
        b.len(),
        "Sequences must have the same length"
