struct TripleSequence<I>
where
    I: StreamingIterator,
{
    inner: I,
    buffer: [Option<I::Item>; 3],
    index: usize,
}

impl<I> TripleSequence<I>
where
    I: StreamingIterator,
    I::Item: Copy + std::ops::Add<isize, Output = I::Item> + std::ops::Sub<isize, Output = I::Item>,
{
    fn new(inner: I) -> Self {
        TripleSequence {
            inner,
            buffer: [None; 3],
            index: 0,
        }
    }
}

impl<I> StreamingIterator for TripleSequence<I>
where
    I: StreamingIterator,
    I::Item: Copy + std::ops::Add<isize, Output = I::Item> + std::ops::Sub<isize, Output = I::Item>,
{
    type Item = I::Item;

    fn advance(&mut self) {
        if self.index == 0 {
            self.inner.advance();
            if let Some(item) = self.inner.get() {
                self.buffer[0] = Some(*item - 1);
                self.buffer[1] = Some(*item);
                self.buffer[2] = Some(*item + 1);
            } else {
                self.buffer = [None; 3];
            }
        } else {
            self.index += 1;
            if self.index >= 3 {
                self.index = 0;
            }
        }
    }

    fn get(&self) -> Option<&Self::Item> {
        self.buffer[self.index].as_ref()
    }
}

