use streaming_iterator::StreamingIterator;

/// A streaming iterator that, for each input element `x`, emits `x-1`, `x`, `x+1`,
/// and then sets every alternate emitted element (indices 0,2,4,...) to zero.
struct TripleAlternateZero<I>
where
    I: Iterator<Item = i32>,
{
    iter: I,
    // current source value for the 3-emission group
    cur_val: i32,
    // which sub-value of the current group to emit next
    state: State,
    // index of next emission (used to determine alternate-zero)
    index: usize,
    // the last produced value for `get()`
    current: i32,
    // whether a current value is available (get returns Option<&Item>)
    has_current: bool,
}

#[derive(Copy, Clone, Debug)]
enum State {
    NeedNext,   // we need to pull the next element from the underlying iterator
    EmitMinus,  // will emit cur_val - 1
    EmitSelf,   // will emit cur_val
    EmitPlus,   // will emit cur_val + 1
    Done,
}

impl<I> TripleAlternateZero<I>
where
    I: Iterator<Item = i32>,
{
    fn new(iter: I) -> Self {
        TripleAlternateZero {
            iter,
            cur_val: 0,
            state: State::NeedNext,
            index: 0,
            current: 0,
            has_current: false,
        }
    }
}

impl<I> StreamingIterator for TripleAlternateZero<I>
where
    I: Iterator<Item = i32>,
{
    type Item = i32;

    // advance prepares the next item; get() will return Some(&item) if there is one.
    fn advance(&mut self) {
        // Ensure we have a group to emit from; if state is NeedNext, try to fetch one.
        if let State::NeedNext = self.state {
            match self.iter.next() {
                Some(v) => {
                    self.cur_val = v;
                    self.state = State::EmitMinus;
                }
                None => {
                    self.state = State::Done;
                    self.has_current = false;
                    return;
                }
            }
        }

        // Now produce value according to state and advance state for next time.
        let base_val = match self.state {
            State::EmitMinus => {
                self.state = State::EmitSelf;
                self.cur_val - 1
            }
            State::EmitSelf => {
                self.state = State::EmitPlus;
                self.cur_val
            }
            State::EmitPlus => {
                self.state = State::NeedNext;
                self.cur_val + 1
            }
            State::NeedNext | State::Done => {
                // Shouldn't happen because we handled NeedNext above, and Done is handled earlier.
                self.has_current = false;
                return;
            }
        };

        // Set every alternate element to zero: indices 0,2,4,... become 0.
        let out = if self.index % 2 == 0 { 0 } else { base_val };
        self.current = out;
        self.has_current = true;
        self.index += 1;
    }

    fn get(&self) -> Option<&Self::Item> {
        if self.has_current {
            Some(&self.current)
        } else {
            None
        }
    }
}

