use ahocorasick::AhoCorasick;

/// Replace the `nth` (1-based) whole-word occurrence of `needle` in `text` with `replacement`.
/// If `nth` == 0 or no such occurrence exists, returns a clone of `text`.
///
/// Word characters are considered: Unicode alphanumeric or underscore ('_').
pub fn replace_nth_occurrence(text: &str, needle: &str, replacement: &str, nth: usize) -> String {
    if nth == 0 || needle.is_empty() {
        return text.to_string();
    }

    let ac = AhoCorasick::new(&[needle]);
    let mut count = 0usize;
    let mut target_range: Option<(usize, usize)> = None;

    for mat in ac.find_iter(text) {
        let s = mat.start();
        let e = mat.end();

        // Determine previous char (if any) and next char (if any) to check word boundaries.
        let prev_char = text[..s].chars().rev().next();
        let next_char = text[e..].chars().next();

        let is_word_char = |c: Option<char>| -> bool {
            match c {
                Some(ch) => ch.is_alphanumeric() || ch == '_',
                None => false,
            }
        };

        let before_is_word = is_word_char(prev_char);
        let after_is_word = is_word_char(next_char);

        // whole word if no word-char immediately before and after
        if !before_is_word && !after_is_word {
            count += 1;
            if count == nth {
                target_range = Some((s, e));
                break;
            }
        }
    }

    if let Some((s, e)) = target_range {
        let mut out = String::with_capacity(text.len() - (e - s) + replacement.len());
        out.push_str(&text[..s]);
        out.push_str(replacement);
        out.push_str(&text[e..]);
        out
    } else {
        text.to_string()
    }
}

fn main() {
    let var0 = "foo bar foo_bar foo foo";
    let var1 = "foo";
    let var2 = "FOO";
    let var3 = 2usize;

    let result = replace_nth_occurrence(var0, var1, var2, var3);
    println!("{}", result);
    // With the whole-word rule, matches are: "foo" (index 0), "foo" (index at word before last)
    // Note "foo_bar" is not a whole-word "foo". For the example above the output will be:
    // "foo bar foo_bar FOO foo"
}
```

