        futures.push(ready(&list0[i] == &list1[i]));
    }

    let mut results = Vec::with_capacity(min_len);
    while let Some(result) = futures.next().await {
        results.push(result);
    }

    results
}

// Synchronous wrapper for convenience
pub fn compare_lists_sync<T: PartialEq + Send + 'static>(
    list0: &[T],
    list1: &[T],
) -> Vec<bool>
where
    T: Clone,
{
    // For synchronous use, we can use a simple iterator approach
    // since parallel execution doesn't provide benefits in sync context
    let min_len = std::cmp::min(list0.len(), list1.len());

    list0.iter()
        .zip(list1.iter())
        .take(min_len)
        .map(|(a, b)| a == b)
        .collect()
}

