///
/// Elements not present in `lst1` are appended after matched elements in their original relative order.
///
/// Complexity: expected O(len(lst1) + len(lst0))
pub fn reorder_by_reference<T>(lst0: Vec<T>, lst1: &[T]) -> Vec<T>
where
    T: Eq + Hash + Clone,
{
    // Build map from value -> index in lst1. Reserve capacity to avoid reallocation
    let mut index_of = HashMap::with_capacity(lst1.len());
    for (i, item) in lst1.iter().enumerate() {
        // If there are duplicate keys in lst1, the first occurrence is used.
        index_of.entry(item.clone()).or_insert(i);
    }

    // Pair each element of lst0 with its rank (index in lst1 if present, else usize::MAX)
    // and its original position so we can keep relative order for ties (and unmatched).
    let mut paired: Vec<(usize, usize, T)> = Vec::with_capacity(lst0.len());
    for (orig_pos, item) in lst0.into_iter().enumerate() {
        let rank = index_of.get(&item).copied().unwrap_or(usize::MAX);
        paired.push((rank, orig_pos, item));
    }

    // Sort by rank, tie-breaking by original position to keep relative order stable.
    paired.sort_unstable_by(|a, b| match a.0.cmp(&b.0) {
        std::cmp::Ordering::Equal => a.1.cmp(&b.1),
        other => other,
    });

    // Extract reordered values
    paired.into_iter().map(|(_, _, v)| v).collect()
}

