    // Using FxHashMap for faster hashing (optimized for integer-like keys)
    let position_map: FxHashMap<&T, usize> = lst1
        .iter()
        .enumerate()
        .map(|(i, item)| (item, i))
        .collect();

    // Separate elements into those found in lst1 and those not found
    let mut found: Vec<(&T, usize)> = Vec::new();
    let mut not_found: Vec<&T> = Vec::new();

    for item in lst0 {
