use rustc_hash::FxHashMap;

/// Reorders elements of `lst0` according to the order defined in the sorted `lst1`.
/// 
/// # Arguments
/// * `lst0` - The list to be reordered
/// * `lst1` - The sorted reference list defining the desired order
///
/// # Returns
