/// let lst1 = vec![1, 2, 3];
/// let result = reorder_by_reference(lst0, &lst1);
/// assert_eq!(result, vec![1, 1, 2, 3, 3]);
/// ```
fn reorder_by_reference<T: Eq + std::hash::Hash + Clone>(
    lst0: Vec<T>,
    lst1: &[T],
) -> Vec<T> {
    // Build a hash map to count occurrences of each element in lst0
    let mut element_counts: FxHashMap<T, Vec<T>> = FxHashMap::default();

    for item in lst0 {
        element_counts.entry(item.clone())
            .or_insert_with(Vec::new)
            .push(item);
    }

    let mut result = Vec::with_capacity(lst0.len());

    // Iterate through lst1 and collect elements in order
    for reference_item in lst1 {
        if let Some(items) = element_counts.get_mut(reference_item) {
            // Pop items from the back (efficient) and append to result
            while let Some(item) = items.pop() {
                result.push(item);
            }
        }
    }

    // Add any remaining elements not found in lst1
    for (_, mut items) in element_counts {
        while let Some(item) = items.pop() {
            result.push(item);
        }
    }

    result
}

