use fshash::FxHashSet;

/// Returns the common elements between two lists (intersection)
///
/// # Arguments
/// * `lst0` - First input list (Vec<T>)
/// * `lst1` - Second input list (Vec<T>)
///
/// # Returns
/// A new Vec containing elements present in both input lists
///
/// # Examples
/// ```
/// let lst0 = vec![1, 2, 3, 4, 5];
/// let lst1 = vec![4, 5, 6, 7, 8];
/// let common = find_common_elements(&lst0, &lst1);
/// assert_eq!(common, vec![4, 5]);
/// ```
pub fn find_common_elements<T: std::hash::Hash + Eq + Clone>(lst0: &[T], lst1: &[T]) -> Vec<T> {
    // Create a hash set from the first list for O(1) lookups
    let set0: FxHashSet<_> = lst0.iter().cloned().collect();

    // Collect elements from the second list that are in the first set
    lst1.iter()
        .filter(|x| set0.contains(x))
        .cloned()
        .collect()
}
```

