use rusqlite::{params, Connection, OptionalExtension, Result, ToSql};
use regex::Regex;

/// Sum the values of `column` in `table` for all rows matching `filter_expr`.
///
/// - `conn`: open rusqlite::Connection
/// - `table`: table name (validated: [A-Za-z_][A-Za-z0-9_]*)
/// - `column`: column name (validated)
/// - `filter_expr`: SQL fragment for WHERE (e.g. "age > ? AND name = ?")
/// - `params`: slice of &dyn ToSql values corresponding to placeholders in `filter_expr`
///
/// Returns Ok(Some(sum)) when there are matching rows, Ok(None) if SUM is NULL (no rows), or Err on DB error.
pub fn sum_column_with_filter(
    conn: &Connection,
    table: &str,
    column: &str,
    filter_expr: &str,
    params: &[&dyn ToSql],
) -> Result<Option<f64>> {
    // Validate identifiers to avoid injection via table/column names.
    // Identifiers are restricted to typical SQL identifier characters.
    let ident_re = Regex::new(r"^[A-Za-z_][A-Za-z0-9_]*$").expect("valid regex");
    if !ident_re.is_match(table) || !ident_re.is_match(column) {
        return Err(rusqlite::Error::InvalidParameterName(
            "invalid table or column name".into(),
        ));
    }

    // Build SQL using validated identifiers. Filter expression may contain `?` placeholders.
    let sql = format!("SELECT SUM({}) FROM {} WHERE {}", column, table, filter_expr);

    let mut stmt = conn.prepare(&sql)?;
    // Use OptionalExtension to allow mapping SQL NULL -> None
    let sum_opt: Option<f64> = stmt.query_row(params, |row| row.get(0)).optional()?;
    Ok(sum_opt)
}

fn main() -> Result<()> {
    // Example usage: create an in-memory DB and table, insert some rows, then compute sums.
    let conn = Connection::open_in_memory()?;

    conn.execute(
        "CREATE TABLE items (id INTEGER PRIMARY KEY, category TEXT NOT NULL, value REAL NOT NULL)",
        [],
    )?;

