/// Sorts a collection of records (IndexMap) according to the order defined by a reference sequence.
/// Each record's value at key `var0` determines its sort position based on where that value appears in `lst0`.
///
/// # Arguments
/// * `dict0` - An IndexMap of records to be sorted
/// * `lst0` - A reference sequence defining the desired order
/// * `var0` - The key in each record whose value determines sort position
///
/// # Returns
/// A new IndexMap with records sorted according to the order in `lst0`
///
/// # Panics
/// Will panic if a record's value at `var0` is not found in `lst0`
pub fn sort_by_reference<K, V, T>(
    dict0: IndexMap<K, IndexMap<String, T>>,
    lst0: &[T],
    var0: &str,
) -> IndexMap<K, IndexMap<String, T>>
where
    K: std::hash::Hash + Eq + Clone,
    T: std::hash::Hash + Eq + Clone + std::fmt::Debug,
{
    // Create a lookup map for positions in lst0
    let position_map: std::collections::HashMap<&T, usize> = lst0
        .iter()
        .enumerate()
        .map(|(i, val)| (val, i))
        .collect();

    // Convert dict0 to a Vec for sorting
    let mut sorted_records: Vec<(K, IndexMap<String, T>)> = dict0.into_iter().collect();

    // Sort based on position in lst0
    sorted_records.sort_by(|(_, record_a), (_, record_b)| {
        let val_a = record_a
            .get(var0)
            .expect("Record missing key var0");
        let val_b = record_b
            .get(var0)
            .expect("Record missing key var0");

        let pos_a = position_map
            .get(val_a)
            .unwrap_or_else(|| panic!("Value {:?} not found in lst0", val_a));
        let pos_b = position_map
            .get(val_b)
            .unwrap_or_else(|| panic!("Value {:?} not found in lst0", val_b));

        pos_a.cmp(pos_b)
    });

    // Convert back to IndexMap
    sorted_records.into_iter().collect()
