/// Sorts a collection of records (IndexMap) according to the order defined by a reference sequence.
/// 
/// # Arguments
/// * `dict0` - A mutable IndexMap where each value is itself a map/dict containing the key `var0`
/// * `lst0` - A reference sequence that defines the desired sort order
/// * `var0` - The key to look up in each record that determines its sort position
///
/// # Example
/// ```
/// use indexmap::IndexMap;
///
/// let mut dict0 = IndexMap::new();
/// let mut record1 = IndexMap::new();
/// record1.insert("color", "blue");
/// dict0.insert("item1", record1);
///
/// let mut record2 = IndexMap::new();
/// record2.insert("color", "red");
/// dict0.insert("item2", record2);
///
/// let lst0 = vec!["red", "blue"];
/// sort_by_reference_sequence(&mut dict0, &lst0, "color");
/// ```
fn sort_by_reference_sequence<K, V>(
    dict0: &mut IndexMap<K, IndexMap<String, V>>,
    lst0: &[V],
    var0: &str,
) where
    K: Clone + std::cmp::Eq + std::hash::Hash,
    V: Clone + PartialEq,
{
    // Create a mapping of values to their position in lst0
    let position_map: IndexMap<&V, usize> = lst0
        .iter()
        .enumerate()
        .map(|(idx, val)| (val, idx))
        .collect();

    // Sort the dictionary by the position of the var0 value in lst0
    dict0.sort_by(|_key_a, record_a, _key_b, record_b| {
        let val_a = record_a.get(var0);
        let val_b = record_b.get(var0);

        match (val_a, val_b) {
            (Some(a), Some(b)) => {
                let pos_a = position_map.get(a).copied().unwrap_or(usize::MAX);
                let pos_b = position_map.get(b).copied().unwrap_or(usize::MAX);
                pos_a.cmp(&pos_b)
            }
            (Some(_), None) => std::cmp::Ordering::Less,
            (None, Some(_)) => std::cmp::Ordering::Greater,
            (None, None) => std::cmp::Ordering::Equal,
        }
    });
}

