use indexmap::IndexMap;

fn transform_to_dict<T: ToString>(df0: Vec<Vec<T>>, orientation: &str) -> IndexMap<String, Vec<T>> {
    let mut dict = IndexMap::new();

    // Check the orientation and transform accordingly
    if orientation == "row" {
        // Convert each row into a key-value pair
        for (i, row) in df0.iter().enumerate() {
            let key = format!("row_{}", i);
            dict.insert(key, row.clone()); // Clone the row onto the map with the key
        }
    } else if orientation == "column" {
        // Convert each column into a key-value pair
        if !df0.is_empty() {
            let column_count = df0[0].len();
            for i in 0..column_count {
                let key = format!("column_{}", i);
                let column_values: Vec<T> = df0.iter().filter_map(|row| row.get(i).cloned()).collect();
                dict.insert(key, column_values);
            }
        }
    } else {
        panic!("Invalid orientation specified. Use 'row' or 'column'.");
    }

    dict
}

fn main() {
    let data = vec![
        vec!["A", "B", "C"],
        vec!["D", "E", "F"],
        vec!["G", "H", "I"],
    ];

    let row_dict = transform_to_dict(data.clone(), "row");
    println!("Row Dictionary: {:?}", row_dict);

    let column_dict = transform_to_dict(data, "column");
    println!("Column Dictionary: {:?}", column_dict);
}
