use indexmap::IndexMap;

/// Orientation for transformation.
#[derive(Debug, Clone, Copy)]
pub enum Orientation {
    /// Produce a map of row-index -> { column_name -> value }.
    Rows,
    /// Produce a map of column_name -> Vec<value>.
    Columns,
}

impl Orientation {
    /// Parse a string into Orientation. Accepts common variants.
    pub fn from_str(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "rows" | "row" | "records" | "records_rows" => Some(Orientation::Rows),
            "columns" | "cols" | "columns_map" => Some(Orientation::Columns),
            _ => None,
        }
    }
}

/// Result type: either rows-oriented or columns-oriented representation.
pub enum TransformResult {
    Rows(IndexMap<usize, IndexMap<String, String>>),
    Columns(IndexMap<String, Vec<String>>),
}

/// Transform a 2D dataset `df0` into a dictionary according to orientation `var0`.
///
/// - `df0` is expected as a vector of rows, where the first row is the header (column names).
///   Each row is a Vec<String>.
/// - `var0` is a string describing orientation, e.g. "rows" or "columns".
/// - Returns `TransformResult::Rows` where the outer map keys are 0-based row indices (for data rows,
///   i.e., excluding the header) and each inner map maps column name -> cell value.
/// - Or returns `TransformResult::Columns` mapping column name -> vector of column values (in
///   original order, excluding the header).
///
/// Example:
/// let df = vec![
///   vec!["id".into(), "name".into(), "age".into()],
///   vec!["1".into(), "Alice".into(), "30".into()],
///   vec!["2".into(), "Bob".into(), "25".into()],
/// ];
/// let res = transform_df(&df, "rows").unwrap();
pub fn transform_df(
    df0: &[Vec<String>],
    var0: &str,
) -> Result<TransformResult, String> {
    let orientation =
        Orientation::from_str(var0).ok_or_else(|| format!("unknown orientation: {}", var0))?;

    if df0.is_empty() {
        return Err("df0 is empty; expected at least a header row".into());
    }

    let header = &df0[0];
    if header.is_empty() {
        return Err("header (first row) is empty; expected column names".into());
    }

    match orientation {
        Orientation::Rows => {
            let mut out: IndexMap<usize, IndexMap<String, String>> = IndexMap::new();
            for (i, row) in df0.iter().enumerate().skip(1) {
                let mut row_map: IndexMap<String, String> = IndexMap::new();
                for (j, col_name) in header.iter().enumerate() {
                    let value = row.get(j).cloned().unwrap_or_default();
                    row_map.insert(col_name.clone(), value);
                }
                // use 0-based index for data rows; i - 1 if you prefer starting at 1 adjust as needed
                out.insert(i - 1, row_map);
            }
            Ok(TransformResult::Rows(out))
        }
        Orientation::Columns => {
            let mut out: IndexMap<String, Vec<String>> = IndexMap::new();
            // initialize vectors for each column
            for col_name in header {
                out.insert(col_name.clone(), Vec::new());
            }
            // collect values
            for row in df0.iter().enumerate().skip(1).map(|(_, r)| r) {
                for (j, col_name) in header.iter().enumerate() {
                    let value = row.get(j).cloned().unwrap_or_default();
                    // Safe unwrap because we inserted all column names above
                    out.get_mut(col_name).unwrap().push(value);
                }
            }
            Ok(TransformResult::Columns(out))
        }
    }
}
