use tokenizers::Tokenizer;

fn extract_context_words(text: &str, search_term: &str, var2: usize) -> (Option<String>, Vec<Option<String>>, Option<String>) {
    // Tokenize the input text
    let tokenizer = Tokenizer::from_pretrained("bert-base-uncased", None).unwrap();
    let tokenized = tokenizer.encode(text, None).unwrap();

    // Get the tokenized string and find the index of the search term
    let tokens: Vec<&str> = tokenized.get_tokens().iter().map(|t| t.as_str()).collect();

    let search_term_indices: Vec<usize> = tokens.iter().enumerate()
        .filter_map(|(i, &token)| {
            if token == search_term {
                Some(i)
            } else {
                None
            }
        })
        .collect();

    // Prepare results
    let mut before: Vec<Option<String>> = Vec::new();
    let mut after: Vec<Option<String>> = Vec::new();

    for index in search_term_indices {
        // Collect words before the search term
        let left_start = if index >= var2 { index - var2 } else { 0 };
        let left_end = index;
        let before_words = tokens[left_start..left_end].iter()
            .map(|&word| Some(word.to_string()))
            .collect::<Vec<_>>();

        before.push(Some(search_term.to_string()));
        before.extend(before_words);

        // Collect words after the search term
        let right_start = index + 1;
        let right_end = (index + 1 + var2).min(tokens.len());

        let after_words = tokens[right_start..right_end].iter()
            .map(|&word| Some(word.to_string()))
            .collect::<Vec<_>>();

        after.push(after_words);
