/// 
/// # Returns
/// * `Result<(f64, f64), PolarsError>` - A tuple containing (mean_row_index, mean_col_index)
///   or an error if the DataFrame is empty or contains no non-zero values
pub fn mean_nonzero_indices(df: &DataFrame) -> Result<(f64, f64), PolarsError> {
    let shape = df.shape();
    let n_rows = shape.0;
    let n_cols = shape.1;

    if n_rows == 0 || n_cols == 0 {
        return Err(PolarsError::ComputeError(
            "DataFrame is empty".into()
        ));
    }

    let mut row_indices: Vec<f64> = Vec::new();
    let mut col_indices: Vec<f64> = Vec::new();

    // Iterate through each column
    for col_idx in 0..n_cols {
        let series = &df[col_idx];

        // Handle different numeric types
        match series.dtype() {
            DataType::Int32 => {
                let arr = series.i32().unwrap();
                for row_idx in 0..n_rows {
                    if let Some(val) = arr.get(row_idx) {
                        if val != 0 {
                            row_indices.push(row_idx as f64);
                            col_indices.push(col_idx as f64);
                        }
                    }
                }
            },
            DataType::Int64 => {
                let arr = series.i64().unwrap();
                for row_idx in 0..n_rows {
                    if let Some(val) = arr.get(row_idx) {
                        if val != 0 {
                            row_indices.push(row_idx as f64);
                            col_indices.push(col_idx as f64);
