            DataType::Float64 => {
                let arr = series.f64().unwrap();
                for row_idx in 0..n_rows {
                    if let Some(val) = arr.get(row_idx) {
                        if val != 0.0 {
                            row_indices.push(row_idx as f64);
                            col_indices.push(col_idx as f64);
                        }
                    }
                }
            },
            _ => {
                return Err(PolarsError::ComputeError(
                    format!("Unsupported data type: {:?}", series.dtype()).into()
                ));
            }
        }
    }

    if row_indices.is_empty() {
        return Err(PolarsError::ComputeError(
            "No non-zero values found in DataFrame".into()
