/// return them as a DVector. If the matrix has zero columns, returns an empty DVector.
fn first_elements<T: Scalar + Clone>(mat: &DMatrix<T>) -> DVector<T> {
    if mat.ncols() == 0 {
        DVector::from_vec(Vec::new())
    } else {
        mat.column(0).into_owned()
    }
