```rust
use std::hash::Hash;
use linked_hash_map::LinkedHashMap;

/// Sort a sequence of LinkedHashMap<K, V> by the value associated with `var0`.
///
/// - `lst0`: slice of maps to sort (maps are cloned into the result)
/// - `var0`: the key to use for comparison
/// - `ascending`: if true, sort ascending; if false, sort descending
///
/// Missing keys are treated as "greater than" present keys (i.e., placed at the end).
pub fn sort_maps_by_key<K, V>(
    lst0: &[LinkedHashMap<K, V>],
    var0: &K,
    ascending: bool,
) -> Vec<LinkedHashMap<K, V>>
where
    K: Eq + Hash + Clone,
    V: Ord + Clone,
{
    // Clone the input maps into a vector we can sort
    let mut items: Vec<LinkedHashMap<K, V>> = lst0.iter().cloned().collect();

    items.sort_by(|a, b| {
        let va = a.get(var0);
        let vb = b.get(var0);
        // Order present values by their Ord implementation.
        // Treat missing key as greater than present key so missing appear at end.
        match (va, vb) {
            (Some(x), Some(y)) => x.cmp(y),
            (None, Some(_)) => std::cmp::Ordering::Greater,
            (Some(_), None) => std::cmp::Ordering::Less,
            (None, None) => std::cmp::Ordering::Equal,
        }
    });

    if !ascending {
        items.reverse();
    }

    items
}

