pub fn filter_by_list(
    df0: Chunk<Box<dyn Array>>,
    var0: &str,
    lst0: Vec<String>,
    op0: &str,
) -> Result<Chunk<Box<dyn Array>>, Box<dyn std::error::Error>> {
    // Find the column index
    let col_index = df0
        .names()
        .position(|name| name == var0)
        .ok_or("Column not found")?;

    let column = df0.column(col_index);

    // Create a boolean mask for matching rows
    let mut mask = vec![false; column.len()];

    // Iterate through the column and check if each value is in the list
    for i in 0..column.len() {
        let value_in_list = match column.data_type() {
            DataType::Utf8 | DataType::LargeUtf8 => {
                let str_array = column
                    .as_any()
                    .downcast_ref::<arrow2::array::Utf8Array<i32>>()
                    .ok_or("Failed to cast to string array")?;

