                    .as_any()
                    .downcast_ref::<arrow2::array::PrimitiveArray<i32>>()
                    .ok_or("Failed to cast to int32 array")?;

                if let Some(val) = int_array.get(i) {
                    lst0.iter()
                        .any(|item| item.parse::<i32>().ok() == Some(val))
                }
                else {
                    false
                }
            }
            DataType::Int64 => {
                let int_array = column
                    .as_any()
                    .downcast_ref::<arrow2::array::PrimitiveArray<i64>>()
                    .ok_or("Failed to cast to int64 array")?;

                if let Some(val) = int_array.get(i) {
                    lst0.iter()
                        .any(|item| item.parse::<i64>().ok() == Some(val))
                } else {
                    false
                }
            }
            _ => return Err("Unsupported data type".into()),
        };

        // Apply the operation
