fn reorder_columns(df: &RecordBatch) -> Result<RecordBatch, Box<dyn std::error::Error>> {
    // Get the original column names and their corresponding indices
    let column_names: Vec<&String> = df.schema().fields().iter()
        .map(|field| field.name())
        .collect();

    // Create a sorted vector of the column names
    let mut sorted_column_names = column_names.clone();
    sorted_column_names.sort();

    // Create a HashMap to map original names to indices
    let name_to_index: HashMap<_, _> = column_names.iter()
        .enumerate()
        .map(|(i, &name)| (name, i))
        .collect();

    // Create a vector to hold the reordered columns
    let mut reordered_columns: Vec<Arc<dyn Array>> = Vec::new();

    // Loop through the sorted names and get corresponding columns
    for name in sorted_column_names {
        if let Some(&index) = name_to_index.get(name) {
            reordered_columns.push(df.column(index).clone());
        }
    }

    // Create a new RecordBatch with sorted columns
    let sorted_schema = Arc::new(Schema::new(sorted_column_names.iter()
        .map(|name| df.schema().field(name_to_index[name]).clone())
        .collect::<Vec<_>>()));

    let sorted_batch = RecordBatch::try_new(sorted_schema, reordered_columns)?;

    Ok(sorted_batch)
}

