/// Reorders the columns of `batch` so that column names are sorted alphabetically.
/// Returns a new RecordBatch with the same number of rows and same metadata.
///
/// Example:
/// let sorted = reorder_columns_alpha(&df0)?;
pub fn reorder_columns_alpha(batch: &RecordBatch) -> Result<RecordBatch> {
    // original schema and fields
    let schema = batch.schema();
    // collect (index, field) pairs so we can reorder columns by field name
    let mut index_field_pairs: Vec<(usize, arrow::datatypes::Field)> =
        schema.fields().iter().cloned().enumerate().collect();

    // sort by field name (lexicographic)
    index_field_pairs.sort_by(|a, b| a.1.name().cmp(b.1.name()));

    // build new schema preserving metadata
    let sorted_fields: Vec<arrow::datatypes::Field> =
        index_field_pairs.iter().map(|(_, f)| f.clone()).collect();
    let new_schema = Arc::new(Schema::new_with_metadata(sorted_fields, schema.metadata().clone()));

    // reorder columns to match sorted schema
    let cols = batch.columns();
    let new_columns: Vec<ArrayRef> = index_field_pairs
        .into_iter()
        .map(|(idx, _)| cols[idx].clone())
        .collect();

    RecordBatch::try_new(new_schema, new_columns)
}
```

