/// Sorts a 2D array by specified columns in ascending order.
///
/// # Arguments
/// * `data` - The input 2D array to be sorted
/// * `columns` - A vector of column indices to sort by (0-based)
///
/// # Returns
/// A new Array2 containing the sorted rows
///
/// # Example
/// ```
/// use ndarray::array;
///
/// let df = array![
///     [3, 1, 2],
///     [1, 2, 3],
///     [2, 3, 1],
/// ];
///
/// let sorted = sort_by_columns(&df, vec![0, 1]);
/// ```
fn sort_by_columns(data: &Array2<f64>, columns: Vec<usize>) -> Array2<f64> {
    // Create a vector of row indices (0..rows)
    let mut indices: Vec<usize> = (0..data.nrows()).collect();

    // Sort the indices based on the specified columns
    indices.sort_by(|&i, &j| {
        for &col in &columns {
            // Compare elements in the specified columns
            let ordering = data[[i, col]].partial_cmp(&data[[j, col]]).unwrap_or(Ordering::Equal);
            if ordering != Ordering::Equal {
                return ordering;
            }
        }
        Ordering::Equal
    });

    // Create a new array with rows in the sorted order
    let mut result = Array2::zeros((data.nrows(), data.ncols()));
    for (i, &idx) in indices.iter().enumerate() {
        result.row(i).assign(&data.row(idx));
    }

    result
}

