/// Sort a 2-D array (rows are records) by multiple columns (primary, secondary, ...).
///
/// - `df0` is the input 2-D array (shape: rows x cols).
/// - `cols` are the column indices to sort by in priority order (e.g. &[0, 2] sorts by column 0 then column 2).
/// - `ascending` is an optional slice of booleans indicating ascending (true) or descending (false)
///   for each corresponding column in `cols`. If `None`, all columns are sorted ascending.
///
/// Returns a new Array2<T> containing the rows of `df0` in the requested sorted order.
///
/// Notes:
/// - T must implement `PartialOrd + Clone`.
/// - Column indices are zero-based. The function will panic if any column index is out of bounds
///   or if `ascending` is provided with the wrong length.
pub fn sort_by_columns<T>(
    df0: &Array2<T>,
    cols: &[usize],
    ascending: Option<&[bool]>,
) -> Array2<T>
where
    T: PartialOrd + Clone,
{
    let (nrows, ncols) = df0.dim();

    // Nothing to do
    if cols.is_empty() || nrows <= 1 {
        return df0.to_owned();
    }

    // Validate columns
    for &c in cols {
        if c >= ncols {
            panic!("Column index {} out of bounds (ncols = {})", c, ncols);
        }
    }

    // Validate / prepare ascending flags
    let asc_flags: Vec<bool> = match ascending {
        Some(flags) => {
            if flags.len() != cols.len() {
                panic!(
                    "Length of ascending flags ({}) does not match number of columns ({})",
                    flags.len(),
                    cols.len()
                );
            }
            flags.to_vec()
        }
        None => vec![true; cols.len()],
    };

    // Create row indices and sort them according to the multi-key comparator
    let mut indices: Vec<usize> = (0..nrows).collect();
    indices.sort_by(|&i, &j| {
        for (k, &col) in cols.iter().enumerate() {
            let a = &df0[(i, col)];
            let b = &df0[(j, col)];
            match a.partial_cmp(b) {
                Some(Ordering::Less) => {
                    return if asc_flags[k] { Ordering::Less } else { Ordering::Greater }
                }
                Some(Ordering::Greater) => {
                    return if asc_flags[k] { Ordering::Greater } else { Ordering::Less }
                }
                Some(Ordering::Equal) => continue,
                // If values are not comparable (e.g. NaN), treat them as equal and continue to next key
                None => continue,
            }
        }
        Ordering::Equal
    });

    // Build the sorted array by collecting rows in the new order
    let mut data: Vec<T> = Vec::with_capacity(nrows * ncols);
    for &r in &indices {
        for c in 0..ncols {
            data.push(df0[(r, c)].clone());
        }
    }

    Array2::from_shape_vec((nrows, ncols), data).expect("shape and data length mismatch")
}

