///     1, 1, 'c' as i32,
/// ]).unwrap().mapv(|x| x as f64);
/// 
/// let sorted = sort_by_columns(&df, vec![0, 1]);
/// ```
pub fn sort_by_columns(df: &Array2<f64>, sort_cols: Vec<usize>) -> Array2<f64> {
    let nrows = df.nrows();
    let ncols = df.ncols();

    // Validate sort_cols
    for &col in &sort_cols {
        assert!(col < ncols, "Column index {} out of bounds", col);
    }
    assert!(!sort_cols.is_empty(), "Must specify at least one column to sort by");

    // Create a vector of row indices
    let mut row_indices: Vec<usize> = (0..nrows).collect();

    // Sort indices based on multiple columns
    row_indices.sort_by(|&row_a, &row_b| {
        for &col in &sort_cols {
            let val_a = df[[row_a, col]];
            let val_b = df[[row_b, col]];

            // Compare values (handling NaN cases)
            match val_a.partial_cmp(&val_b) {
                Some(std::cmp::Ordering::Equal) => continue,
                Some(ordering) => return ordering,
                None => {
                    // Handle NaN: treat NaN as greater than all numbers
                    if val_a.is_nan() && !val_b.is_nan() {
                        return std::cmp::Ordering::Greater;
                    } else if !val_a.is_nan() && val_b.is_nan() {
                        return std::cmp::Ordering::Less;
                    } else if val_a.is_nan() && val_b.is_nan() {
                        continue;
                    }
                }
            }
        }
        std::cmp::Ordering::Equal
    });

    // Build the sorted array
    let mut sorted_data = Vec::with_capacity(nrows * ncols);
    for &row_idx in &row_indices {
        for col_idx in 0..ncols {
            sorted_data.push(df[[row_idx, col_idx]]);
        }
    }

    Array2::from_shape_vec((nrows, ncols), sorted_data)
        .expect("Failed to reshape sorted data")
}

