# Rust Function for Filtering Groups in Tabular Data

```rust
use polars::prelude::*;

/// Filters a tabular dataset to retain only groups with more than one entry,
/// based on values in a specified column, and resets row indices.
///
/// # Arguments
///
/// * `df` - A Polars DataFrame containing the tabular data
/// * `group_col` - The name of the column to group by
///
/// # Returns
///
/// A new DataFrame containing only rows from groups with more than one entry,
/// with row indices reset to a continuous sequence starting from 0
///
/// # Example
///
/// ```
/// use polars::prelude::*;
///
/// let df = df!(
///     "group" => &["A", "B", "A", "C", "B"],
///     "value" => &[1, 2, 3, 4, 5],
/// ).unwrap();
///
/// let result = filter_groups_with_multiple_entries(df, "group").unwrap();
/// // Result will contain rows for groups "A" and "B" (2 entries each)
/// // but exclude group "C" (only 1 entry)
/// ```
fn filter_groups_with_multiple_entries(
    df: DataFrame,
    group_col: &str,
) -> PolarsResult<DataFrame> {
    // Count occurrences of each group
    let group_counts = df
        .clone()
        .lazy()
        .select([col(group_col)])
        .group_by([col(group_col)])
        .agg([count().alias("count")])
        .collect()?;

    // Filter to keep only groups with more than one entry
    let groups_to_keep = group_counts
        .lazy()
        .filter(col("count").gt(lit(1)))
        .select([col(group_col)])
        .collect()?;

    // Get the list of group values to keep
    let group_series = groups_to_keep.column(group_col)?;

    // Filter the original dataframe to keep only rows in those groups
    let mask = df.column(group_col)?.is_in(group_series)?;
    let filtered_df = df.filter(&mask)?;

    // Reset indices by collecting the dataframe (Polars handles this automatically)
    Ok(filtered_df)
}
```

