    batch: &RecordBatch,
    row_indices: &[usize],
    column_names: &[&str],
) -> Result<f64, String> {
    // Validate column names
    let mut selected_columns = Vec::new();
    for &column_name in column_names {
        if let Some(index) = batch.schema().index_of(column_name) {
            let column = batch.column(index);
            if matches!(column.data_type(), DataType::Float64) {
                selected_columns.push(column);
            } else {
                return Err(format!("Column {} is not of type Float64", column_name));
            }
        } else {
            return Err(format!("Column {} not found in schema", column_name));
        }
    }

    // Validate row indices
    let num_rows = batch.num_rows();
    for &row_index in row_indices {
        if row_index >= num_rows {
            return Err(format!("Row index {} out of bounds", row_index));
        }
