/// Extracts columns from a two-level hierarchical table where the second-level label matches `str0`.
///
/// # Arguments
/// * `df0` - The input table with two-level column hierarchy
/// * `str0` - The second-level label to match against
///
/// # Returns
/// A new table containing only the columns where the second-level label equals `str0`
///
/// # Example
/// ```
/// use dsv::Table;
///
/// let data = vec![
///     vec!["A", "B", "C"],
///     vec!["X", "Y", "Z"],
/// ];
///
/// let headers = vec![
///     vec!["First", "Second", "Third"],
///     vec!["Alpha", "Beta", "Gamma"],
/// ];
///
/// let mut table = Table::from_iter(data, headers);
/// let result = extract_columns_by_second_level(&mut table, "Beta").unwrap();
/// ```
pub fn extract_columns_by_second_level(df0: &mut Table, str0: &str) -> Result<Table, Box<dyn Error>> {
    // Get the column headers (which should be two-level)
    let headers = df0.headers().ok_or("Table has no headers")?;
    if headers.len() != 2 {
        return Err("Expected two-level column headers".into());
    }

    let first_level = &headers[0];
    let second_level = &headers[1];

    // Collect column indices where second-level matches str0
    let mut selected_indices = Vec::new();
    for (i, &second_label) in second_level.iter().enumerate() {
        if second_label == str0 {
            selected_indices.push(i);
        }
    }

    if selected_indices.is_empty() {
        return Err(format!("No columns found with second-level label '{}'", str0).into());
    }

    // Extract the selected columns
    let mut new_table = Table::new();

    // Copy the headers (first level only)
    new_table.headers_mut().ok_or("Failed to get headers for new table")?
        .push(first_level.clone());

    // Copy the selected second-level labels
    let mut new_second_level = Vec::new();
    for &i in &selected_indices {
        new_second_level.push(second_level[i].clone());
    }
    new_table.headers_mut().ok_or("Failed to get headers for new table")?
        .push(new_second_level);

    // Copy the data rows
    for row in df0.rows() {
        let mut new_row = Vec::new();
        for &i in &selected_indices {
            new_row.push(row[i].clone());
        }
        new_table.push_row(new_row)?;
    }

    Ok(new_table)
}
