    #[test]
    fn basic() {
        let input: Vec<char> = "a/b//c/".chars().collect();
        // Explanation: after first '/' -> 'b', after second '/' -> '/', after third '/' -> 'c', last '/' has nothing after it
        assert_eq!(chars_after_slash(&input), vec!['b', '/', 'c']);
