use nsarray::{Array, ArrayD, IxDyn};

/// Delete elements from arr0 along the specified dimension, removing every var0-th element.
///
/// # Arguments
/// * `arr0` - Input array
/// * `var0` - Remove every var0-th element (e.g., 2 removes every 2nd element)
/// * `var1` - Dimension along which to remove elements (0-indexed)
///
/// # Returns
/// A new array with the specified elements removed
///
/// # Panics
/// * If var1 is out of bounds for the array dimensions
/// * If var0 is less than 1
pub fn delete_every_nth<T: Clone + Default>(
    arr0: &ArrayD<T>,
    var0: usize,
    var1: usize,
) -> ArrayD<T> {
    assert!(var0 >= 1, "var0 must be >= 1");
    assert!(
        var1 < arr0.ndim(),
        "var1 must be less than the number of dimensions"
    );

    let shape = arr0.shape();
    let dim_size = shape[var1];

    // Calculate new dimension size after removing every var0-th element
    let new_dim_size = dim_size - (dim_size / var0);

    // Create new shape
    let mut new_shape: Vec<usize> = shape.to_vec();
    new_shape[var1] = new_dim_size;

    // Create output array
    let mut result = ArrayD::<T>::default(new_shape.clone());

    // Calculate strides for iteration
    let strides = compute_strides(shape);
    let new_strides = compute_strides(&new_shape);

    // Iterate over all elements of the output array
    for flat_idx in 0..result.len() {
        // Convert flat index to multi-dimensional indices
        let mut indices = vec![0usize; shape.len()];
        let mut remaining = flat_idx;

        for d in (0..shape.len()).rev() {
            indices[d] = remaining / new_strides[d];
            remaining %= new_strides[d];
        }

        // Adjust the index along var1 dimension to skip removed elements
        let original_idx = adjust_index(indices[var1], var0);
        indices[var1] = original_idx;

        // Get value from input array
        let src_flat_idx = indices_to_flat(&indices, strides);
        let value = arr0.as_slice().unwrap()[src_flat_idx].clone();

        // Set value in result array
        result.as_slice_mut().unwrap()[flat_idx] = value;
    }

    result
}

/// Compute strides for a given shape
fn compute_strides(shape: &[usize]) -> Vec<usize> {
    let mut strides = vec![1usize; shape.len()];
    for i in (0..shape.len() - 1).rev() {
        strides[i] = strides[i + 1] * shape[i + 1];
    }
    strides
}

/// Convert multi-dimensional indices to flat index
fn indices_to_flat(indices: &[usize], strides: &[usize]) -> usize {
    indices.iter().zip(strides.iter()).map(|(i, s)| i * s).sum()
}

/// Adjust an index along the dimension to account for removed elements
fn adjust_index(index: usize, var0: usize) -> usize {
    // For each group of var0 elements, we remove the last one
    // So we need to find the original index that maps to this new index
    let groups = index / (var0 - 1);
    let remainder = index % (var0 - 1);
    groups * var0 + remainder
}

