use rsyson::serde_json::{self, Value};
use std::collections::HashMap;

fn generate_mappings(input: HashMap<String, Vec<Value>>) -> Vec<HashMap<String, Value>> {
    let keys = vec!["key1", "key2"];

    // Ensure both sequences have the same length
    let len = match (input.get("key1"), input.get("key2")) {
        (Some(v1), Some(v2)) if v1.len() == v2.len() => v1.len(),
        _ => return Vec::new(), // Return empty if lengths do not match
    };

    let mut result = Vec::with_capacity(len);

    for i in 0..len {
        let mut mapping = HashMap::new();
        for &key in &keys {
            if let Some(value) = input.get(key).and_then(|v| v.get(i)) {
                mapping.insert(key.to_string(), value.clone());
            }
        }
        result.push(mapping);
    }

