///   Non-numeric or missing second elements are skipped.
/// - The returned Value is an array of floating-point numbers (Value constructed
///   from f64).
///
/// Example (conceptual):
/// input = [[ [1, 2.5], [3, 4] ], [ [0, 1], [2, 3] ]]  => output = [6.5, 4.0]
pub fn sum_second_elements_of_lists(input: &Value) -> Value {
    // If the input is not an array, return an empty array.
    let outer = match input.as_array() {
        Some(a) => a,
        None => return Value::from(Vec::<Value>::new()),
    };

    let mut result: Vec<Value> = Vec::with_capacity(outer.len());

    for sub in outer.iter() {
        let mut sum = 0.0_f64;

        if let Some(inner_lists) = sub.as_array() {
            for inner in inner_lists.iter() {
                if let Some(items) = inner.as_array() {
                    if items.len() > 1 {
                        // Try extracting numeric value as f64, fall back to i64.
                        if let Some(v) = items[1].as_f64() {
                            sum += v;
                        } else if let Some(i) = items[1].as_i64() {
                            sum += i as f64;
                        }
                        // Non-numeric second elements are skipped.
                    }
                }
            }
        }

        result.push(Value::from(sum));
    }

