/// A new matrix with the same dimensions as the input, containing only 0s and 1s
///
/// # Examples
/// ```
/// use balgebra::prelude::*;
/// use nalgebra::DMatrix;
///
/// let matrix = DMatrix::from_row_slice(3, 3, &[1.0, 2.0, 0.0, 3.0, 0.0, 4.0, 0.0, 5.0, 6.0]);
/// let binarized = binarize_matrix(&matrix);
/// assert_eq!(binarized, DMatrix::from_row_slice(3, 3, &[1.0, 1.0, 0.0, 1.0, 0.0, 1.0, 0.0, 1.0, 1.0]));
/// ```
pub fn binarize_matrix<T>(matrix: &DMatrix<T>) -> DMatrix<f64>
where
    T: RealField,
{
    // Create a new matrix with f64 type for the output
    let mut result = DMatrix::zeros(matrix.nrows(), matrix.ncols());

    // Iterate through each element and apply binarization
    for ((i, j), &val) in matrix.indexed_iter() {
        result[(i, j)] = if val != T::zero() { 1.0 } else { 0.0 };
    }

    result
}

