fn calculate_total(df0: &DataFrame, var1: &Value) -> f64 {
    // Filter the DataFrame based on the condition
    let filtered_df = df0.filter(|row| row.get("var0").unwrap() == var1);

    // Get the column "other_column" from the filtered DataFrame
    let series = filtered_df.column("other_column").unwrap();

    // Calculate the sum of the series
    series.sum::<f64>().unwrap_or(0.0)
}

