        vec![
            Series::new("var0", vec![Value::Int32(1), Value::Int32(2), Value::Int32(1)]),
            Series::new("other_column", vec![Value::Float64(10.0), Value::Float64(20.0), Value::Float64(30.0)]),
        ]
    ).unwrap();

    let var1 = Value::Int32(1);
    let total = calculate_total(&df0, &var1);
    println!("Total: {}", total);
}
