    let mut group_key_value: HashMap<String, Value> = HashMap::new();

    for row in table.iter_rows() {
        // Build a string key representation (works for ints & strings). Null will be "NULL".
        let key_val = &row[key_idx];
        let key_string = match key_val {
            Value::Utf8(s) => s.clone(),
            Value::Int64(i) => i.to_string(),
            Value::UInt64(u) => u.to_string(),
            Value::Null => "NULL".to_string(),
            other => format!("{}", other), // fallback display
        };

        let sums = groups.entry(key_string.clone()).or_insert_with(|| vec![0.0; numeric_col_indices.len()]);
        // store one representative Value for this key (first seen)
        group_key_value.entry(key_string.clone()).or_insert_with(|| key_val.clone());

        for (j, &col_idx) in numeric_col_indices.iter().enumerate() {
            let v = &row[col_idx];
            let as_f = match v {
                Value::Int64(i) => *i as f64,
                Value::UInt64(u) => *u as f64,
                Value::Float64(f) => *f,
                Value::Float32(f) => *f as f64,
                Value::Int32(i) => *i as f64,
                Value::Null => 0.0,
                _ => 0.0,
            };
            sums[j] += as_f;
        }
    }

    // Build new schema: keep original var0 field type if possible, other columns as Float64
    let mut out_schema: Vec<Field> = Vec::new();
    let var0_field = &schema[key_idx];
    out_schema.push(Field { name: var0_field.name.clone(), dtype: var0_field.dtype.clone() });
    for name in &numeric_col_names {
        out_schema.push(Field { name: name.clone(), dtype: DataType::Float64 });
    }

    // Build output rows: one row per group
    let mut out_rows: Vec<Vec<Value>> = Vec::with_capacity(groups.len());
    for (key_string, sums) in groups {
