        }
        // Push summed numeric columns as Float64 Values
        for sum in sums {
            out_row.push(Value::Float64(sum));
        }
        out_rows.push(out_row);
    }

    // Construct and return the new table
    arow::Table::from_rows(out_schema, out_rows)
}
