use chromo::{DataFrame, DataType, Series};
use chrono::{DateTime, NaiveDateTime, NaiveTime, TimeZone, Utc};
use std::error::Error;
use std::fmt;

#[derive(Debug)]
pub enum DateReformatError {
    ColumnNotFound(String),
    TypeMismatch(String),
    ParseError(String),
    FormatError(String),
}

impl fmt::Display for DateReformatError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            DateReformatError::ColumnNotFound(col) => write!(f, "Column '{}' not found", col),
            DateReformatError::TypeMismatch(t) => write!(f, "Expected date/time type, got '{}'", t),
            DateReformatError::ParseError(e) => write!(f, "Date parsing error: {}", e),
            DateReformatError::FormatError(e) => write!(f, "Date formatting error: {}", e),
        }
    }
}

impl Error for DateReformatError {}

/// Reformats date-time values in a column of a DataFrame
///
/// # Arguments
/// * `df` - The input DataFrame
/// * `col_name` - Name of the column containing date-time values
/// * `format_str` - The target format string (e.g., "%Y-%m-%d %H:%M:%S")
///
/// # Returns
/// A new DataFrame with the reformatted column
///
/// # Errors
/// Returns DateReformatError if:
/// - Column doesn't exist
/// - Column isn't a date/time type
/// - Date parsing fails
/// - Date formatting fails
pub fn reformat_datetime_column(
    df: DataFrame,
    col_name: &str,
    format_str: &str,
) -> Result<DataFrame, DateReformatError> {
    // Check if column exists
    if !df.column_names().contains(&col_name.to_string()) {
        return Err(DateReformatError::ColumnNotFound(col_name.to_string()));
    }

    let mut df = df.clone();

    // Get the original column
    let original_series = df
        .column(col_name)
        .ok_or_else(|| DateReformatError::ColumnNotFound(col_name.to_string()))?;

    // Check if the column is a date/time type
    let original_dtype = original_series.dtype();
    if !matches!(
        original_dtype,
        DataType::Datetime(_) | DataType::Timestamp(_)
    ) {
        return Err(DateReformatError::TypeMismatch(original_dtype.to_string()));
    }

    // Convert to Series<DateTime<Utc>> for processing
    let datetime_series: Series<DateTime<Utc>> = match original_dtype {
        DataType::Datetime(_) => original_series
            .as_any()
            .downcast_ref::<Series<DateTime<Utc>>>()
            .ok_or_else(|| DateReformatError::TypeMismatch(original_dtype.to_string()))?
            .clone(),
        DataType::Timestamp(_) => original_series
            .as_any()
            .downcast_ref::<Series<DateTime<Utc>>>()
            .ok_or_else(|| DateReformatError::TypeMismatch(original_dtype.to_string()))?
            .clone(),
        _ => return Err(DateReformatError::TypeMismatch(original_dtype.to_string())),
    };

    // Create a new series with the reformatted values
    let reformatted_series = Series::new(
        col_name,
        datetime_series
            .iter()
            .map(|dt| {
                dt.map(|dt| dt.format(format_str).to_string())
                    .unwrap_or_else(|_| "".to_string())
            })
            .collect::<Vec<String>>(),
    );

    // Replace the original column with the reformatted one
    df = df.with_column(
        chromo::prelude::replace_column(col_name, reformatted_series)
            .map_err(|e| DateReformatError::FormatError(e.to_string()))?,
    );

    Ok(df)
}
