/// Removes rows from the dataset where the specified column has missing values.
///
/// # Arguments
/// * `df0` - The input dataset to filter
/// * `col_name` - The name of the column to check for missing values
///
/// # Returns
/// A new dataset with rows where the specified column is not missing
///
/// # Example
/// ```
/// use csb::prelude::*;
/// let df = DataFrame::from_iter(vec![
///     vec!["a", "1", "x"],
///     vec!["b", "", "y"],
///     vec!["c", "2", "z"],
/// ]);
/// let filtered = remove_missing_rows(&df, "col1").unwrap();
/// ```
pub fn remove_missing_rows(df0: &DataFrame, col_name: &str) -> Result<DataFrame, Box<dyn Error>> {
    // Get the column index
    let col_idx = df0.column_index(col_name)
        .ok_or_else(|| format!("Column '{}' not found", col_name))?;

    // Get the column data
    let col_data = df0.column(col_idx)
        .ok_or_else(|| format!("Failed to get column data for '{}'", col_name))?;

    // Find indices of non-missing values
    let non_missing_indices: Vec<usize> = col_data
        .iter()
        .enumerate()
        .filter(|(_, val)| val.is_some())
        .map(|(i, _)| i)
        .collect();

    // Create a new dataset with only the non-missing rows
    let mut new_df = DataFrame::new();
    for col_idx in 0..df0.num_columns() {
        let col_data = df0.column(col_idx)
            .ok_or_else(|| format!("Failed to get column data for column {}", col_idx))?;

        let new_col: Vec<Option<Value>> = non_missing_indices
            .iter()
            .map(|&i| col_data[i])
            .collect();

        new_df.add_column(col_idx, new_col)?;
    }

    Ok(new_df)
}
