use narray::{Array1, ArrayView1};

fn assign_ranks(lst0: ArrayView1<f64>) -> Array1<usize> {
    // Create an array of indices
    let mut indices: Array1<usize> = Array1::range(0, lst0.len(), 1);

    // Sort the indices based on the values in lst0
    indices.sort_by(|&i, &j| lst0[i].partial_cmp(&lst0[j]).unwrap());

    // Create an array to store the ranks
    let mut ranks = Array1::zeros(lst0.len());

    // Assign ranks based on the sorted indices
    for (rank, &index) in indices.iter().enumerate() {
        ranks[index] = rank;
    }

    ranks
}

fn main() {
    // Example usage
    let lst0 = Array1::from_vec(vec![3.0, 1.0, 2.0, 3.0, 4.0]);
    let ranks = assign_ranks(lst0.view());
    println!("{:?}", ranks); // Output: [3, 0, 1, 4, 2]
}
