    let mut current_rank = 1;

    for i in 0..indices.len() {
        if i > 0 && lst[indices[i]] != lst[indices[i - 1]] {
            current_rank = i + 1;
        }
        ranks.set(indices[i], current_rank);
    }

    ranks
}

fn main() {
    // Example usage
    let lst0 = Array1::from_vec(vec![3.0, 1.0, 2.0, 2.0, 4.0]);
