) -> LinkedHashMap<T, String> {
    // Create a LinkedHashMap to maintain insertion order
    let mut reordered = LinkedHashMap::new();

    // Create a set for fast lookups
    let order_set: std::collections::HashSet<_> = order.iter().cloned().collect();

    // First, insert items in the order defined by the `order` list
    for id in order {
