use linked_hashmap::LinkedHashMap;
use std::cmp::Ordering;

/// Reorders the entries of `dict0` by the value associated with `var0` in each entry's value.
/// Each entry's value must be a `LinkedHashMap` containing the key `var0`.
///
/// # Arguments
/// * `dict0` - The `LinkedHashMap` to reorder.
/// * `var0` - The key whose value in each inner map will be used for ordering.
///
/// # Returns
/// A new `LinkedHashMap` with entries ordered by the specified key's value.
pub fn reorder_by_inner_key<K, V, T>(dict0: LinkedHashMap<K, LinkedHashMap<T, V>>, var0: T) -> LinkedHashMap<K, LinkedHashMap<T, V>>
where
    K: Ord + std::hash::Hash + Eq,
    T: Ord + std::hash::Hash + Eq + Clone,
    V: Ord, // Assuming we want to compare values for ordering
{
    // Collect entries into a vector for sorting
    let mut entries: Vec<_> = dict0.into_iter().collect();

    // Sort by the value associated with `var0` in each inner map
    entries.sort_by(|(_, inner1), (_, inner2)| {
        match (inner1.get(&var0), inner2.get(&var0)) {
            (Some(v1), Some(v2)) => v1.cmp(v2),
            (Some(_), None) => Ordering::Greater,
            (None, Some(_)) => Ordering::Less,
            (None, None) => Ordering::Equal,
        }
    });

    // Rebuild the LinkedHashMap in the new order
    entries.into_iter().map(|(k, v)| (k, v)).collect()
}

// Example usage:
