/// The length of the result will be lst0.len() - window_size + 1.
///
/// # Panics
/// Panics if window_size is 0 or greater than lst0.len()
pub fn moving_average(lst0: &[f64], window_size: usize) -> Vec<f64> {
    assert!(window_size > 0, "Window size must be positive");
    assert!(
        window_size <= lst0.len(),
        "Window size cannot exceed sequence length"
    );

    // Create a RolSum instance with the specified window size
    let mut rol_sum = RolSum::new(window_size);

    // Initialize with the first window_size elements
    for &value in lst0.iter().take(window_size) {
        rol_sum.add(value);
    }

    // Collect the results
    let mut result = Vec::with_capacity(lst0.len() - window_size + 1);

    // Add the first window's average
    result.push(rol_sum.sum() / window_size as f64);

    // Slide the window across the remaining elements
    for &value in lst0.iter().skip(window_size) {
        rol_sum.add(value);
        result.push(rol_sum.sum() / window_size as f64);
    }

    result
}

