pub fn repeat_along_axis(input: &Tensor, repeats: i64, axis: i64) -> Tensor {
    // Get the shape of the input tensor
    let shape: Vec<i64> = input.size();

    // Validate axis
    let axis = if axis < 0 {
        (shape.len() as i64 + axis) as usize
    } else {
        axis as usize
    };

    assert!(
