type Bool = bool;

// Define a function to compare two sequences of boolean values
fn compare_bool_sequences<T: HList, U: HList>(seq1: T, seq2: U) -> Result<HList, &'static str>
where
    T: HList,
    U: HList,
    T::Length: Eq<U::Length>,
{
    // Check if the sequences have the same length
    if T::Length::to_usize() != U::Length::to_usize() {
        return Err("Sequences must have the same length");
    }

    // Compare the sequences
    compare_bool_sequences_impl(seq1, seq2)
