fn compare_bool_sequences_impl<T: HList, U: HList>(seq1: T, seq2: U) -> HList
where
    T: HList,
    U: HList,
{
    // Base case: empty sequences
    match (seq1, seq2) {
        (HNil, HNil) => HNil,
        // Recursive case: compare the first elements and the rest of the sequences
        (HCons(a, as_), HCons(b, bs)) => HCons(a == b, compare_bool_sequences_impl(as_, bs)),
        _ => unreachable!(),
    }
