///     "event" => &["X", "Y", "X", "Y", "Z", "X"]
/// ).unwrap();
///
/// let result = group_and_count(&df, "group", "event").unwrap();
/// ```
fn group_and_count(df: &DataFrame, group_col: &str, count_col: &str) -> Result<DataFrame, Box<dyn std::error::Error>> {
