    let mut groupby = df.groupby(vec![group_col])?;

    // Count occurrences of each value in count_col within each group
    let counts = groupby
        .agg(vec![col(count_col).value_counts(true)?])?;

    // Rename the columns to be more descriptive
    let mut result = counts.rename(&[
        (count_col, "value"),
        ("value_counts", "count"),
