    // Reorder columns to have the group column first
    let group_col_idx = result.get_column_index(group_col)?;
    let value_col_idx = result.get_column_index("value")?;
    let count_col_idx = result.get_column_index("count")?;

    result = result
        .column(&[group_col_idx, value_col_idx, count_col_idx])?
        .unwrap();

    Ok(result)
}

