/// * `var1` - Ending column index (exclusive)
///
/// # Returns
/// A new 2D array containing the specified columns
///
/// # Panics
/// Panics if indices are out of bounds or if `var0 > var1`
fn extract_columns(arr0: &Array2D<f64>, var0: usize, var1: usize) -> Array2D<f64> {
