    let mut result = Array2D::new(rows, cols_to_extract);

    // Copy the specified columns
    for col in 0..cols_to_extract {
        let source_col = var0 + col;
        for row in 0..rows {
            result[(row, col)] = arr0[(row, source_col)];
        }
    }

    result
}

