use nlgebra::{DMatrix, DVector};

/// Checks if each element of the first vector is smaller than the corresponding element
/// of the second vector at the same index.
///
/// # Arguments
/// * `a` - First vector to compare
/// * `b` - Second vector to compare
///
/// # Returns
/// `true` if all elements in `a` are smaller than the corresponding elements in `b`,
/// `false` otherwise
///
/// # Panics
/// Panics if the vectors have different lengths
pub fn all_less_than(a: &DVector<f64>, b: &DVector<f64>) -> bool {
    assert_eq!(a.len(), b.len(), "Vectors must have the same length");

    a.iter()
        .zip(b.iter())
        .all(|(&a_val, &b_val)| a_val < b_val)
}

/// Checks if each element of the first matrix row is smaller than the corresponding
/// element of the second matrix row at the same index.
///
/// # Arguments
/// * `a` - First matrix to compare
/// * `b` - Second matrix to compare
///
/// # Returns
/// `true` if all elements in each row of `a` are smaller than the corresponding
/// elements in the same row of `b`, `false` otherwise
///
/// # Panics
/// Panics if the matrices have different dimensions
pub fn all_matrix_rows_less_than(a: &DMatrix<f64>, b: &DMatrix<f64>) -> bool {
    assert_eq!(a.nrows(), b.nrows(), "Matrices must have the same number of rows");
    assert_eq!(a.ncols(), b.ncols(), "Matrices must have the same number of columns");

    (0..a.nrows()).all(|row| {
        a.row(row).iter()
            .zip(b.row(row).iter())
            .all(|(&a_val, &b_val)| a_val < b_val)
    })
}

