        Some(|(_, count)| (count, count)),
        None,
    );
    println!("Ordered counts: {:?}", ordered_counts);

    // Count with limiting (top 2)
    let limited_counts = count_tuples(
        data.clone(),
        None,
        Some(|(_, count)| (count, count)),
        Some(|i| i < 2),
    );
    println!("Limited counts: {:?}", limited_counts);
}
