/// Removes consecutive duplicate rows from a DataFrame, keeping only the first occurrence.
///
/// # Arguments
/// * `df` - The input DataFrame to process
///
/// # Returns
/// A new DataFrame with consecutive duplicates removed
pub fn remove_consecutive_duplicates(df: &Frame) -> Frame {
    // Create a new empty frame with the same schema
    let mut result = Frame::new(df.schema().clone());

    // If the input is empty, return an empty frame
    if df.nrows() == 0 {
        return result;
    }

    // Add the first row unconditionally
    result.push_row(df.row(0).unwrap()).unwrap();

    // Iterate through the remaining rows
    for i in 1..df.nrows() {
        let current_row = df.row(i).unwrap();
        let prev_row = df.row(i - 1).unwrap();

        // Check if current row is different from previous row
        if !current_row.equals(&prev_row) {
            result.push_row(current_row).unwrap();
        }
    }

    result
}

