pub fn remove_columns(mat0: &Mat<f64>, columns_to_delete: impl IntoIterator<Item = usize>) -> Mat<f64> {
    let rows = mat0.rows();
    let cols = mat0.cols();

    // Build a set of valid column indices to delete
    let delete_set: HashSet<usize> = columns_to_delete
        .into_iter()
        .filter(|&c| c < cols) // ignore out-of-range indices
        .collect();

    // Collect columns to keep in increasing order
    let keep_cols: Vec<usize> = (0..cols).filter(|c| !delete_set.contains(c)).collect();
    let new_cols = keep_cols.len();

    // If no columns remain, return an empty (rows x 0) matrix
    if new_cols == 0 {
        return Mat::from_vec(rows, 0, Vec::new());
    }

    // Build row-major data for the new matrix
    let mut data: Vec<f64> = Vec::with_capacity(rows * new_cols);
    for r in 0..rows {
        for &c in &keep_cols {
            data.push(mat0[(r, c)]);
        }
    }

    Mat::from_vec(rows, new_cols, data)
}

