#[macro_use]
extern crate diesel;

use diesel::prelude::*;
use diesel::pg::PgConnection;
use dotenv::dotenv;
use std::env;

// Define the schema
table! {
    users (id) {
        id -> Int4,
        name -> Varchar,
    }
}

table! {
    posts (id) {
        id -> Int4,
        user_id -> Int4,
        title -> Varchar,
        body -> Text,
    }
}

// Allow joining the tables
joinable!(posts -> users (user_id));

// Selectable columns for each table
allow_tables_to_appear_in_same_query!(users, posts);

// Define the User struct
#[derive(Queryable, Debug)]
struct User {
    id: i32,
    name: String,
}

// Define the Post struct
