struct Post {
    id: i32,
    user_id: i32,
    title: String,
    body: String,
}

// Function to establish a database connection
fn establish_connection() -> PgConnection {
    dotenv().ok();

    let database_url = env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    PgConnection::establish(&database_url)
        .unwrap_or_else(|_| panic!("Error connecting to {}", database_url))
}

// Function to filter users with matching posts
fn filter_users_with_posts(conn: &PgConnection) -> QueryResult<Vec<User>> {
    use self::schema::users::dsl::*;
    use self::schema::posts::dsl::*;

    // Perform an inner join between users and posts on the user_id column
    let filtered_users = users.inner_join(posts.on(user_id.eq(users::id))).select(users::all).load::<User>(conn)?;

    Ok(filtered_users)
}

fn main() {
