use std::collections::HashMap;

/// Calculate the mean for each set of columns that share the same name
/// 
/// # Arguments
/// * `data` - A 2D array where rows are observations and columns are variables
/// * `column_names` - A slice of column names, one per column in the data
/// 
/// # Returns
/// A HashMap mapping column names to their mean values
/// 
/// # Panics
/// Panics if the number of column names doesn't match the number of columns in the data
pub fn mean_by_column_name(
    data: &Array2<f64>,
    column_names: &[String],
) -> HashMap<String, f64> {
    // Validate input dimensions
    assert_eq!(
        data.ncols(),
        column_names.len(),
        "Number of column names must match number of columns in data"
    );

    // Group column indices by name
    let mut column_groups: HashMap<String, Vec<usize>> = HashMap::new();
    for (col_idx, name) in column_names.iter().enumerate() {
        column_groups.entry(name.clone())
            .or_insert_with(Vec::new)
            .push(col_idx);
    }

    // Calculate mean for each group of columns
    let mut result: HashMap<String, f64> = HashMap::new();

    for (name, col_indices) in &column_groups {
        // Extract the columns for this group
        let mut group_data = Vec::new();
        for &col_idx in col_indices {
            let column: Vec<f64> = data.column(col_idx).iter().copied().collect();
            group_data.push(column);
        }

        // Calculate row-wise means across the grouped columns
        let n_rows = data.nrows();
        let n_cols_in_group = col_indices.len();

        let mut row_means = Vec::with_capacity(n_rows);
        for row_idx in 0..n_rows {
            let mut sum = 0.0;
            for col_idx in col_indices {
                sum += data[(row_idx, *col_idx)];
            }
            row_means.push(sum / n_cols_in_group as f64);
        }

        // Calculate the overall mean of the row means
        let overall_mean: f64 = row_means.iter().sum::<f64>() / n_rows as f64;
        result.insert(name.clone(), overall_mean);
    }

    result
}

