            (Value::String("a".into()), Value::Unit),
            (Value::String("b".into()), Value::String("old".into())),
            (Value::String("c".into()), Value::Option(None)),
            (Value::String("d".into()), Value::I64(42)),
        ]);

        let out = remove_nulls_and_update(input);

        assert_eq!(
            out,
            Value::Map(vec![
                (Value::String("b".into()), Value::String("updated".into())),
