/// Computes the mean of each column in a DataFrame, grouped by the specified fields.
///
/// # Arguments
/// * `df0` - The input DataFrame containing the data to be grouped and aggregated.
/// * `group_fields` - A vector of field names to group by (e.g., ["var0", "var1"]).
/// * `numeric_fields` - A vector of field names to compute the mean for (e.g., ["col1", "col2"]).
///
/// # Returns
/// A Result containing a new DataFrame with the grouped means, or an error if something goes wrong.
///
/// # Example
/// ```
/// use dsft::prelude::*;
///
/// let df0 = DataFrame::from_iter(vec![
///     ("var0", "A"), ("var1", "X"), ("col1", 1.0), ("col2", 2.0),
///     ("var0", "A"), ("var1", "Y"), ("col1", 3.0), ("col2", 4.0),
///     ("var0", "B"), ("var1", "X"), ("col1", 5.0), ("col2", 6.0),
/// ])?;
///
/// let result = compute_grouped_means(&df0, &["var0", "var1"], &["col1", "col2"])?;
/// println!("{:?}", result);
/// ```
pub fn compute_grouped_means(
    df0: &DataFrame,
    group_fields: &[&str],
    numeric_fields: &[&str],
) -> Result<DataFrame, Box<dyn Error>> {
    // Group the data by the specified fields
    let grouped = df0
        .group_by(group_fields)
        .map_err(|e| format!("Failed to group data: {}", e))?;

    // Compute the mean for each numeric field
    let mut result = DataFrame::new();
    for field in numeric_fields {
        let mean_series = grouped
            .mean(field)
            .map_err(|e| format!("Failed to compute mean for field '{}': {}", field, e))?;

        // Add the mean to the result DataFrame
        result.insert(field.to_string(), mean_series)?;
    }

    // Add the grouping fields to the result
    for field in group_fields {
        let group_series = grouped
            .get(field)
            .map_err(|e| format!("Failed to get grouping field '{}': {}", field, e))?
            .clone();

        result.insert(field.to_string(), group_series)?;
    }

    Ok(result)
}
```

