        // Create a dataset with missing values (NaN)
        let data = arr2(&[
            [1.0, f64::NAN, 3.0],
            [f64::NAN, 5.0, 6.0],
            [7.0, 8.0, f64::NAN],
        ]);

        let imputed = impute_column_means(&data);

        // Column 0: non-missing values are 1.0 and 7.0, mean = 4.0
        // Column 1: non-missing values are 5.0 and 8.0, mean = 6.5
        // Column 2: non-missing values are 3.0 and 6.0, mean = 4.5

        let expected = arr2(&[
            [1.0, 6.5, 3.0],
            [4.0, 5.0, 6.0],
