use sirted_vec::SirtedVec;
use std::cmp::Ordering;

/// Sort the entries of `dict0` first by their values, then by their keys.
/// 
/// `dict0` can be any IntoIterator of `(K, V)` (for example `HashMap::into_iter()`).
/// Returns a Vec<(K, V)> with entries sorted by (value, key).
///
/// Example:
/// ```ignore
/// // let map: HashMap<String, i32> = ...;
/// // let sorted = sort_dict0_by_value_then_key(map.into_iter());
/// ```
pub fn sort_dict0_by_value_then_key<K, V, I>(dict0: I) -> Vec<(K, V)>
where
    K: Ord,
    V: Ord,
    I: IntoIterator<Item = (K, V)>,
{
    // Create a SirtedVec that orders items by value, then by key
    let mut sv = SirtedVec::new_by(|a: &(K, V), b: &(K, V)| {
        match a.1.cmp(&b.1) {
            Ordering::Equal => a.0.cmp(&b.0),
            other => other,
        }
    });

    // Insert all items; SirtedVec keeps them in sorted order
    for item in dict0 {
        sv.push(item);
    }

    // Convert back to Vec and return
    sv.into_vec()
}
```

