fn alternate_reverse<T: Clone>(lst0: &[T], lst1: &[T]) -> Vec<T> {
    let mut result = Vec::new();
    let mut deque1 = ArrayDeque::<_, 32>::from(lst1); // Change 32 to a suitable capacity
    let mut deque2 = ArrayDeque::<_, 32>::from(lst0); // Change 32 to a suitable capacity

    // Extend the result by taking elements from both lists
    let max_len = lst0.len().max(lst1.len());
    for i in 0..max_len {
        if i < lst1.len() {
            // Add from lst1 (in reverse order)
            if let Some(element) = deque1.pop_back() {
                result.push(element);
            }
        }
        if i < lst0.len() {
            // Add from lst0 (in original order)
            if let Some(element) = deque2.pop_front() {
                result.push(element);
            }
        }
    }

    result
}

