```rust
use odermap::OrderMap;
use std::hash::Hash;

/// Sort an OrderMap<K, Vec<T>> by the element at `index` inside each Vec<T>.
///
/// - Consumes `map` and returns a new OrderMap with entries ordered by the element at `index`.
/// - If an entry's vector has no element at `index`, that entry is considered "missing" and
///   sorts before present elements for ascending order (and after for descending).
///
/// Requirements:
/// - K: key type used by OrderMap (must implement Eq + Hash)
/// - T: element type inside the vectors (must implement Ord)
pub fn sort_by_index<K, T>(
    map: OrderMap<K, Vec<T>>,
    index: usize,
    ascending: bool,
) -> OrderMap<K, Vec<T>>
where
    K: Eq + Hash,
    T: Ord,
{
    // Drain into a Vec so we can sort the entries
    let mut entries: Vec<(K, Vec<T>)> = map.into_iter().collect();

    entries.sort_by(|(_, a), (_, b)| {
        let a_elem = a.get(index);
        let b_elem = b.get(index);

        // Define ordering when elements are present or missing.
        // None < Some(...) for ascending order
        let ord = match (a_elem, b_elem) {
            (Some(x), Some(y)) => x.cmp(y),
            (Some(_), None) => std::cmp::Ordering::Greater,
            (None, Some(_)) => std::cmp::Ordering::Less,
            (None, None) => std::cmp::Ordering::Equal,
        };

        if ascending { ord } else { ord.reverse() }
    });

    // Rebuild an OrderMap in the new order
    let mut out = OrderMap::new();
    for (k, v) in entries {
        out.insert(k, v);
    }
    out
}

// Example usage:
