    let mut m: OrderMap<&str, Vec<i32>> = OrderMap::new();
    m.insert("a", vec![10, 2]);
    m.insert("b", vec![5, 9]);
    m.insert("c", vec![7]); // missing element at index 1

    // Sort by element at index 1 (the second element), ascending.
    let sorted = sort_by_index(m, 1, true);

    for (k, v) in sorted.iter() {
        println!("{} => {:?}", k, v);
    }
    // Output (ascending, missing treated as smallest):
    // c => [7]
    // a => [10, 2]
    // b => [5, 9]
}
