fn subtract_row_means(df0: &Matrix<f64>) -> Matrix<f64> {
    let n_rows = df0.nrows();
    let n_cols = df0.ncols();

    // Create a mutable copy of the input matrix
    let mut result = df0.clone();

    // Process each row
    for i in 0..n_rows {
        // Calculate the mean of the current row
        let row_sum: f64 = (0..n_cols).map(|j| df0[(i, j)]).sum();
        let row_mean = row_sum / n_cols as f64;

        // Subtract the mean from each element in the row
        for j in 0..n_cols {
            result[(i, j)] -= row_mean;
        }
    }

    result
}

