/// This function reads a tabular dataset from a file, sums the values of columns
/// with identical headers, and returns a new dataset with each header appearing
/// only once.
///
/// # Arguments
///
/// * `input_file` - The path to the input file.
/// * `output_file` - The path to the output file.
///
/// # Returns
///
/// * `Result<(), io::Error>` - An empty result if the operation is successful,
///   or an error if there's an issue reading or writing the files.
pub fn sum_columns(input_file: &str, output_file: &str) -> io::Result<()> {
    // Open the input file for reading.
    let input = File::open(input_file)?;

    // Create a Cav reader to read the input file.
    let mut reader = CavReader::new(input);

    // Read the header row from the input file.
    let headers = reader.read_header()?;

    // Create a HashMap to store the sum of each column.
    let mut sums: HashMap<String, Vec<f64>> = HashMap::new();

    // Iterate over each row in the input file.
    for row in reader {
        let row = row?;

        // Iterate over each column in the row.
        for (header, value) in headers.iter().zip(row) {
            // If the column is not in the sums HashMap, add it with a new vector.
            if !sums.contains_key(header) {
                sums.insert(header.clone(), vec![value.parse::<f64>().unwrap_or(0.0)]);
            } else {
                // Otherwise, append the value to the existing vector.
                let vec = sums.get_mut(header).unwrap();
                vec.push(value.parse::<f64>().unwrap_or(0.0));
            }
        }
    }

    // Open the output file for writing.
    let output = File::create(output_file)?;

    // Create a Cav writer to write the output file.
    let mut writer = CavWriter::new(output);

    // Write the header row to the output file.
    writer.write_header(sums.keys().cloned().collect::<Vec<String>>())?;

    // Write the summed rows to the output file.
    for vec in sums.values() {
        let sum: f64 = vec.iter().sum();
        writer.write_row(vec![format!("{}", sum)])?;
    }

    Ok(())
}

fn main() {
