/// - This example assumes the cav API exposes methods shown below:
///   DataFrame::nrows(), DataFrame::column(), DataFrame::column_mut(),
///   Series::get_f64_opt(), Series::set_f64_opt(), Series::len(), etc.
/// - Non-numeric or missing values produce None in the result. Division by zero produces None.
pub fn divide_columns_by_column(
    df: &mut cav::DataFrame,
    columns_list0: &[&str],
    column_name0: &str,
) -> Result<(), cav::Error> {
    // ensure divisor column exists
    if !df.has_column(column_name0) {
        return Err(cav::Error::ColumnNotFound(column_name0.to_string()));
    }

    let nrows = df.nrows();
    // load divisor column once as Option<f64> per row
    let divisor_series = df.column(column_name0)?;
    let mut divisor: Vec<Option<f64>> = Vec::with_capacity(nrows);
    for r in 0..nrows {
        // get_f64_opt returns Option<f64> (None for non-numeric/missing)
        divisor.push(divisor_series.get_f64_opt(r)?);
    }

    // process each target column
    for &col_name in columns_list0 {
        if !df.has_column(col_name) {
            return Err(cav::Error::ColumnNotFound(col_name.to_string()));
        }

        // borrow the target column mutably
        let mut target = df.column_mut(col_name)?;

        // make sure lengths match
        if target.len() != nrows {
            return Err(cav::Error::ShapeMismatch {
                expected: nrows,
                found: target.len(),
            });
        }

        // compute row-wise division, writing results back into the target column
        for r in 0..nrows {
            let a_opt = target.get_f64_opt(r)?;    // Option<f64>
            let b_opt = divisor[r];                // Option<f64>

            let out = match (a_opt, b_opt) {
                (Some(a), Some(b)) if b != 0.0 => Some(a / b),
                _ => None, // preserve None for missing/non-numeric or division-by-zero
            };

            target.set_f64_opt(r, out)?;
        }
    }

    Ok(())
}
