pub fn filter_groups_with_multiple_entries(
    df: &DataFrame,
    group_column: &str,
) -> Result<DataFrame, String> {
    // Check if the group column exists
    if !df.columns().contains(&group_column.to_string()) {
        return Err(format!("Column '{}' not found in DataFrame", group_column));
    }

    // Get the group column data
    let group_series = df.column(group_column)
        .ok_or_else(|| format!("Failed to access column '{}'", group_column))?;

    // Count occurrences of each group value
    let mut group_counts: HashMap<String, usize> = HashMap::new();

    for value in group_series.iter() {
        let key = match value {
            Some(v) => v.to_string(),
            None => "null".to_string(),
        };
        *group_counts.entry(key).or_insert(0) += 1;
    }

    // Identify groups with more than one entry
    let valid_groups: Vec<String> = group_counts
        .iter()
        .filter(|(_, &count)| count > 1)
        .map(|(group, _)| group.clone())
        .collect();

    // Create a set for faster lookup
    let valid_groups_set: std::collections::HashSet<String> = 
        valid_groups.into_iter().collect();

    // Filter rows that belong to valid groups
    let mut filtered_rows: Vec<Vec<Option<cav::Value>>> = Vec::new();

    for row_idx in 0..df.nrows() {
