use msplit::MSplit;
use std::collections::HashMap;

/// Transforms a nested sequence of two-element sequences into a HashMap.
/// Each inner sequence's first element becomes the key and the second element becomes the value.
///
/// # Arguments
/// * `input` - A string slice containing the nested sequence
///
/// # Returns
/// * `HashMap<String, String>` - A mapping of first elements to second elements
///
/// # Panics
/// * If any inner sequence doesn't have exactly two elements
/// * If there are duplicate keys (the last occurrence will overwrite previous ones)
///
/// # Example
/// ```
/// use std::collections::HashMap;
///
/// let input = "((a 1) (b 2) (c 3))";
/// let result = nested_sequence_to_mapping(input);
/// 
/// let mut expected = HashMap::new();
/// expected.insert("a".to_string(), "1".to_string());
/// expected.insert("b".to_string(), "2".to_string());
/// expected.insert("c".to_string(), "3".to_string());
/// 
/// assert_eq!(result, expected);
/// ```
pub fn nested_sequence_to_mapping(input: &str) -> HashMap<String, String> {
    let mut result = HashMap::new();

    // Parse the outer sequence
    let outer = MSplit::new(input)
        .expect("Failed to parse input as sequence");

    // Iterate over each inner sequence
    for inner_str in outer {
        let inner = MSplit::new(inner_str)
            .expect("Failed to parse inner sequence");

        // Collect all elements from the inner sequence
        let elements: Vec<&str> = inner.collect();

        // Ensure we have exactly two elements
        assert_eq!(
            elements.len(), 
            2, 
            "Each inner sequence must have exactly two elements, got {}: {:?}", 
            elements.len(), 
            elements
        );

        // Insert key-value pair (last occurrence wins for duplicates)
        result.insert(
            elements[0].to_string(), 
            elements[1].to_string()
        );
    }

    result
}

