/// Sorts text elements with optional descending order for specified positions.
///
/// # Arguments
/// * `elements` - A mutable slice of text elements to sort
/// * `positions` - An optional slice of integer positions that should be sorted in descending order
///
/// The function sorts elements in ascending order by default, but elements at the specified
/// positions are sorted in descending order. If positions is None, all elements are sorted
/// in ascending order.
pub fn sort_text_with_positions<'a>(
    elements: &mut [&'a str],
    positions: Option<&[usize]>,
) {
    match positions {
        None => {
            // Sort all elements in ascending order
            sort(elements);
        }
        Some(pos_list) => {
            // Create a vector of indices to track original positions
            let n = elements.len();
            let mut indices: Vec<usize> = (0..n).collect();

            // Sort indices based on the elements, with special handling for specified positions
            sort(&mut indices, |&i, &j| {
                let pos_set = pos_list;
                let i_in_pos = pos_set.contains(&i);
                let j_in_pos = pos_set.contains(&j);

                match (i_in_pos, j_in_pos) {
                    // Both in positions list: sort descending
                    (true, true) => elements[j].cmp(elements[i]),
                    // Neither in positions list: sort ascending
                    (false, false) => elements[i].cmp(elements[j]),
                    // One in positions list: the one in positions list should come after
                    (true, false) => std::cmp::Ordering::Greater,
                    (false, true) => std::cmp::Ordering::Less,
                }
            });

            // Reorder elements according to sorted indices
            let mut temp = Vec::with_capacity(n);
            for &idx in &indices {
                temp.push(elements[idx]);
            }
