/// // Result depends on the sorting implementation
/// ```
pub fn sort_with_selective_order(texts: &mut [&str], desc_positions: Option<Vec<usize>>) {
    let desc_set = desc_positions
        .map(|positions| positions.into_iter().collect::<std::collections::HashSet<_>>())
        .unwrap_or_default();

    sort_by(texts, |a, b| {
        // Get the positions of elements being compared
        let pos_a = texts.iter().position(|&x| std::ptr::eq(x, a)).unwrap_or(0);
        let pos_b = texts.iter().position(|&x| std::ptr::eq(x, b)).unwrap_or(0);

        let is_a_desc = desc_set.contains(&pos_a);
        let is_b_desc = desc_set.contains(&pos_b);

        match (is_a_desc, is_b_desc) {
            (true, true) => b.cmp(a),     // both descending
            (false, false) => a.cmp(b),   // both ascending
            (true, false) => std::cmp::Ordering::Greater,  // a is desc, b is asc
            (false, true) => std::cmp::Ordering::Less,     // a is asc, b is desc
        }
    });
}

/// Alternative implementation using indexed approach for clearer semantics
