        .map(|positions| positions.into_iter().collect::<std::collections::HashSet<_>>())
        .unwrap_or_default();

    // Create indexed pairs
    let mut indexed: Vec<(usize, &str)> = texts.iter().enumerate().map(|(i, &t)| (i, t)).collect();

    // Sort using odqsort with custom comparator
    sort_by(&mut indexed, |(idx_a, text_a), (idx_b, text_b)| {
