use breemultimap::BTreeMultiMap;

fn insert_sorted(sub_lists: &mut BTreeMultiMap<i32, i32>, new_sublist: (i32, i32)) {
    // Extracting the second element for comparison
    let (_, new_value) = new_sublist;

    // Insert while maintaining order
    let mut inserted = false;

    // Create a temporary vector to hold elements before the new one
    let mut items_to_reinsert = Vec::new();

    for (key, value) in sub_lists.iter() {
        if !inserted && value > new_value {
            sub_lists.insert(new_sublist.0, new_sublist.1);
            inserted = true;
        }
        // Push current item into the temporary vector
        items_to_reinsert.push((key.clone(), value.clone()));
    }

    // If new_sublist wasn't inserted, it should be the last
    if !inserted {
        sub_lists.insert(new_sublist.0, new_sublist.1);
    }

    // Reinsert items
    for (key, value) in items_to_reinsert {
        sub_lists.insert(key, value);
    }
}

