/// ```
pub fn label_unique_elements<T: Eq + std::hash::Hash + Clone>(input: &[T]) -> Vec<usize> {
    let mut label_map = HashMap::new();
    let mut next_label = 0;
    let mut labels = Vec::with_capacity(input.len());

