/// - The first vector contains the mean values of the specified rows.
/// - The second vector contains the mean values of the specified columns.
///
/// # Panics
/// This function will panic if any index in `row_indices` or `col_indices` is out of bounds.
fn compute_means(
    data_table: &Vec<Vec<f64>>,
    row_indices: &Vec<usize>,
    col_indices: &Vec<usize>,
) -> (Vec<f64>, Vec<f64>) {
    let mut row_means = Vec::new();
    let mut col_means = Vec::new();

    // Compute row means
    for &row_index in row_indices {
        if row_index >= data_table.len() {
            panic!("Row index {} is out of bounds", row_index);
        }
        let row = &data_table[row_index];
        let row_mean = mean(row).unwrap_or(f64::NAN);
        row_means.push(row_mean);
    }

    // Compute column means
    if !data_table.is_empty() {
        let num_cols = data_table[0].len();
