            let mut col_values = Vec::new();
            for row in data_table {
                col_values.push(row[col_index]);
            }
            let col_mean = mean(&col_values).unwrap_or(f64::NAN);
            col_means.push(col_mean);
        }
    }

    (row_means, col_means)
}

