        let is_nonzero = match v {
            Value::Int(n) => n != 0,
            Value::Float(f) => f != 0.0,
            Value::Bool(b) => b,                // true considered non-zero
            Value::Sequence(ref s) => !s.is_empty(), // non-empty sequence considered non-zero
            // For any other kind of value, treat it as non-zero
            _ => true,
        };

        if is_nonzero {
            out.push(Value::Int(i as i64));
        }
    }

    Value::Sequence(out)
}

