/// Assumes ragon::Value has at least:
/// - Value::Seq(Vec<Value>)
/// - Value::Number(f64)
pub fn inner_with_max_sum(x: &Value) -> Option<Value> {
    // Ensure top-level is a sequence
    let top_seq = match x {
        Value::Seq(v) => v,
        _ => return None,
    };

    let mut best: Option<(f64, &Vec<Value>)> = None;

