fn sort_lists_by_mapping<T: Ord + Clone>(
    lists: Vec<Vec<T>>,
    order_mapping: HashMap<T, usize>,
) -> Vec<Vec<T>> {
    // Create a vector of all unique elements to determine the full ordering
    let mut all_elements: Vec<T> = order_mapping.keys().cloned().collect();
    all_elements.sort_by(|a, b| {
        // If both elements have explicit orderings, compare their order values
        if let (Some(a_order), Some(b_order)) = (order_mapping.get(a), order_mapping.get(b)) {
            a_order.cmp(b_order)
        }
        // If one element doesn't have an ordering, it comes after the other
        else if order_mapping.contains_key(a) {
            std::cmp::Ordering::Greater
        } else if order_mapping.contains_key(b) {
            std::cmp::Ordering::Less
        }
        // If neither has an ordering, use their natural ordering
        else {
            a.cmp(b)
        }
    });

    // Create a lookup table for quick ordering
    let mut order_lookup = HashMap::new();
    for (index, element) in all_elements.iter().enumerate() {
        order_lookup.insert(element.clone(), index);
