    for (i, key) in b.iter().enumerate() {
        if needed.contains(key) && !index_map.contains_key(key) {
            index_map.insert(key.clone(), i);
            found += 1;
            if found == needed.len() {
                break;
            }
        }
    }

    // Partition A into items not in B and items in B (with their index).
    let mut not_in_b: Vec<T> = Vec::new();
    let mut in_b: Vec<(usize, T)> = Vec::new();
    for item in a.iter() {
        if let Some(&idx) = index_map.get(item) {
            in_b.push((idx, item.clone()));
        } else {
            not_in_b.push(item.clone());
        }
    }

    // Sort items that are in B according to the index found in B.
    // Use stable sort to preserve relative order among equal keys if any.
    in_b.sort_by_key(|&(idx, _)| idx);

    // Concatenate: items not in B first, then items in B in B's order.
    let mut result: Vec<T> = Vec::with_capacity(a.len());
    result.extend(not_in_b);
    result.extend(in_b.into_iter().map(|(_, v)| v));
    result
}

Example usage:

fn main() {
    let a = vec!["c", "a", "d", "b", "e"];
    let b = vec!["a", "b", "c", "d"]; // B is the desired order
    let sorted = sort_by_order(&a, &b);
    // Items not in B ("e") come first; remaining items follow the order in B: a,b,c,d
    println!("{:?}", sorted); // ["e", "a", "b", "c", "d"]
}

Notes:
- The function is generic over T: Eq + Hash + Clone.
- Complexity: O(|A|) memory, and time roughly O(|A| + scanned_prefix_of_B). If A is much smaller than B, the code only scans B until all A keys are discovered (it can stop early), so it remains efficient for very large B in common cases.

