use mergee::Merge;

/// Merges all key-value pairs from `source` into `dest`, updating `dest` with entries from `source`.
///
/// # Examples
///
/// ```
/// use mergee::Merge;
/// use std::collections::HashMap;
///
/// let mut dest = HashMap::from([("a", 1), ("b", 2)]);
/// let source = HashMap::from([("b", 3), ("c", 4)]);
///
/// merge_into(&mut dest, &source);
///
/// assert_eq!(dest, [("a", 1), ("b", 3), ("c", 4)]);
/// ```
pub fn merge_into<K, V, D, S>(dest: &mut D, source: &S)
where
    D: Merge<K, V>,
    S: IntoIterator<Item = (K, V)>,
    K: std::hash::Hash + Eq,
{
    for (key, value) in source {
        dest.merge(key, value);
    }
}
