use statistical::{mean, standard_deviation};

pub fn filter_within_std(lst0: &[f64], var0: f64) -> Vec<f64> {
    if lst0.is_empty() {
        return Vec::new();
    }

    let mu = mean(lst0);
    let sigma = standard_deviation(lst0);

    let limit = var0.abs() * sigma; // use absolute var0 so negative multipliers behave as their magnitude
    lst0
        .iter()
        .cloned()
        .filter(|x| (x - mu).abs() <= limit)
        .collect()
}

Example usage:

fn main() {
    let data = vec![10.0, 12.0, 11.5, 20.0, 9.0, 10.2];
    let filtered = filter_within_std(&data, 1.0); // keep points within 1 std dev of mean
    println!("{:?}", filtered);
}

Notes:
- If lst0 is empty the function returns an empty Vec.
- If the standard deviation is zero, only elements exactly equal to the mean will be kept.
- var0 is treated by absolute value so a negative var0 behaves like its positive magnitude. Adjust if you want to reject negative thresholds.

