```rust
use std::collections::HashMap;

/// Group the columns of a 2D table by their labels and compute the sum
/// of the values in each resulting group.
///
/// - `table`: slice of rows; each row is a Vec<f64>. All rows must have the same length.
/// - `labels`: slice of column labels; length must equal the number of columns.
///
/// Returns: Ok((group_labels, grouped_table))
/// - `group_labels` is the labels for the grouped columns in order of first appearance.
/// - `grouped_table` is a Vec of rows where each row has one value per group (the sum
///    across all original columns that share that label).
///
/// Returns Err on invalid input (mismatched row lengths or labels length).
pub fn group_columns_sum(
    table: &[Vec<f64>],
    labels: &[impl AsRef<str>],
) -> Result<(Vec<String>, Vec<Vec<f64>>), String> {
    // Quick checks
    if table.is_empty() {
        // no rows -> no data. produce empty group result (but keep label grouping computed from labels)
        // If there are labels but no rows, return zero-row grouped table.
        let mut seen = HashMap::new();
        let mut order = Vec::new();
        for lbl in labels {
            let s = lbl.as_ref().to_string();
            if !seen.contains_key(&s) {
                seen.insert(s.clone(), ());
                order.push(s);
            }
        }
        return Ok((order, Vec::new()));
    }

    let ncols = labels.len();
    if ncols == 0 {
        // no columns -> empty grouped table with same number of rows
        return Ok((Vec::new(), vec![Vec::new(); table.len()]));
    }

    // validate row lengths
    for (ridx, row) in table.iter().enumerate() {
        if row.len() != ncols {
            return Err(format!(
                "Row {} length {} does not match labels length {}",
                ridx,
                row.len(),
                ncols
            ));
        }
    }

    // Determine group order (labels in order of first appearance) and map each label to group index
    let mut label_to_group: HashMap<String, usize> = HashMap::new();
    let mut group_labels: Vec<String> = Vec::new();
    for lbl in labels {
        let s = lbl.as_ref().to_string();
        if !label_to_group.contains_key(&s) {
            let idx = group_labels.len();
            group_labels.push(s.clone());
            label_to_group.insert(s, idx);
        }
    }

    let ngroups = group_labels.len();
    // Prepare output table: same number of rows, ngroups columns initialized to 0.0
    let mut out: Vec<Vec<f64>> = vec![vec![0.0; ngroups]; table.len()];

    // Sum columns into groups
    for (col_idx, lbl) in labels.iter().enumerate() {
        let s = lbl.as_ref();
        // safe unwrap: label_to_group was built from the same labels
        let gidx = *label_to_group
            .get(s)
            .expect("label missing in label_to_group map");
        for (ridx, row) in table.iter().enumerate() {
            out[ridx][gidx] += row[col_idx];
        }
    }

    Ok((group_labels, out))
}

#[cfg(test)]
