/// Reorders a sequence of tuples based on a desired ordering sequence.
///
/// # Arguments
/// * `lst0` - A mutable vector of tuples to be reordered
/// * `lst1` - A slice defining the desired ordering (as indices)
///
/// # Panics
/// Panics if `lst1` contains indices that are out of bounds for `lst0`
/// or if `lst1` doesn't contain all indices from 0 to lst0.len()-1
pub fn reorder_by_sequence<T>(lst0: &mut Vec<T>, lst1: &[usize]) {
    // Validate that lst1 contains all valid indices
    assert_eq!(
        lst0.len(),
        lst1.len(),
        "lst1 must have the same length as lst0"
    );

    // Create a sortable vector from the indices
    let mut sortable = SortableVec::new();

    // Add each element with its desired position as the sort key
    for (new_position, &old_index) in lst1.iter().enumerate() {
        assert!(
            old_index < lst0.len(),
            "Index {} in lst1 is out of bounds for lst0 (length {})",
            old_index,
            lst0.len()
        );

        // We'll use the old_index as the value and new_position as the sort key
        // This way, when we sort by the key, elements will be in the order specified by lst1
        sortable.push((new_position, old_index));
    }

    // Sort by the first element (the new position)
    sortable.sort_by_key(|&(key, _)| key);

    // Now extract the old indices in the sorted order
    let sorted_indices: Vec<usize> = sortable.iter().map(|&(_, old_idx)| old_idx).collect();

