use streamingiterator::{StreamingIterator, StreamingIteratorExt};

/// Combine multiple input lists into a single list by following a provided sequence.
/// 
/// The `sequence` parameter specifies, at each step, which input list (by index) to draw
/// the next element from. The function stops when any input list is exhausted or when
/// the sequence ends.
///
/// # Arguments
/// * `lists` - A slice of vectors containing the input data
/// * `sequence` - A slice of indices specifying which list to draw from at each step
///
/// # Returns
/// A vector containing the combined elements in the order specified by the sequence
///
/// # Panics
/// Panics if any index in `sequence` is out of bounds for `lists`
pub fn combine_lists<T: Clone>(lists: &[Vec<T>], sequence: &[usize]) -> Vec<T> {
    // Create streaming iterators for each list
    let mut iterators: Vec<_> = lists
        .iter()
        .map(|list| list.iter().cloned().to_streaming_iterator())
        .collect();

    let mut result = Vec::new();

    // Follow the sequence, drawing one element at a time
    for &list_index in sequence {
        // Ensure the index is valid
        assert!(
            list_index < iterators.len(),
            "Sequence index {} is out of bounds (lists length: {})",
            list_index,
            iterators.len()
        );

        // Get the next element from the specified list
        match iterators[list_index].next() {
            Some(element) => result.push(element.clone()),
            None => break, // Stop if the source list is exhausted
        }
    }

    result
}

