    lst0: Option<Vec<String>>,
) -> Result<Table, TableError> {
    // Validate that either dict0 or lst0 is provided
    if dict0.is_none() && lst0.is_none() {
        return Err(TableError::InvalidInput(
            "Either dict0 or lst0 must be provided for column renaming".to_string(),
        ));
