    let original_columns = df0.columns().to_vec();

    // Determine the new column names based on the provided arguments
    let new_columns = if let Some(dict) = dict0 {
        // Apply the mapping dictionary
        original_columns
            .into_iter()
            .map(|col| dict.get(&col).cloned().unwrap_or(col))
            .collect()
    } else if let Some(lst) = lst0 {
        // Use the provided sequence (must match number of columns)
        if lst.len() != original_columns.len() {
            return Err(TableError::InvalidInput(
                "Length of lst0 must match number of columns".to_string(),
            ));
        }
