use permutohedron::Heap;

pub fn reorder_by_keys<T: Clone, K: Ord + Clone>(lst0: &[T], lst1: &[K]) -> Vec<T> {
    assert_eq!(lst0.len(), lst1.len(), "lists must have equal length");
    let n = lst0.len();
    if n == 0 {
        return Vec::new();
    }

    // sorted target of lst1
    let mut sorted_keys = lst1.to_vec();
    sorted_keys.sort();

    // generate permutations of indices and find one that makes lst1 sorted
    let mut indices: Vec<usize> = (0..n).collect();
    for perm in Heap::new(&mut indices) {
        let permuted_keys: Vec<K> = perm.iter().map(|&i| lst1[i].clone()).collect();
        if permuted_keys == sorted_keys {
            return perm.iter().map(|&i| lst0[i].clone()).collect();
        }
    }

    // Should never reach here because sorted_keys is a permutation of lst1
    unreachable!()
}

