use srd::prelude::*;

/// Combine two sequences by producing a new sequence of pairs, where each pair 
/// contains elements from the corresponding positions of the two input sequences.
/// 
/// The resulting sequence will have the length of the shorter input sequence.
/// 
/// # Arguments
/// * `seq1` - The first input sequence
/// * `seq2` - The second input sequence
/// 
/// # Returns
/// A new sequence of pairs (tuple) containing elements from corresponding positions
fn zip_sequences<T, U>(seq1: Sequence<T>, seq2: Sequence<U>) -> Sequence<(T, U)>
where
    T: Clone,
    U: Clone,
{
    let mut result = Sequence::new();

    // Get iterators for both sequences
    let iter1 = seq1.iter();
    let iter2 = seq2.iter();

    // Iterate through both sequences simultaneously
    for (item1, item2) in iter1.zip(iter2) {
        result.push((item1.clone(), item2.clone()));
    }

    result
}

// Example usage
fn main() {
    // Create two sample sequences
    let seq1 = Sequence::from(vec![1, 2, 3, 4, 5]);
    let seq2 = Sequence::from(vec!['a', 'b', 'c']);

    // Combine them
    let zipped = zip_sequences(seq1, seq2);

    // Print the result
    println!("Zipped sequence: {:?}", zipped);

    // Output: Zipped sequence: [(1, 'a'), (2, 'b'), (3, 'c')]
}
