/// Compute the sum of element-wise products of two sequences.
///
/// This function takes two sequences as input, multiplies corresponding elements,
/// and returns the sum of these products.
///
/// # Arguments
///
/// * `seq1` - The first sequence.
/// * `seq2` - The second sequence.
///
/// # Returns
///
/// The sum of element-wise products of `seq1` and `seq2`.
pub fn element_wise_product_sum(seq1: Vec<i32>, seq2: Vec<i32>) -> i32 {
    // Check if sequences have the same length
    assert_eq!(seq1.len(), seq2.len(), "Sequences must have the same length");

    // Create streams from sequences
    let stream1: Stream<i32> = Stream::from_iter(seq1.into_iter());
    let stream2: Stream<i32> = Stream::from_iter(seq2.into_iter());

    // Use zip to pair corresponding elements, multiply them, and sum the results
    stream1.zip(stream2)
        .map(|(x, y)| x * y)
        .fold(0, |acc, x| acc + x)
}

