        // Expected: all items ordered by lst1: 'a','a','b','c' then unmatched 'x','y' in original relative order
        let out = reorder_by_reference(lst0, &lst1);
        assert_eq!(out, vec!['a', 'a', 'b', 'c', 'x', 'y']);
    }
}
```

