use oad::Text;

/// Centers text within a specified total length, padding both sides with a given character.
///
/// # Arguments
/// * `text` - The original text to center
/// * `total_length` - The desired total length of the output
/// * `pad_char` - The character to use for padding on both sides
///
/// # Returns
/// A new `Text` with the original text centered and padded on both sides
///
/// # Panics
/// Panics if `total_length` is less than the length of the input text
pub fn center_pad(text: &str, total_length: usize, pad_char: char) -> Text {
    let text_len = text.len();

    // Validate that total_length is sufficient
    assert!(
        total_length >= text_len,
        "total_length ({}) must be >= text length ({})",
        total_length,
        text_len
    );

    // Calculate padding needed on each side
    let total_padding = total_length - text_len;
    let left_padding = total_padding / 2;
    let right_padding = total_padding - left_padding;

    // Create the padded string
    let mut result = String::with_capacity(total_length);

    // Add left padding
    for _ in 0..left_padding {
        result.push(pad_char);
    }

    // Add the original text
    result.push_str(text);

    // Add right padding
    for _ in 0..right_padding {
        result.push(pad_char);
    }

    Text::from(result)
}

// Example usage
fn main() {
    let centered = center_pad("Hello", 11, '-');
    println!("'{}'", centered); // Output: '---Hello---'

    let centered2 = center_pad("Rust", 10, '*');
    println!("'{}'", centered2); // Output: '***Rust***'

    let centered3 = center_pad("Hi", 5, '=');
    println!("'{}'", centered3); // Output: '=Hi=='
}
