///
/// # Arguments
///
/// * `df0`: The 2D dataset to transform.
/// * `var0`: The orientation to use for transformation.
///
/// # Returns
///
/// An `IndexMap` representing the transformed dataset.
fn transform_dataset(df0: Vec<Vec<String>>, var0: String) -> IndexMap<String, Vec<String>> {
    let mut result = IndexMap::new();

    // Check if the orientation is 'horizontal' or 'vertical'
    if var0 == "horizontal" {
        // Iterate over each row in the dataset
        for row in df0 {
            // Iterate over each element in the row
            for (index, element) in row.iter().enumerate() {
                // Use the column index as the key
                let key = format!("column_{}", index);
                // Push the element to the corresponding key in the result map
                result.entry(key).or_insert(Vec::new()).push(element.clone());
            }
        }
    } else if var0 == "vertical" {
        // Transpose the dataset
        let transposed_df0: Vec<Vec<String>> = (0..df0[0].len())
            .map(|col| df0.iter().map(|row| row[col].clone()).collect())
            .collect();

        // Iterate over each row in the transposed dataset
        for (index, row) in transposed_df0.iter().enumerate() {
            // Use the row index as the key
            let key = format!("row_{}", index);
            // Push the row to the corresponding key in the result map
            result.insert(key, row.clone());
        }
    } else {
        panic!("Invalid orientation. Please use 'horizontal' or 'vertical'.");
    }

    result
}

