    df1: DataFrame,
    lst0: &[String],
    var0: &str,
) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Validate that var0 exists in both dataframes
    if !df0.has_column(var0) || !df1.has_column(var0) {
        return Err("Key column not found in one or both dataframes".into());
    }

    // Validate that all columns in lst0 exist in df0
    for col in lst0 {
        if !df0.has_column(col) {
            return Err(format!("Column '{}' not found in df0", col).into());
        }
    }

    // Create a lookup map from df1 using var0 as key
    let mut lookup: HashMap<String, Vec<Value>> = HashMap::new();

    // Get the key column from df1
    let key_col = df1.column(var0)?;
    let key_values: Vec<String> = key_col.iter()
        .map(|v| v.to_string())
        .collect();

    // Get all other columns from df1 (excluding var0)
    let other_cols: Vec<String> = df1.columns()
        .iter()
        .filter(|c| c != &var0)
        .cloned()
        .collect();

    // Build lookup map
    for (i, key) in key_values.iter().enumerate() {
        let mut row_values = Vec::new();
        for col in &other_cols {
            let col_data = df1.column(col)?;
            row_values.push(col_data.get(i).cloned().unwrap_or(Value::Null));
        }
        lookup.insert(key.clone(), row_values);
    }

    // Build the merged result
    let mut result_columns: Vec<(String, Vec<Value>)> = Vec::new();

    // Add columns from lst0 (from df0)
    for col_name in lst0 {
        let col_data = df0.column(col_name)?;
        let values: Vec<Value> = col_data.iter().cloned().collect();
        result_columns.push((col_name.clone(), values));
    }

    // Add columns from df1 (excluding var0)
    for col_name in &other_cols {
        let mut values = Vec::new();

        // Get the key column from df0 to look up matching rows
        let df0_keys = df0.column(var0)?;
        for key_val in df0_keys.iter() {
